def blanked(text):
    return ' ' * len(text) if '\n' not in text else NOT_NL.sub(' ', text)


def docstring(text, start, tok):
    t = tok.lstrip('rRbBuUfF')
    if not t.startswith(('"""', "'''")):
        return False
    i = start - 1
    while i >= 0 and text[i] in ' \t\r\n':
        i -= 1
    return i < 0 or text[i] == ':' or (text[i] not in '=([{,+%' and '\n' in text[i:start])


def comment_free(rel, lang, text):
    """`text` con los comentarios y docstrings en blanco (mismas líneas y columnas; las cadenas se conservan), como `Src.code`: la
    fase de recogida no debe tomar modelos, tablas, rutas ni variables de ejemplos en comentarios (JSDoc `@example`, docstrings)."""
    out, last = [], 0
    for m in TOKENS['dart' if rel.endswith('.dart') else lang].finditer(text):
        tok = m.group()
        if tok[0] in '/#' or (lang == 'py' and docstring(text, m.start(), tok)):
            out.append(text[last:m.start()])
            out.append(blanked(tok))
            last = m.end()
    if not out:
        return text
    out.append(text[last:])
    return ''.join(out)


def paren(m):
    return m.start() + m.group().rfind('(')


class Src:
    consts = None
    url_builders = ()  # funciones del repo que devuelven su primer parámetro como prefijo de la URL (`buildUrl('api/x', q)`)

    def __init__(self, rel, lang, text):
        self.rel, self.lang, self.text = rel, lang, text
        code, struct, self.strings = [], [], []
        last = 0
        for m in TOKENS['dart' if rel.endswith('.dart') else lang].finditer(text):
            s, e = m.span()
            tok = m.group()
            gap = text[last:s]
            code.append(gap)
            struct.append(gap)
            if tok[0] in '/#' or (lang == 'py' and docstring(text, s, tok)):
                b = blanked(tok)
                code.append(b)
                struct.append(b)
            else:
                code.append(tok)
                struct.append(tok[0] + blanked(tok[1:-1]) + tok[-1] if len(tok) > 1 else tok)
                self.strings.append((s, e))
            last = e
        code.append(text[last:])
        struct.append(text[last:])
        self.code, self.struct = ''.join(code), ''.join(struct)
        self.ends = dict(self.strings)
        self.scope, self.assigns = None, {}
        self.nl = [m.start() for m in re.finditer('\n', text)]
        self.reg_pairs = self.reg_servers = None

    def line(self, pos):
        return bisect_left(self.nl, pos) + 1

    def skip(self, pos):
        return WS.match(self.struct, pos).end()

    def literal(self, pos):
        end = self.ends.get(pos)
        if end is None:
            return None
        tok = self.text[pos:end]
        i = next((k for k, ch in enumerate(tok) if ch in '"\'`'), None)
        if i is None:
            return None
        q = tok[i]
        body = tok[i:].rstrip('#')
        content = body[3:-3] if body.startswith(q * 3) and len(body) >= 6 else body[1:-1]
        return content, end, tok[:i], q

    def template(self, content, prefix, quote, pos=None, depth=0, env=None):
        def value(name):
            name = name.strip()
            if pos is None or not IDENT.fullmatch(name):
                return None
            return self.ident_value(name, pos, depth, env)

        content = DYNAMIC.sub('\0', interpolated(content, value))
        if self.lang != 'py' and '{{' in content:
            content = re.sub(r'\{\{.*?\}\}', '\0', content)
        if 'f' in prefix.lower() or '$' in prefix:
            content = BRACED.sub(lambda m: value(m.group()[1:-1].split(':')[0].split(',')[0]) or '\0', content)
        if self.lang == 'php' and quote == '"':
            content = PHP_VAR.sub('\0', content)
        if self.lang == 'c' and '\\(' in content:
            content = re.sub(r'\\\((?:[^()]|\([^()]*\))*\)', lambda m: value(m.group()[2:-1]) or '\0', content)
        if self.lang in ('kt', 'c') and '$' in content:
            content = re.sub(r'\$([A-Za-z_]\w*)', lambda m: value(m.group(1)) or '\0', content)
        return content

    def ident_value(self, name, pos, depth, env):
        if env and name in env:
            return env[name]
        if depth >= 3:
            return None
        key = re.sub(r'^(?:this|self)\.|^@', '', name)
        if not re.fullmatch(r'[A-Za-z_$][\w$]*', key):
            return self.const_value(key) if re.fullmatch(r'[A-Z][\w$]*(?:\.[A-Za-z_$][\w$]*)+', key) else None
        if key not in self.assigns:
            self.assigns[key] = list(re.finditer(rf'(?:(?<=\bthis\.)|(?<=\bself\.)|(?<![\w$.@])){re.escape(key)}'
                                                 rf'\s*(?::\s*[\w<>\[\]?., |]+?\s*)?:?=(?![=>~])', self.struct))
        cands = self.assigns[key]
        if self.scope:
            own = self.scope(pos)
            cands = [m for m in cands if self.scope(m.start()) in (own, None)]
        before = [m for m in cands if m.start() < pos and pos - m.start() < 3000]
        pick = before[-1] if before else (cands[0] if len(cands) == 1 else None)
        if pick is None and not self.assigns[key]:
            return self.const_value(key)
        if pick is None or pick.start() <= pos <= pick.end():
            return None
        return self.expr(pick.end(), depth + 1, env)

    def const_value(self, name):
        if '.' not in name and not re.fullmatch(r'[A-Z][A-Z0-9_]+', name):
            return None
        found = self.consts.get(name.rsplit('.', 1)[-1]) if self.consts else None
        return next(iter(found)) if found and len(found) == 1 else None

    def call_value(self, name, open_pos, depth, env):
        short = re.sub(r'^(?:this|self)\.', '', name)
        if depth >= 2 or not re.fullmatch(r'\w+', short):
            return None
        for m in re.finditer(rf'\b{re.escape(short)}\s*\(', self.struct):
            if m.end() - 1 == open_pos:
                continue
            close = self.close(m.end() - 1)
            tail = self.struct[close + 1:close + 120] if close > 0 else ''
            body = re.match(r'\s*(?::\s*[\w<>\[\]?., ]+?\s*)?(\{|=>|=(?!=)|:[ \t]*\n)', tail)
            if not body:
                continue
            params = [param_name(self.struct[a:b], self.lang) for a, b in self.args(m.end() - 1)[0]]
            start = close + 1 + body.end()
            if body.group(1) == '{':
                end = self.close(start - 1)
                rets = list(re.finditer(r'\breturn\b', self.struct[start:end])) if end > 0 else []
                if not rets:
                    return None
                start += rets[-1].end()
            elif body.group(1).startswith(':'):
                ret = re.search(r'\breturn\b', self.struct[start:start + 2000])
                if not ret:
                    return None
                start += ret.end()
            args = [self.expr(a, depth + 1, env) for a, b in self.args(open_pos)[0]]
            scope = {p: (v if v is not None else '\0') for p, v in zip(params, args) if p}
            return self.expr(start, depth + 1, scope)
        return None

    def close(self, pos):
        depth = 0
        for m in BRACKETS.finditer(self.struct, pos, min(len(self.struct), pos + MAX_SCAN)):
            depth += 1 if m.group() in '([{' else -1
            if depth == 0:
                return m.start()
        return -1

    def args(self, open_pos):
        end = self.close(open_pos)
        if end < 0:
            return [], -1
        out, depth, start = [], 0, open_pos + 1
        for m in ARGS_SPLIT.finditer(self.struct, open_pos + 1, end):
            ch = m.group()
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            elif depth == 0:
                out.append((start, m.start()))
                start = m.end()
        if self.struct[start:end].strip() or out:
            out.append((start, end))
        return out, end

    def expr(self, pos, depth=0, env=None):
        parts, p, seen = [], self.skip(pos), False
        for _ in range(10):
            lit = self.literal(p)
            if lit:
                content, end, prefix, quote = lit
                parts.append(self.template(content, prefix, quote, p, depth, env))
                p, seen = end, True
            else:
                m = EXPR.match(self.struct, p)
                if not m:
                    break
                q = self.skip(m.end())
                if q < len(self.struct) and self.struct[q] == '(':
                    end = self.close(q)
                    if end < 0:
                        break
                    name = m.group().replace('?.', '.')
                    inner = None
                    if depth < 3 and (name in WRAPPERS or name.rsplit('.', 1)[-1] in WRAPPERS or name.rsplit('.', 1)[-1] in self.url_builders):
                        inner = self.expr(q + 1, depth + 1, env)
                    elif not name.startswith('new '):
                        inner = self.call_value(name, q, depth, env)
                    parts.append(inner if inner is not None else '\0')
                    seen = seen or inner is not None
                    p = end + 1
                else:
                    name = m.group().rstrip('!')
                    inner = self.ident_value(name, p, depth, env) if not name.startswith('new ') else None
                    parts.append(inner if inner is not None else '\0')
                    seen = seen or inner is not None
                    p = m.end()
            q = self.skip(p)
            if not seen and self.lang == 'js' and self.struct.startswith('&&', q):
                # `cond && \`api/x\``: el valor es el de la derecha
                alt = self.expr(q + 2, depth + 1, env)
                if alt is not None:
                    return alt
            if not seen and self.struct.startswith('?', q) and not self.struct.startswith(('?.', '??'), q):
                alt = self.expr(q + 1, depth + 1, env)
                if alt is not None:
                    return alt
            if self.struct.startswith('+', q) and not self.struct.startswith('++', q) or (
                    self.lang == 'php' and self.struct.startswith('.', q) and not self.struct.startswith('..', q)):
                p = self.skip(q + 1)
                continue
            break
        return ''.join(parts) if seen else None


def param_name(text, lang=None):
    text = re.sub(r'\[[^\]]*\]|@\w+(?:\([^)]*\))?|<[^<>]*>', ' ', text).split('=', 1)[0].split(':', 1)[0]
    words = [w for w in re.findall(r'[A-Za-z_$][\w$]*', text) if w not in PARAM_MODIFIERS]
    return (words[0] if lang == 'go' else words[-1]) if words else None


def interpolated(content, value=None):
    out, i = [], 0
    while True:
        j = min((k for k in (content.find('${', i), content.find('#{', i)) if k >= 0), default=-1)
        if j < 0:
            return ''.join(out) + content[i:]
        depth, k = 0, j + 1
        while k < len(content):
            depth += {'{': 1, '}': -1}.get(content[k], 0)
            if depth == 0:
                break
            k += 1
        if k >= len(content):
            return ''.join(out) + content[i:j]
        expr = content[j + 2:k]
        known = value(expr) if value else None
        out.append(content[i:j] + (known if known is not None else '?' if re.search(r'''['"`]\?|['"`]&''', expr) else '\0'))
        i = k + 1


def drop_base(tpl):
    tpl = SCHEME.sub('', tpl.strip())
    if tpl.startswith('\0'):
        cut = tpl.find('/')
        tpl = tpl[cut:] if cut >= 0 else ''
    return tpl


def norm_path(path):
    path = OPTIONAL.sub(r'{\1}', path).split('?', 1)[0].split('#', 1)[0]
    segs = []
    for s in path.split('/'):
        if not s or s == '.':
            continue
        if s == '*':
            s = ':param'
        m = PARAM.search(s)
        if m:
            s = ':' + next((x for x in m.groups() if x), 'param')
        segs.append(s)
    return '/' + '/'.join(segs)


def inline_scripts(text):
    out, last = [], 0
    for m in re.finditer(r'<script\b(?![^>]*\bsrc=)[^>]*>([\s\S]*?)</script>', text, re.I):
        out.append(blanked(text[last:m.start(1)]))
        out.append(m.group(1))
        last = m.end(1)
    out.append(blanked(text[last:]))
    return ''.join(out)


def js_chain(code, pos):
    out = []
    while True:
        m = re.search(r'([A-Za-z_$][\w$]*)\s*\??\.\s*$', code[max(0, pos - 80):pos])
        if not m:
            return out[::-1]
        out.append(m.group(1))
        pos = pos - len(code[max(0, pos - 80):pos]) + m.start()


def js_open(struct, close):
    depth = 0
    for i in range(close, max(-1, close - 400), -1):
        ch = struct[i]
        if ch in ')]}':
            depth += 1
        elif ch in '([{':
            depth -= 1
            if depth == 0:
                return i
    return -1


def with_base(base, tpl):
    if not base or tpl is None or tpl.startswith('\0') or SCHEME.match(tpl):
        return tpl
    return base.rstrip('/') + '/' + tpl.lstrip('/')


def client_path(tpl):
    if not tpl:
        return None
    if re.match(r'\s*\x00+[A-Za-z_]', tpl):
        tpl = '\0/' + tpl.strip().lstrip('\0')
    if re.fullmatch(r'(?:[a-zA-Z][\w+.-]*:)?//\x00[\x00/]*', tpl.strip()):
        return '/'
    tpl = drop_base(tpl).split('?', 1)[0].split('#', 1)[0]
    tpl = re.sub(r'(?<=[A-Za-z0-9_\-])\x00+$', '', tpl)
    if tpl == '/':
        return '/'
    if not tpl or not PATHLIKE.fullmatch(tpl) or not re.search('[A-Za-z]', tpl):
        return None
    if not tpl.startswith('/'):
        if '/' not in tpl.strip('/') and not tpl.endswith('/') or re.match(r'[\w-]+\.[a-z]{2,4}(?:/|$)', tpl):
            return None
    return norm_path(tpl)


def segments(path):
    return [s.lower() if not s.startswith(':') else ':' for s in path.strip('/').split('/') if s]


def plural_word(word):
    if word.endswith('y') and word[-2:-1] not in 'aeiou':
        return word[:-1] + 'ies'
    if word.endswith(('s', 'x', 'z', 'ch', 'sh')):
        return word + 'es'
    return word + 's'


def snake(name):
    return SNAKE.sub('_', name).lower()


def plural_forms(word):
    out = {word, word + 's', word + 'es'}
    if word.endswith('y'):
        out.add(word[:-1] + 'ies')
    if word.endswith('s'):
        out.add(word[:-1])
    return out


def singularize(word):
    if word.endswith('ies'):
        return word[:-3] + 'y'
    if word.endswith(('ses', 'xes', 'ches', 'shes')):
        return word[:-2]
    if word.endswith('s') and not word.endswith('ss'):
        return word[:-1]
    return word


def grpc_service(type_name, services):
    name = type_name.rsplit('.', 1)[-1]
    for cand in (name, re.sub(r'^(?:Mutiny|Reactor|Rx\d?)', '', name)):
        for trimmed in (cand, re.sub(r'(?:Grpc|GrpcKt)?(?:Blocking|Future|Coroutine|Mutiny)?(?:Stub|Client)$', '', cand)):
            if trimmed in services:
                return trimmed
    return None


def rb_classes(rel, text):
    stack, out = [], []
    lines = text.split('\n')
    for i, line in enumerate(lines):
        m = re.match(r'^(\s*)(module|class)\s+((?:::)?[A-Z][\w]*(?:::[A-Z]\w*)*)(?:\s*<\s*((?:::)?[A-Z][\w:]*))?', line)
        ind = indent_of(line)
        if m:
            stack = [x for x in stack if x[0] < ind]
            qual = '::'.join([x[1] for x in stack] + [m.group(3).lstrip(':')])
            stack.append((ind, m.group(3).lstrip(':'), i))
            if m.group(2) == 'class':
                end = next((j for j in range(i + 1, len(lines)) if re.match(r'^\s*end\b', lines[j]) and indent_of(lines[j]) == ind),
                           len(lines) - 1)
                body = '\n'.join(lines[i:end])
                marker = bool(RB_JOB_MARK.search(body) or m.group(4) and RB_JOB_BASE.fullmatch(m.group(4).lstrip(':')))
                out.append((rel, i + 1, qual, (m.group(4) or '').lstrip(':'), marker))
        elif re.match(r'^\s*end\b', line):
            stack = [x for x in stack if x[0] < ind]
    return out


def fam_models(models, lang):
    fam = LANG_FAMILY.get(lang, lang)
    return any(f == fam for f, _ in models)


def gql_fields(body):
    out = []
    for m in re.finditer(r'(?:^|[`"\'\s{(])(query|mutation|subscription)\b[^{}]*\{|^[`"\']{1,3}\s*(\{)', body):
        op = m.group(1) or 'query'
        depth, i, start = 1, m.end(), m.end()
        expect = True
        while i < len(body) and depth:
            ch = body[i]
            if ch == '{':
                depth += 1
            elif ch == '}':
                depth -= 1
            elif ch == '(' and depth == 1:
                close = body.find(')', i)
                i = close if close > 0 else i
            elif depth == 1 and (ch.isalpha() or ch == '_') and expect:
                word = re.match(r'\w+', body[i:]).group()
                after = body[i + len(word):].lstrip()
                if after.startswith(':'):
                    i += len(word)
                    continue
                if body[max(start, i - 3):i] != '...':
                    out.append((op, word))
                i += len(word) - 1
            i += 1
    return out


def rpc_key(name):
    return name.replace('_', '').lower()


def shared(a, b):
    n = 0
    for x, y in zip(a.split('/')[:-1], b.split('/')[:-1]):
        if x != y:
            break
        n += 1
    return n


def quoted_all(text):
    return [m.group(1) for m in QUOTED.finditer(text or '')]


def first_string(text):
    m = QUOTED.search(text or '')
    return m.group(1) if m else None


def main_verbs(found):
    found = [v for v in dict.fromkeys(v.upper() for v in found) if v in VERBS or v == 'ANY']
    trimmed = [v for v in found if v not in ('HEAD', 'OPTIONS')]
    return trimmed or found or ['ANY']


def ann_path(args):
    for m in STR_LIT.finditer(args or ''):
        if m.group(1) in (None, 'value', 'path', 'template', 'url', 'uri'):
            return m.group(2) if m.group(2) is not None else m.group(3)
    return ''


def next_seg(part):
    if part.startswith('(') and part.endswith(')') or part.startswith('@'):
        return ''
    m = re.fullmatch(r'\[\[?(?:\.\.\.)?(\w+)\]?\]', part)
    return ':' + m.group(1) if m else part


def django_regex(path):
    path = path.lstrip('^').rstrip('$')
    path = re.sub(r'\(\?P<(\w+)>[^)]*\)', r'<\1>', path)
    path = re.sub(r'\(\?:[^)]*\)\??', '', path)
    path = re.sub(r'\([^)]*\)', '<param>', path)
    return path.replace('\\', '').replace('?', '').replace('$', '')


def unq(value):
    return (value or '').strip().strip('\'":[]')


def deploy_world(rel, compose=()):
    base = rel.rsplit('/', 1)[-1]
    if base.startswith(('docker-compose', 'compose.')) or rel in compose:
        return 'compose'
    if base.endswith(('.yml', '.yaml')) and not re.match(r'(?:application|bootstrap)\b', base):
        return 'manifest'
    return None


def env_key(name):
    return re.sub(r'[^A-Z0-9]+', '_', name.replace('-', '').upper()).strip('_')


def nest_version(args):
    if 'VERSION_NEUTRAL' in (args or ''):
        return 'NEUTRAL'
    return first_string(args)


def option_map(text):
    return {k: v for k, v in RAILS_OPT.findall(text or '')}


def indent_of(line):
    return len(line) - len(line.lstrip())


def yaml_blocks(lines, key, items=False):
    start = next((i for i, x in enumerate(lines) if re.match(rf'{key}:\s*(?:#.*)?$', x)), None)
    out, child = [], None
    if start is None:
        return out
    for i in range(start + 1, len(lines)):
        body = lines[i].strip()
        if not body or body.startswith('#'):
            continue
        ind = indent_of(lines[i])
        if ind == 0 and not (items and body.startswith('-')):
            break
        child = ind if child is None else child
        if ind == child and (body.startswith('- ') if items else re.match(r'[\w.\-]+\s*:\s*(?:#.*)?$', body)):
            out.append([body, i + 1, i + 1])
        elif out and ind >= child:
            out[-1][2] = i + 1
    return out


def compose_services(text):
    lines = text.split('\n')
    found, blocks = [], yaml_blocks(lines, 'services')
    if not blocks and not re.search(r'^(?:services|version|name|volumes|networks)\s*:', text, re.M):
        lines = ['services:'] + ['  ' + x for x in lines]
        blocks = [(b, line - 1, end - 1) for b, line, end in yaml_blocks(lines, 'services')]
        lines = text.split('\n')
        if not blocks or not all(re.search(r'^\s+(?:image|build)\s*:', '\n'.join(lines[line:end]), re.M) for _, line, end in blocks):
            return []
    for body, line, end in blocks:
        block = '\n'.join(lines[line:end])
        if re.search(r'^\s+(?:image|build)\s*:', block, re.M):
            found.append((body.split(':', 1)[0].strip(), line, end))
    return found


def spec_base(url):
    path = SCHEME.sub('', (url or '').strip().strip('\'"'))
    path = re.sub(r'\{[^}]*\}', '', path)
    return path.rstrip('/') if path.startswith('/') else ''


def openapi_yaml(text):
    lines = text.split('\n')
    base = re.search(r'''^basePath:\s*['"]?(/[^'"\s#]*)''', text, re.M)
    base = base.group(1).rstrip('/') if base else ''
    servers = re.search(r'^servers:\s*\n\s*-\s*url:\s*(\S+)', text, re.M)
    base = base or (spec_base(servers.group(1)) if servers else '')
    start = next((i for i, x in enumerate(lines) if re.match(r'paths:\s*(?:#.*)?$', x)), None)
    if start is None:
        return []
    ops, path, child, verb_ind, op = [], None, None, None, None
    for i in range(start + 1, len(lines)):
        raw = lines[i]
        body = raw.strip()
        if not body or body.startswith('#'):
            continue
        ind = indent_of(raw)
        if ind == 0:
            break
        child = ind if child is None else child
        if ind == child:
            m = re.match(r'''['"]?(/[^'"]*?)['"]?\s*:\s*(?:#.*)?$''', body)
            path, verb_ind, op = (m.group(1) if m else None), None, None
            continue
        if path is None:
            continue
        verb_ind = ind if verb_ind is None else verb_ind
        if ind == verb_ind:
            m = re.match(r'(get|put|post|delete|patch|head|options)\s*:\s*$', body)
            op = [i + 1, m.group(1).upper(), base + path, None, []] if m else None
            if op:
                ops.append(op)
            continue
        if op is None:
            continue
        m = re.match(r'''operationId:\s*['"]?([\w.\-]+)''', body)
        if m:
            op[3] = m.group(1)
        m = re.match(r'tags:\s*(\[[^\]]*\])?\s*$', body)
        if m and m.group(1):
            op[4] = [t.strip().strip('\'"') for t in m.group(1)[1:-1].split(',') if t.strip()]
        elif m:
            for nxt in lines[i + 1:i + 12]:
                item = re.match(r'''\s*-\s*['"]?([^'"#]+?)['"]?\s*$''', nxt)
                if not item or indent_of(nxt) < ind:
                    break
                op[4].append(item.group(1))
    return [tuple(o[:4]) + (tuple(o[4]),) for o in ops if o[3]]


def openapi_json(text):
    try:
        data = json.loads(text)
    except ValueError:
        return []
    paths = data.get('paths') if isinstance(data, dict) else None
    if not isinstance(paths, dict) or not (data.get('openapi') or data.get('swagger')):
        return []
    base = data.get('basePath') or ''
    servers = data.get('servers')
    if not base and isinstance(servers, list) and servers and isinstance(servers[0], dict):
        base = spec_base(servers[0].get('url'))
    base = str(base).rstrip('/')
    ops, pos = [], max(0, text.find('"paths"'))
    for path, item in paths.items():
        if not isinstance(item, dict):
            continue
        at = text.find(json.dumps(path), pos)
        pos = at if at >= 0 else pos
        for verb, op in item.items():
            if verb.upper() not in VERBS or not isinstance(op, dict) or not op.get('operationId'):
                continue
            vat = text.find(f'"{verb}"', pos)
            line = text.count('\n', 0, vat if vat >= 0 else pos) + 1
            tags = tuple(t for t in op.get('tags') or () if isinstance(t, str))
            ops.append((line, verb.upper(), base + path, str(op['operationId']), tags))
    return ops


class Bridges(Structural, Idioms, CrossLanguage, UrlBuilders, SchemaMaps, GeneratedClients, Generalized, JsClassClients, ConfigKeys,
              BuildModules, GoChannels, SqlIdentifiers, RepositoryFactories, DockerRefs):
    def __init__(self, root, files, g, read_source, is_test, issues=None):
        self.root, self.g, self.read_source, self.is_test = root, g, read_source, is_test
        self.files = sorted(files)
        self.fileset = set(files)
        self.issues = issues if issues is not None else Issues()
        self.by_file = defaultdict(list)
        self.short = defaultdict(list)
        self.full = defaultdict(list)
        self.owners = defaultdict(list)
        self.tables = defaultdict(list)
        self.table_classes = defaultdict(list)
        for nid, m in sorted(g.nodes.items()):
            if m.get('kind') in ('function', 'method', 'class') and m.get('file'):
                self.by_file[m['file']].append((m.get('line') or 1, m.get('end') or 0, nid))
                self.short[m['name'].rsplit('.', 1)[-1]].append(nid)
                self.full[m['name']].append(nid)
                if m['kind'] == 'method' and '.' in m['name']:
                    self.owners[m['name'].rsplit('.', 1)[0]].append(nid)
            if m.get('table'):
                self.tables[str(m['table']).lower()].append(nid)
                if m.get('kind') == 'class':
                    self.table_classes[m['name'].lower()].append(nid)
        for rel in self.by_file:
            self.by_file[rel].sort()
        self.starts = {rel: [x[0] for x in items] for rel, items in self.by_file.items()}
        self.pending, self.clients, self.mounts = [], [], defaultdict(list)
        self.reread, self.reread_size = {}, 0
        self.local = defaultdict(dict)
        self.local_at = defaultdict(dict)  # variables de grupo redefinidas (sombreado en bloques): (línea, padre, prefijo)
        self.ep_index = defaultdict(list)
        self.env_defs, self.env_uses = [], []
        self.topic_uses, self.tasks, self.task_calls = [], {}, []
        self.services, self.rpc_pending = {}, []
        self.nest, self.nest_prefix = [], []
        self.js_imports, self.django, self.test_routes = {}, {}, set()
        self.hints, self.js_bases, self.import_targets = {}, {}, None
        self.mount_links = []
        self.config_reads, self.config_keys, self.assocs = [], {}, {}
        self.kt_route_fns, self.kt_calls, self.wrappers = defaultdict(list), [], defaultdict(list)
        self.event_types, self.event_handlers = set(), []
        self.grpc_regs, self.gen_files = [], {}
        self.svc_refs, self.svc_names, self.kt_modules, self.gateway_routes = [], [], [], []
        self.models, self.table_decls, self.repos, self.dbsets, self.cache = defaultdict(list), set(), {}, {}, {}
        self.repo_methods = {}
        self.nest_versioning, self.declared_clients = [], set()
        self.route_lines, self.weak_clients, self.based = set(), [], set()
        self.proto_routes, self.grpc_impls, self.grpc_wiring = [], {}, []
        self.env_loaded, self.soft_env_uses, self.spring_props, self.env_file_refs = set(), [], [], []
        self.tracked = False
        self.svc_ports, self.port_refs, self.config_url_refs, self.xml_reads = [], [], [], []
        self.proxies, self.ext_mounts, self.aspire_refs, self.aspire_env = [], [], [], []
        self.ef_tables, self.ef_refs = [], []
        self.cm_refs, self.cm_values, self.resources = [], {}, []
        self.roots = None
        self.consts, self.topic_refs = defaultdict(set), set()
        self.sql_tables, self.sqlc, self.sqlc_rx, self.sqlc_structs = [], defaultdict(list), None, []
        self.nuxt = any(f.rsplit('/', 1)[-1].startswith('nuxt.config.') for f in files)
        self.openapi = []
        self.compose_files, self.svc_aliases = set(), []
        self.grpc_clients, self.channel_uses, self.repo_decls = [], [], []
        self.repo_tables, self.renames, self.exposed_entities = [], defaultdict(set), []
        self.variant_uses, self.variant_alias, self.queue_refs = [], {}, []
        self.trpc_routers, self.typed_msgs = [], []
        self.drizzle, self.seaorm = {}, {}
        self.rb_classes, self.job_calls, self.job_refs = [], [], []
        self.settings_fields, self.settings_reads, self.task_defs, self.task_calls_js = {}, [], defaultdict(list), []
        self.structural_init()
        self.idioms_init()
        self.generalized_init()
        self.jsc_init()
        self.cfg_init()
        self.go_init()

    def world(self, rel):
        return deploy_world(rel, self.compose_files)

    def module(self, rel):
        mid = f'm:{rel}'
        return mid if mid in self.g.nodes else None

    def owner(self, rel, line):
        items = self.by_file.get(rel)
        if items:
            i = bisect_left(self.starts[rel], line + 1) - 1
            steps = 0
            while i >= 0 and steps < 400:
                start, end, nid = items[i]
                if not end or end >= line:
                    return nid
                i -= 1
                steps += 1
        return self.module(rel)

    def pick(self, rel, cands):
        cands = sorted(set(cands))
        if len(cands) <= 1:
            return cands[0] if cands else None
        same = [c for c in cands if self.g.nodes[c]['file'] == rel]
        if len(same) == 1:
            return same[0]
        pool = same or cands
        ranked = sorted(((shared(rel, self.g.nodes[c]['file']), c) for c in pool), key=lambda x: (-x[0], x[1]))
        return ranked[0][1] if ranked[0][0] > ranked[1][0] else None

    def in_file(self, rel, name):
        cands = [n for _, _, n in self.by_file.get(rel, []) if self.g.nodes[n]['name'].rsplit('.', 1)[-1] == name]
        cands.sort(key=lambda n: (self.g.nodes[n]['kind'] == 'class', n))
        return cands[0] if cands else None

    def resolve(self, expr, rel, line=None, owner=None, hint=None):
        if hint:
            found = self.resolve(expr, rel, line, owner)
            if found and self.g.nodes[found]['file'].lower().endswith(hint.lower()):
                return found
            with_hint = self.resolve(expr, self.hint_file(hint) or rel, line, owner)
            return with_hint or found
        expr = re.sub(r'\.(?:bind|as_view)\([^)]*\)$', '', (expr or '').strip())
        if not expr:
            return None
        m = re.match(r'''^\[\s*\\?([\w\\]+)::class\s*,\s*['"](\w+)['"]\s*\]$''', expr) or \
            re.match(r'''^['"]\\?([\w\\]+)[@:](\w+)['"]$''', expr) or \
            re.match(r'''^\\?([\w\\]+)::class\s*\.\s*['"]:(\w+)['"]$''', expr)
        if m:
            if '\\' in m.group(1):
                found = self.qualified(rel, m.group(1), m.group(2))
                if found:
                    return found
            owner, name = m.group(1).rsplit('\\', 1)[-1], m.group(2)
        else:
            m = re.match(r'^\\?([\w\\]+)::class$', expr)
            if m:
                cls = m.group(1).rsplit('\\', 1)[-1]
                if '\\' in m.group(1):
                    found = self.qualified(rel, m.group(1), '__invoke') or self.qualified(rel, m.group(1), None)
                    if found:
                        return found
                return self.pick(rel, self.full.get(f'{cls}.__invoke', [])) or self.pick(rel, [
                    n for n in self.short.get(cls, []) if self.g.nodes[n]['kind'] == 'class'])
            if not re.fullmatch(r'[\w$.:>\-&*]+', expr):
                return None
            parts = [p.lstrip('$&*') for p in re.split(r'\.|::|->', expr)]
            parts = [p for p in parts if p and p not in ('this', 'self', 'static', 'cls')]
            if not parts:
                return None
            name = parts[-1]
            if len(parts) > 1 and not owner:
                owner = parts[-2]
        if owner:
            found = self.pick(rel, self.full.get(f'{owner}.{name}', [])) or self.pick(rel, [
                n for n in self.short.get(name, []) if self.g.nodes[n]['name'].endswith(f'.{owner}.{name}')])
            if found:
                return found
            if owner[:1].islower() and rel.endswith(('.go', '.py')):
                pkg = [n for n in self.short.get(name, []) if self.g.nodes[n]['kind'] == 'function'
                       and os.path.basename(os.path.dirname(self.g.nodes[n]['file'])) == owner or rel.endswith('.py')
                       and os.path.splitext(os.path.basename(self.g.nodes[n]['file']))[0] == owner]
                found = pkg[0] if len(pkg) == 1 else self.pick(rel, pkg)
                if found:
                    return found
        cands = self.short.get(name, [])
        local = [n for n in cands if self.g.nodes[n]['file'] == rel]
        if local:
            if line is not None and len(local) > 1:
                return min(local, key=lambda n: (abs(self.g.nodes[n]['line'] - line), n))
            return sorted(local)[0]
        return self.pick(rel, cands)

    def qualified(self, rel, qual, member):
        """Clase nombrada con espacio de nombres (`Client\\Servers\\ServerController`, con el prefijo `use` del fichero resuelto):
        entre las homónimas, la que vive en la carpeta que corresponde al espacio de nombres (PSR-4 y convenciones análogas)."""
        parts = [p for p in qual.split('\\') if p]
        text = self.text(rel) or ''
        use = re.search(rf'^\s*use\s+([\w\\]+\\{re.escape(parts[0])})\s*;', text, re.M) if len(parts) > 1 else None
        if use:
            parts = [p for p in use.group(1).split('\\') if p] + parts[1:]
        cls = parts[-1]
        cands = [n for n in self.short.get(cls, []) if self.g.nodes[n]['kind'] == 'class']
        if len(cands) < 2:
            return None
        dirs = [p.lower() for p in parts[:-1]]
        def score(n):
            segs = [x.lower() for x in self.g.nodes[n]['file'].split('/')[:-1]]
            k = 0
            while k < min(len(dirs), len(segs)) and dirs[-1 - k] == segs[-1 - k]:
                k += 1
            return k
        ranked = sorted(cands, key=lambda n: -score(n))
        if score(ranked[0]) == 0 or len(ranked) > 1 and score(ranked[0]) == score(ranked[1]):
            return None
        cls_node = ranked[0]
        if member is None:
            return cls_node
        meth = [n for n in self.owners.get(self.g.nodes[cls_node]['name'], []) if self.g.nodes[n]['name'].rsplit('.', 1)[-1] == member
                and self.g.nodes[n]['file'] == self.g.nodes[cls_node]['file']]
        return meth[0] if meth else None

    def hint_file(self, hint):
        if hint not in self.hints:
            low = '/' + hint.lower()
            found = sorted(f for f in self.by_file if ('/' + f.lower()).endswith(low))
            self.hints[hint] = found[0] if len(found) == 1 else None
        return self.hints[hint]

    def decl_after(self, src, pos, name):
        line = src.line(pos)
        cands = [n for s, e, n in self.by_file.get(src.rel, []) if self.g.nodes[n]['name'].rsplit('.', 1)[-1] == name
                 and line - 30 <= s <= line + 30]
        return min(cands, key=lambda n: (abs(self.g.nodes[n]['line'] - line), n)) if cands else None

    def imported(self, src, text):
        head, _, rest = text.partition('.')
        if src.lang == 'js':
            trel = self.js_import_target(src, head)
        elif src.lang == 'py' and rest:
            key = self.py_target(src, text)
            trel = key[0] if key and key[0] != src.rel else None
        else:
            trel = None
        if not trel:
            return None
        name = rest.rsplit('.', 1)[-1] if rest else self.js_imported_name(src, head)
        return (self.in_file(trel, name) if name else None) or (self.py_reexport(trel, name) if src.lang == 'py' and name else None) \
            or self.default_export(trel) or self.module(trel)

    def default_export(self, rel):
        items = self.by_file.get(rel)
        text = self.text(rel) if items and rel.endswith(tuple(k for k, v in EXT_LANG.items() if v == 'js')) else None
        m = JS_DEFAULT_FN.search(text or '')
        return self.in_file(rel, m.group(1)) if m else None

    def handler(self, src, start, end, line):
        text = src.code[start:end].strip()
        flat = src.struct[start:end].strip()
        if not flat:
            return None
        pair = re.fullmatch(r'''\[\s*([A-Z]\w*)\s*,\s*['"](\w+)['"]\s*\]''', text)
        if pair:
            return self.resolve(pair.group(2), src.rel, line, owner=pair.group(1))
        if INLINE.match(flat):
            return self.owner(src.rel, line)
        found = self.handler_named(src, start, end, line, text, flat)
        return found if found is not None else self.typed_method(src, text, start)

    def handler_named(self, src, start, end, line, text, flat):
        if re.fullmatch(r'[\w$.:>\-]+', text):
            found = self.imported(src, text)
            if found:
                return found
        found = self.resolve(text, src.rel, line)
        if found or '(' not in flat:
            return found
        inst = re.fullmatch(r'([A-Z][\w.]*)\s*\(\s*\)', text)
        if inst:
            found = self.imported(src, inst.group(1)) or self.resolve(inst.group(1), src.rel, line)
            if found:
                return found
        if '=>' in flat or re.search(r'\b(?:function|func|fn|lambda|delegate)\b', flat):
            return self.owner(src.rel, line)
        names = [m for m in ARG_NAME.finditer(src.code, start, end)
                 if not src.struct[m.end():m.end() + 1].strip().startswith('(')]
        for m in reversed(names):
            found = self.imported(src, m.group()) or self.resolve(m.group(), src.rel, line)
            if not found and '.' in m.group():
                found = self.typed_method(src, m.group(), m.start())  # `pm(hasID(a.GetCampaign), ..)` con `a *App`
            if found:
                return found
        return None

    def route(self, src, pos, recv, verbs, tpl, handler, scope='', strict=False, owner=None):
        if tpl is None:
            return
        if self.is_test(src.rel):
            self.test_routes.add(src.rel)
            return
        dynamic, tpl = '\0' in tpl, drop_base(tpl)
        if '://' in tpl or ' ' in tpl.strip() or (strict and tpl and not tpl.startswith('/')):
            return
        segs = segments(norm_path(tpl))
        if dynamic and segs and all(x == ':' for x in segs):
            return
        line = src.line(pos)
        self.route_lines.add((src.rel, line))
        self.pending.append((src.rel, line, recv or '', tuple(verbs), tpl, handler or '', scope,
                             owner or self.owner(src.rel, line) or ''))

    def client(self, src, pos, method, tpl, sym=None):
        path = client_path(tpl)
        if path is None or src.rel in self.test_routes or self.is_test(src.rel):
            return
        line = src.line(pos)
        sym = sym or self.owner(src.rel, line)
        if sym:
            self.clients.append((src.rel, line, (method or 'ANY').upper(), path, sym))
            if re.match(r'\s*(?:[a-zA-Z][\w+.-]*:)?(?://)?\x00', tpl):
                self.based.add((src.rel, line, (method or 'ANY').upper(), path, sym))

    def function_at(self, src, pos):
        nid = self.owner(src.rel, src.line(pos))
        return nid if nid and self.g.nodes[nid]['kind'] in ('function', 'method') else None

    def scopes_at(self, scopes, pos):
        return '/'.join(p.strip('/') for s, e, p in scopes if s <= pos <= e and p.strip('/'))

    def text(self, rel):
        if rel in self.cache:
            return self.cache[rel]
        if rel in self.reread:
            return self.reread[rel]
        raw = self.read_source(self.root, rel, self.issues)
        text = None if raw is None or b'\0' in raw[:8192] else raw.decode('utf-8', errors='replace')
        size = len(text or '')
        while self.reread and self.reread_size + size > 64 * 1024 * 1024:
            self.reread_size -= len(self.reread.pop(next(iter(self.reread))) or '')
        self.reread[rel] = text
        self.reread_size += size
        return text

    FINISH_PASSES = (
        'finish_trpc', 'finish_rpc_chains', 'finish_contracts', 'finish_endpoints', 'finish_router_passing', 'finish_mounts', 'finish_proxies', 'finish_url_flow',
        'finish_generated_clients', 'finish_class_clients', 'finish_clients', 'finish_sdk_callers', 'finish_table_links', 'finish_query_fields', 'finish_foreign_keys', 'finish_repo_factories',
        'finish_model_relations', 'finish_rpc', 'finish_cross_language', 'finish_flag_env', 'finish_env_idioms', 'finish_config_keys', 'finish_env',
        'finish_channels', 'finish_jobs', 'finish_variants', 'finish_typed_messages', 'finish_job_keys', 'finish_event_idioms',
        'finish_registries', 'finish_go', 'finish_generalized_events', 'finish_topics', 'finish_event_wrappers', 'finish_services', 'finish_build_modules', 'finish_docker_refs')

    def guarded(self, rel, step, fn, *args):
        """Ejecuta un paso de un fichero o una pasada final; un fallo inesperado queda como incidencia y el análisis continúa."""
        try:
            return fn(*args)
        except Exception as exc:  # noqa: BLE001 - un escáner no debe abortar todo el análisis
            self.issues.add(rel, f'flujos ({step}): {type(exc).__name__}: {exc}'[:300])
            return None

    def run(self):
        for step in ('load_protos', 'load_env_files', 'load_json_env', 'load_openapi_json'):
            self.guarded('.', step, getattr(self, step))
        sql = []
        for rel in self.files:
            lang = EXT_LANG.get(os.path.splitext(rel)[1])
            text = self.text(rel) if lang or rel.endswith('.sql') else None
            if text is None:
                continue
            if not lang:
                sql.append((rel, text))
                self.guarded(rel, 'collect_sql', self.collect_sql, rel, text)
                continue
            self.cache[rel] = text
            self.guarded(rel, 'collect', self.collect_file, rel, lang, text)
        self.guarded('.', 'entity_tables', self.entity_tables)
        self.guarded('.', 'prepare_models', self.prepare_models)
        self.guarded('.', 'finish_models', self.finish_models)
        for rel, text in sql:
            self.guarded(rel, 'scan_sql', self.scan_sql, rel, text)
        for rel in self.files:
            self.guarded(rel, 'scan', self.scan_file, rel)
        self.guarded('.', 'load_xml_sql', self.load_xml_sql)
        roots = {('/' + f).split('/app/')[0].lstrip('/') for f in self.files if '/app/' in '/' + f and f.endswith(('.scala', '.java', '.kt'))}
        for base in sorted(roots):
            rel = f'{base}/conf/routes' if base else 'conf/routes'
            if rel not in self.fileset and (self.root / rel).is_file() and self.is_tracked(rel):
                self.guarded(rel, 'scan_play_routes', self.scan_play_routes, rel)
        for step in self.FINISH_PASSES:
            self.guarded('.', step, getattr(self, step))

    def collect_file(self, rel, lang, text):
        code = comment_free(rel, lang, text)
        self.collect_models(rel, lang, code, text)
        self.collect_declared_models(rel, lang, code)
        self.collect_consts(rel, lang, code)
        self.collect_idioms(rel, lang, code)
        self.collect_generalized(rel, lang, code)

    def scan_file(self, rel):
        lang = EXT_LANG.get(os.path.splitext(rel)[1])
        name = rel.rsplit('/', 1)[-1]
        if lang:
            text = self.cache.pop(rel, None)
            if text is not None:
                self.scan(self.src(rel, lang, text))
        elif name.endswith(('.html', '.htm')) and self.module(rel):
            text = self.text(rel)
            if text and '<script' in text:
                self.scan_js_clients(self.src(rel, 'js', inline_scripts(text)), set())
        elif name.startswith(('docker-compose', 'compose.')) or name.endswith(('.yml', '.yaml', '.properties', '.conf')):
            self.scan_yaml(rel)
            if name.endswith('.conf'):
                self.scan_config_env(rel)
        elif name.endswith('.json') and not self.is_test(rel):
            self.scan_json(rel)
        elif name.endswith('.xml') and not self.is_test(rel):
            text = self.text(rel)
            if text:
                self.scan_xml_sql(rel, text)
            for m in XML_PROP.finditer(text or '') if text and len(text) < 256 * 1024 else ():
                self.xml_reads.append((rel, text.count('\n', 0, m.start()) + 1, m.group(1) or m.group(2)))
        elif name.startswith(('Dockerfile', 'Containerfile')) or name.endswith('.dockerfile'):
            self.scan_dockerfile(rel)
        elif self.module(rel) and (name.endswith(SHELLISH) or '.' not in name and self.g.nodes[f'm:{rel}'].get('lang') in ('bash', 'sh', 'shell')):
            self.scan_config_env(rel)
        elif name.endswith('.toml') and not self.is_test(rel):
            self.scan_toml(rel)
        elif (name == 'Procfile' or name.startswith('Procfile.')) and not self.is_test(rel):
            self.scan_procfile(rel)
        elif name == 'routes' and rel.endswith('conf/routes') and not self.is_test(rel):
            self.scan_play_routes(rel)

    def scan(self, src):
        lang = src.lang
        src.scope = lambda pos: self.function_at(src, pos)
        if lang == 'py':
            self.scan_py(src)
        elif lang == 'js':
            self.scan_js(src)
        elif lang == 'go':
            self.scan_go(src)
            self.scan_chained_groups(src)
        elif lang in ('java', 'kt'):
            self.scan_annotations(src)
            self.scan_java_clients(src)
            if lang == 'kt':
                self.scan_ktor(src)
        elif lang == 'cs':
            self.scan_annotations(src)
            self.scan_cs(src)
        elif lang == 'rb':
            self.scan_rb(src)
        elif lang == 'php':
            self.scan_annotations(src)
            self.scan_php(src)
        elif lang == 'rs':
            self.scan_rs(src)
        elif lang == 'ex':
            self.scan_ex(src)
        elif lang == 'c' and src.rel.endswith('.dart'):
            self.scan_dart(src)
        elif lang == 'c' and src.rel.endswith('.swift'):
            self.scan_vapor(src)
            self.scan_swift_clients(src)
        self.scan_registrations(src)
        self.scan_url_flow(src)
        self.scan_jobs(src)
        self.scan_generic_clients(src)
        self.scan_grpc(src)
        self.scan_env(src)
        self.scan_topics(src)
        self.scan_messaging(src)
        self.scan_topic_refs(src)
        self.scan_code_hosts(src)
        self.scan_env_names(src)
        self.scan_idioms(src)
        self.scan_generalized(src)
        self.scan_data(src)

    def scan_code_hosts(self, src):
        if self.is_test(src.rel):
            return
        for s, e in src.strings:
            if e - s > 400:
                continue
            content = src.text[s:e]
            if '//' in content:
                for m in HOST_REF.finditer(content):
                    host = m.group(2) or m.group(3)
                    if host and host not in ('localhost', 'www'):
                        self.svc_refs.append((src.rel, src.line(s), host, 'url'))
            if 'localhost:' in content or '127.0.0.1:' in content:
                for m in LOCAL_PORT.finditer(content):
                    self.port_refs.append((src.rel, src.line(s), m.group(1)))
        for m in CODE_HOST.finditer(src.code):
            self.svc_refs.append((src.rel, src.line(m.start()), m.group(1), 'bare'))

    def scan_env(self, src):
        rx = ENV_USES.get(src.lang)
        if src.lang in ('java', 'kt') and ('property' in src.code or 'get' in src.code or '@Value' in src.code or 'ConfigProperty' in src.code
                                           or '${' in src.code):
            for m in CONFIG_READ.finditer(src.code):
                self.config_reads.append((src.rel, src.line(m.start()), next(x for x in m.groups() if x)))
        for lib, name in ENV_LIBS.get(src.lang, []):
            for m in lib.finditer(src.code):
                self.env_uses.append((src.rel, src.line(m.start()), name))
        if src.lang == 'py' and 'BaseSettings' in src.code:
            self.py_settings(src)
        if src.lang in ('py', 'rb', 'js', 'kt', 'java', 'cs', 'go', 'ex', 'php') and not self.is_test(src.rel):
            self.scan_settings(src)
        if rx is None or not ENV_HINT.search(src.text):
            return
        if src.lang == 'rs' and 'env' in src.code:
            for m in CLAP_ENV.finditer(src.code):
                named = re.search(r'\benv\s*=\s*"(\w+)"', m.group(1))
                if not named:
                    self.env_uses.append((src.rel, src.line(m.end()), m.group(2).upper()))
        for m in rx.finditer(src.code):
            self.env_uses.append((src.rel, src.line(m.start()), next(x for x in m.groups() if x)))
        if src.lang == 'js':
            for alias, (spec, name) in self.js_import_map(src).items():
                if not re.search(r'(?:^|[$/@~#.])env(?:[/.]|$)|config/env', spec or ''):
                    continue
                if name is None or name == 'env':
                    for m in re.finditer(rf'(?<![\w$.]){re.escape(alias)}\s*\.\s*([A-Z][A-Z0-9_]+)\b', src.code):
                        self.env_uses.append((src.rel, src.line(m.start()), m.group(1)))
                elif re.fullmatch(r'[A-Z][A-Z0-9_]+', name):
                    for m in re.finditer(rf'(?<![\w$.]){re.escape(alias)}\b', src.code):
                        if not IMPORT_LINE.match(src.code[src.code.rfind('\n', 0, m.start()) + 1:m.start()]):
                            self.env_uses.append((src.rel, src.line(m.start()), name))
            for m in ENV_DESTRUCT.finditer(src.code):
                line = src.line(m.start())
                for part in m.group(1).split(','):
                    name = part.split(':')[0].split('=')[0].strip().lstrip('.')
                    if re.fullmatch(r'[A-Za-z_]\w*', name):
                        self.env_uses.append((src.rel, line, name))
            for m in ENV_SCHEMA.finditer(src.code):
                args, _ = src.args(paren(m))
                if len(args) < 2 or not src.struct[src.skip(args[1][0]):].startswith('{'):
                    continue
                inner, _ = src.args(src.skip(args[1][0]))
                for a, b in inner:
                    k = re.match(r'''\s*['"]?([A-Z][A-Z0-9_]*)['"]?\s*:''', src.code[a:b])
                    if k:
                        self.env_uses.append((src.rel, src.line(a + k.start(1)), k.group(1)))
        for m in CONFIG_GET.finditer(src.code) if src.lang in ('js', 'py', 'java', 'kt', 'cs', 'php', 'rb', 'go', 'c') else ():
            self.soft_env_uses.append((src.rel, src.line(m.start()), m.group(1)))

    def py_settings(self, src):
        lines = src.code.split('\n')
        for m in PY_SETTINGS.finditer(src.code):
            ind, start = len(m.group(1)), src.line(m.start())
            prefix = ''
            body = []
            for i in range(start, len(lines)):
                line = lines[i]
                if line.strip() and len(line) - len(line.lstrip()) <= ind:
                    break
                body.append((i + 1, line))
            child = min((len(x) - len(x.lstrip()) for _, x in body if x.strip()), default=0)
            for _, line in body:
                pm = re.search(r'''\benv_prefix\s*=\s*['"](\w*)''', line)
                prefix = pm.group(1) if pm else prefix
            for no, line in body:
                f = re.match(r'(\s*)([A-Za-z_]\w*)\s*:(?!=)', line)
                if f and len(f.group(1)) == child and f.group(2) != 'model_config':
                    self.env_uses.append((src.rel, no, (prefix + f.group(2)).upper()))
                    self.settings_fields.setdefault(f.group(2), (prefix + f.group(2)).upper())

    def scan_settings(self, src):
        if src.lang == 'rb' and re.search(r'\b(?:Hanami::Settings|Dry::Configurable|Anyway::Config)\b', src.code):
            for m in re.finditer(r'^\s*(?:setting|attr_config)\s+:(\w+)', src.code, re.M):
                self.env_uses.append((src.rel, src.line(m.start()), m.group(1).upper()))
                self.settings_fields.setdefault(m.group(1), m.group(1).upper())
        if 'ettings' in src.code or 'onfig' in src.code:
            for m in SETTINGS_READ.finditer(src.code):
                self.settings_reads.append((src.rel, src.line(m.start()), m.group(1)))

    def scan_topics(self, src):
        lang, code = src.lang, src.code
        if self.event_types and lang in ('cs', 'java', 'kt', 'js'):
            names = '|'.join(sorted(map(re.escape, self.event_types), key=len, reverse=True))
            for m in re.finditer(rf'\bnew\s+(?:[\w.]+\.)?({names})\s*(?:<[^<>()]*>)?\s*[({{]', code):
                self.topic_uses.append((m.group(1), src.rel, src.line(m.start()), 'pub', '', 'mq'))
            for m in re.finditer(rf'\b(?:AddSubscription|Subscribe|AddConsumer|SubscribeAsync)\s*<\s*(?:[\w.]+\.)?({names})\b', code):
                self.topic_uses.append((m.group(1), src.rel, src.line(m.start()), 'sub', '', 'mq'))
        for langs, guard, rx, role in TOPICS:
            if lang not in langs or guard not in code:
                continue
            for m in rx.finditer(code):
                role_here = role
                if role == 'kafka':
                    before = code[max(0, m.start() - 300):m.start()]
                    role_here = 'sub' if re.search(r'Reader|Consumer|Subscri', before) else 'pub'
                self.topic_uses.append((m.group(1), src.rel, src.line(m.start()), role_here, '', 'mq'))
        if lang == 'js':
            for rx, role, guard in ((EMIT, 'pub', 'emit('), (LISTEN, 'sub', '(')):
                if guard not in code:
                    continue
                for m in rx.finditer(code):
                    name = m.group(1)
                    if name not in COMMON_EVENTS and len(name) > 2:
                        self.topic_uses.append((name, src.rel, src.line(m.start()), role, '', 'emitter'))
        if lang == 'py' and '@' in code:
            for m in CELERY_TASK.finditer(code):
                d = PY_DEF.match(code, m.end())
                if not d or d.group(1) != 'def':
                    continue
                kw = re.search(r'''\bname\s*=\s*['"]([\w.\-:]+)''', m.group(1) or '')
                fn = self.decl_after(src, d.start(2), d.group(2))
                name = kw.group(1) if kw else d.group(2)
                if fn:
                    self.tasks.setdefault(d.group(2), name)
                    self.topic_uses.append((name, src.rel, src.line(m.start()), 'sub', fn, 'mq'))
        if lang == 'py':
            for m in CELERY_CALL.finditer(code):
                self.task_calls.append((m.group(1), src.rel, src.line(m.start())))

    def collect_models(self, rel, lang, text, raw=None):
        if self.is_test(rel):
            return
        if lang == 'rb':
            for m in RB_ASSOC.finditer(text):
                self.assocs.setdefault(m.group(1), m.group(2) or ''.join(w.capitalize() for w in singularize(m.group(1)).split('_')))
            classes = [(m.start(), m.group(1)) for m in re.finditer(r'^[ \t]*class\s+(\w+)', text, re.M)]
            for m in RB_RELATION.finditer(text):
                cls = next((n for p, n in reversed(classes) if p <= m.start()), None)
                if cls:
                    self.model_at(rel, text.count('\n', 0, m.start()) + 1, cls, m.group(1) or m.group(2), lang)
            for m in RB_SEQUEL_MODEL.finditer(text):
                self.model_at(rel, text.count('\n', 0, m.start()) + 1, m.group(1), m.group(2) or plural_word(snake(m.group(1))), lang)
            for m in RB_REPOSITORY.finditer(text):
                self.repo_tables.append((rel, text.count('\n', 0, m.start()) + 1, m.group(1) or m.group(2)))
            self.rb_classes += rb_classes(rel, text)
        for m in TABLE_RENAME.finditer(text) if 'ename' in text else ():
            old, new = [x for x in m.groups() if x][:2]
            self.renames[new.lower()].add(old.lower())
        if lang == 'py' and ('table' in text or 'models.Model' in text) or lang in ('rb', 'php') and 'class' in text:
            lines = text.split('\n')
            for i, line in enumerate(lines):
                for rx, mode in MODEL_DECL[lang]:
                    m = rx.match(line)
                    if m:
                        name = m.group(1)
                        table = name.lower() if mode == 'lower' else snake(name) if mode == 'snake' else plural_word(snake(name))
                        own = re.search(r'''^\s*(?:self\.table_name\s*=|protected\s+\$table\s*=)\s*['"](\w+)''', '\n'.join(lines[i:i + 40]), re.M)
                        self.model_at(rel, i + 1, name, own.group(1) if own and lang != 'py' else table, lang)
        if lang == 'py' and 'CreateModel' in text and '/migrations/' in f'/{rel}':
            for m in re.finditer(r'''\bCreateModel\(\s*name\s*=\s*['"](\w+)['"]''', text):
                self.table_decl(rel, text.count('\n', 0, m.start()) + 1, m.group(1), lang, snake(m.group(1)),
                                text.count('\n', 0, m.start(1)) + 1)
        if lang == 'cs' and ('CreateTable' in text or 'ToTable' in text):
            for m in re.finditer(r'''\.CreateTable\(\s*name\s*:\s*"(\w+)"''', text):
                self.table_decl(rel, text.count('\n', 0, m.start()) + 1, m.group(1), lang, end=text.count('\n', 0, m.start(1)) + 1)
            for m in re.finditer(r'''\.ToTable\(\s*"(\w+)"''', text):
                entity = re.findall(r'\b(?:Entity|EntityTypeBuilder)\s*<\s*(\w+)\s*>', text[max(0, m.start() - 3000):m.start()])
                if entity:
                    self.ef_tables.append((rel, text.count('\n', 0, m.start()) + 1, entity[-1], m.group(1)))
        if lang == 'js' and 'Table(' in text:
            for m in DRIZZLE_TABLE.finditer(text):
                self.drizzle[m.group(1)] = self.table_decl(rel, text.count('\n', 0, m.start()) + 1, m.group(1), lang, m.group(2))
        if lang == 'go' and 'ent.Schema' in text:
            for m in re.finditer(r'^type\s+(\w+)\s+struct\s*\{\s*ent\.Schema\b', text, re.M):
                self.model_at(rel, text.count('\n', 0, m.start()) + 1, m.group(1), plural_word(snake(m.group(1))), lang)
        if lang == 'php' and 'Entity' in text:
            for m in re.finditer(r'(?:#\[(?:ORM\\)?Entity\b|@ORM\\Entity\b)[\s\S]{0,400}?\bclass\s+(\w+)', text):
                named = re.search(r'''(?:ORM\\)?Table\(\s*(?:name\s*[:=]\s*)?['"](\w+)['"]''', text[m.start():m.end()])
                self.model_at(rel, text.count('\n', 0, m.end()) + 1, m.group(1), named.group(1) if named else snake(m.group(1)), lang)
        if lang == 'rs' and ('sea_orm' in text or 'table!' in text):
            for m in re.finditer(r'#\[sea_orm\([^\]]*\btable_name\s*=\s*"(\w+)"[^\]]*\]\s*(?:#\[[^\]]*\]\s*)*pub\s+struct\s+(\w+)', text):
                self.model_at(rel, text.count('\n', 0, m.start(2)) + 1, m.group(2), m.group(1), lang)
                self.seaorm[os.path.splitext(rel.rsplit('/', 1)[-1])[0]] = m.group(1)
        if lang == 'c' and rel.endswith('.swift') and ('@Model' in text or 'NSManagedObject' in text):
            for m in re.finditer(r'@Model\b\s*(?:(?:public|final|open)\s+)*class\s+(\w+)|\bclass\s+(\w+)\s*:\s*NSManagedObject\b', text):
                name = m.group(1) or m.group(2)
                self.model_at(rel, text.count('\n', 0, m.start()) + 1, name, name, lang)
        if lang == 'c' and rel.endswith('.dart') and 'extends Table' in text:
            for m in re.finditer(r'\bclass\s+(\w+)\s+extends\s+Table\b', text):
                self.model_at(rel, text.count('\n', 0, m.start()) + 1, m.group(1), snake(m.group(1)), lang)
        if lang == 'c' and rel.endswith('.dart') and ('@' in text or 'tableName' in text):
            for m in DART_MODEL.finditer(text):
                named = re.search(r'''\b(?:tableName|name)\s*:\s*['"](\w+)['"]''', m.group(2) or '')
                self.model_at(rel, text.count('\n', 0, m.start(3)) + 1, m.group(3),
                              named.group(1) if named else plural_word(snake(m.group(3))), lang)
            for m in DART_TABLE_NAME.finditer(text):
                self.table_decl(rel, text.count('\n', 0, m.start()) + 1, m.group(1), lang)
        head = (raw or text)[:400]  # la cabecera «Code generated by sqlc» es un comentario
        if lang == 'go' and 'sqlc' in head and GENERATED.search(head):
            self.sqlc_structs += [(rel, text.count('\n', 0, m.start()) + 1, m.group(1))
                                  for m in re.finditer(r'^type\s+(\w+)\s+struct\s*\{', text, re.M)]
        if lang in ('js', 'kt', 'go'):
            for rx, mode in MODEL_DECL[lang]:
                if mode == 'mongoose' and 'mongoose' not in text:
                    continue
                for m in rx.finditer(text):
                    line = text.count('\n', 0, m.start()) + 1
                    if mode == 'mongoose':
                        self.model_at(rel, line, m.group(1), m.group(3) or plural_word(m.group(2).lower()), lang, declare=True)
                    elif mode == 'define':
                        self.model_at(rel, line, m.group(1), m.group(2), lang, declare=True)
                    elif mode == 'typeorm':
                        self.model_at(rel, line, m.group(2), m.group(1) or snake(m.group(2)), lang)
                    elif mode == 'exposed':
                        self.model_at(rel, line, m.group(1), m.group(2) or re.sub(r'Table$', '', m.group(1)) or m.group(1), lang)
                    else:
                        self.model_at(rel, line, m.group(1), m.group(2), lang)
        if lang == 'kt' and 'EntityClass' in text:
            for m in EXPOSED_ENTITY.finditer(text):
                self.exposed_entities.append((rel, text.count('\n', 0, m.start()) + 1, m.group(1), m.group(2)))
        if lang in ('java', 'kt'):
            if '@Entity' in text or '@Document' in text or '@MongoEntity' in text or '@Table' in text:
                for m in JPA_ENTITY.finditer(text):
                    table = JPA_TABLE.search(m.group(2) or '') or re.search(r'''\b(?:tableName|collection|value|name)\s*=\s*"(\w+)"''', m.group(1) or '') \
                        or re.fullmatch(r'''\s*"(\w+)"\s*''', m.group(1) or '')
                    self.model_at(rel, text.count('\n', 0, m.start()) + 1, m.group(3), table.group(1) if table else m.group(3), lang)
            for m in JPA_REPO.finditer(text):
                self.repos.setdefault(m.group(1), m.group(2))
                self.repo_decls.append((rel, text.count('\n', 0, m.start()) + 1, LANG_FAMILY.get(lang, lang), m.group(2)))
                brace = text.find('{', m.end())
                body = text[brace:brace + 20000] if brace > 0 else ''
                for r in re.finditer(r'(?:^|[;{}\n])\s*(?:@\w+(?:\([^)]*\))?\s*)*([\w<>,.? \[\]]+?)\s+(\w+)\s*\(', body):
                    self.repo_methods[(m.group(1), r.group(2))] = re.findall(r'[A-Z]\w*', r.group(1))
        if lang in ('cs', 'java', 'kt', 'js') and ('Handler' in text or 'Event' in text or 'Consumer' in text or 'IHandle' in text):
            for m in EVENT_HANDLER.finditer(text):
                self.event_handlers.append((m.group(2), m.group(1), rel))
                self.event_types.add(m.group(2))
            for m in EVENT_TYPE.finditer(text):
                self.event_types.add(m.group(1))
        if lang == 'cs':
            for m in EF_DBSET.finditer(text):
                self.dbsets.setdefault(m.group(2), (m.group(1), rel))
            for m in CS_TABLE_ATTR.finditer(text):
                self.model_at(rel, text.count('\n', 0, m.start()) + 1, m.group(2), m.group(1), lang)
        if lang == 'ex' and 'schema' in text:
            mods = [(m.start(), m.group(1)) for m in EX_DEFMODULE.finditer(text)]
            for m in ECTO_SCHEMA.finditer(text):
                mod = next((n for p, n in reversed(mods) if p < m.start()), None)
                if mod:
                    self.model_at(rel, text.count('\n', 0, m.start()) + 1, mod, m.group(1), lang)
        rx = TABLE_DECL.get(lang)
        if rx and rx.search(text):
            for m in rx.finditer(text):
                self.table_decl(rel, text.count('\n', 0, m.start()) + 1, next(x for x in m.groups() if x), lang)

    def table_decl(self, rel, line, name, lang, table=None, end=None):
        nid = f'c:{rel}:{name}'
        if nid in self.g.nodes and nid not in self.table_decls and not self.g.nodes[nid].get('table'):
            nid = f'c:{rel}:{name}#table'
        if nid not in self.g.nodes:
            self.declare(nid, 'class', name, rel, line)
            self.g.nodes[nid].update(table=table or name, end=max(line, end or line), lang=lang)
            self.table_decls.add(nid)
            self.tables[(table or name).lower()].append(nid)
        return nid

    def model_at(self, rel, line, name, table, lang, declare=False):
        short = name.rsplit('.', 1)[-1]
        cands = [n for s, e, n in self.by_file.get(rel, []) if self.g.nodes[n]['kind'] == 'class'
                 and self.g.nodes[n]['name'].rsplit('.', 1)[-1] == short]
        nid = min(cands, key=lambda n: (abs((self.g.nodes[n].get('line') or 0) - line), n)) if cands else None
        if nid is None and declare:
            nid = self.declare(f'c:{rel}:{short}', 'class', short, rel, line)
            self.g.nodes[nid].update(end=line, lang=lang)
        if nid is None:
            return
        meta = self.g.nodes[nid]
        if not meta.get('table'):
            meta['table'] = table
            self.tables[table.lower()].append(nid)
        self.table_classes[short.lower()].append(nid)
        self.models[(LANG_FAMILY.get(lang, lang), short)].append(nid)

    def finish_models(self):
        for new, olds in sorted(self.renames.items()):
            if not any(n in self.table_decls for n in self.tables.get(new, [])):
                self.tables[new] += [n for old in sorted(olds) for n in self.tables.get(old, []) if n in self.table_decls]
        for prop, (entity, rel) in sorted(self.dbsets.items()):
            self.model_named(entity, rel, prop, 'cs')
        for rel, line, entity, table in sorted(set(self.ef_tables)):
            self.model_named(entity, rel, table, 'cs')
            for nid in self.models.get(('cs', entity), []):
                if str(self.g.nodes[nid].get('table')).lower() != table.lower():
                    self.g.nodes[nid]['table'] = table
                    self.tables[table.lower()].append(nid)
            self.ef_refs.append((rel, line, table))
        for rel, line, entity, table_obj in self.exposed_entities:
            objs = self.models.get(('java', table_obj), [])
            obj = objs[0] if len(objs) == 1 else self.pick(rel, objs)
            table = self.g.nodes[obj].get('table') if obj else None
            self.model_at(rel, line, entity, table or table_obj, 'kt')
            ent = self.model_targets('java', entity, rel)
            if obj and ent and ent[0] != obj:
                self.g.edge(ent[0], obj, 'data')
        known = {n for ns in self.models.values() for n in ns}
        for nid in sorted({n for ns in self.table_classes.values() for n in ns} - known - self.table_decls):
            meta = self.g.nodes[nid]
            ext = os.path.splitext(meta.get('file') or '')[1]
            lang = EXT_LANG.get(ext) or SCHEMA_EXT.get(ext)
            if lang and not self.is_test(meta['file']):
                self.models[(LANG_FAMILY.get(lang, lang), meta['name'].rsplit('.', 1)[-1])].append(nid)
        self.link_named_structs()
        for key in list(self.tables):
            self.tables[key] = sorted(set(self.tables[key]))
        decls = defaultdict(list)
        for key, ns in sorted(self.tables.items()):
            for nid in ns:
                if (nid in self.table_decls or self.g.nodes[nid].get('file', '').endswith('.sql')) and not self.is_test(self.g.nodes[nid]['file']):
                    decls[key].append(nid)
        for nid in sorted({n for ns in self.models.values() for n in ns}):
            meta = self.g.nodes[nid]
            found = [t for t in decls.get(str(meta['table']).lower(), []) if self.g.nodes[t]['file'] != meta['file']
                     and self.same_project(meta['file'], self.g.nodes[t]['file'])]
            best = self.pick(meta['file'], found) if len(found) > 1 else (found[0] if found else None)
            for t in [best] if best else found[:3]:
                self.g.edge(nid, t, 'data')
        for rel, line, table in self.repo_tables:
            sym = self.owner(rel, line)
            found = [n for n in self.tables.get(table.lower(), []) if n not in self.table_decls and n != sym
                     and self.same_project(rel, self.g.nodes[n]['file'])] or self.sql_targets(table, rel)
            for t in found[:2] if sym else ():
                self.g.edge(sym, t, 'data')
        for rel, line, fam, entity in self.repo_decls:
            sym = self.owner(rel, line)
            for t in self.model_targets(fam, entity, rel) if sym else ():
                if t != sym:
                    self.g.edge(sym, t, 'data')
        for rel, line, table in self.ef_refs:
            sym = self.owner(rel, line)
            found = decls.get(table.lower(), [])
            best = self.pick(rel, found) if len(found) > 1 else (found[0] if found else None)
            if sym and best:
                self.g.edge(sym, best, 'data')
        self.model_rx = {}
        for (fam, short), nids in self.models.items():
            self.model_rx.setdefault(fam, set()).add(short)
        self.model_rx = {fam: re.compile(r'(?<![\w.$])(' + '|'.join(sorted(map(re.escape, names), key=len, reverse=True)) + r')\b')
                         for fam, names in self.model_rx.items()}

    def link_named_structs(self):
        for rel, line, name in self.sqlc_structs:
            key = snake(name)
            found = [(nid, table) for nid, schema, table in self.sql_tables
                     if key in (table, singularize(table)) or schema and key in (f'{schema}_{table}', f'{schema}_{singularize(table)}')]
            tables = sorted({t for _, t in found})
            if len(tables) == 1:
                self.model_at(rel, line, name, tables[0], 'go')

    def model_named(self, name, near, table, lang):
        cands = [n for n in self.short.get(name, []) if self.g.nodes[n]['kind'] == 'class'
                 and EXT_LANG.get(os.path.splitext(self.g.nodes[n]['file'])[1]) == lang]
        if len(cands) > 1:
            cands = [n for n in cands if not self.migration_class(n, name)] or cands
        nid = self.pick(near, cands)
        if nid:
            self.model_at(self.g.nodes[nid]['file'], self.g.nodes[nid]['line'] or 1, name, table, lang)

    def model_targets(self, fam, name, rel):
        cands = self.models.get((fam, name.rsplit('.', 1)[-1]), [])
        if len(cands) <= 1:
            return cands
        best = self.pick(rel, cands)
        return [best] if best else []

    def model_uses(self, src):
        fam = LANG_FAMILY.get(src.lang, src.lang)
        rx = self.model_rx.get(fam)
        out = []
        if src.lang == 'ex':
            if rx and 'Repo.' in src.code:
                out += self.ecto_uses(src, fam)
            return out
        if rx:
            code = src.code
            for m in rx.finditer(code):
                after = code[m.end():m.end() + 3].lstrip()
                before = code[max(0, m.start() - 6):m.start()]
                if src.lang in ('py', 'rb', 'js', 'kt') and after[:1] == '.' or src.lang in ('py', 'js') and after[:1] == '(' \
                        or src.lang == 'kt' and after[:1] == '[' or src.lang == 'java' and DATA_CALL.match(code, m.end()) \
                        or src.lang == 'php' and after[:2] == '::' or src.lang == 'js' and re.search(r'\bnew\s+$', before) \
                        or src.lang == 'py' and after[:1] in ',)' and PY_DB_CALL.search(code[max(0, m.start() - 60):m.start()]):
                    if src.lang == 'py' and after[:1] == '(' and re.search(r'\bclass\s+\w+\s*\($|\bclass\s+$', code[max(0, m.start() - 80):m.start()]):
                        continue
                    line_start = code.rfind('\n', 0, m.start()) + 1
                    if IMPORT_LINE.match(code[line_start:m.start()]):
                        continue
                    out += [(src.line(m.start()), t) for t in self.model_targets(fam, m.group(1), src.rel)
                            if self.model_visible(src, m.group(1), t)]
        if rx and src.lang in ('java', 'kt') and MODEL_REGISTRY.search(src.code):
            for m in MODEL_REGISTRY.finditer(src.code):
                end = src.close(m.end() - 1)
                for name in rx.finditer(src.code, m.end(), end if end > 0 else m.end()):
                    out += [(src.line(m.start()), t) for t in self.model_targets(fam, name.group(1), src.rel)]
        if src.lang == 'rb' and self.assocs:
            names = '|'.join(sorted(map(re.escape, self.assocs), key=len, reverse=True))
            for m in re.finditer(rf'\.\s*({names})\b(?=\s*\.\s*\w)', src.struct):
                out += [(src.line(m.start()), t) for t in self.model_targets(fam, self.assocs[m.group(1)], src.rel)]
        if src.lang in ('java', 'kt') and self.repos:
            names = '|'.join(sorted(map(re.escape, self.repos), key=len, reverse=True))
            if re.search(rf'\b(?:{names})\b', src.code):
                found = {}
                for m in re.finditer(rf'\b({names})\s*(?:<[^>]*>)?\s+(\w+)\s*[;,)=]|\b(\w+)\s*:\s*({names})\b', src.code):
                    found[m.group(2) or m.group(3)] = m.group(1) or m.group(4)
                for var, repo in sorted(found.items()):
                    for m in re.finditer(rf'\b{re.escape(var)}\s*\.\s*(\w+)\s*\(', src.code):
                        named = [e for e in self.repo_methods.get((repo, m.group(1)), []) if self.models.get((fam, e))]
                        for entity in named or [self.repos[repo]]:
                            out += [(src.line(m.start()), t) for t in self.model_targets(fam, entity, src.rel)]
        if src.lang == 'cs' and self.dbsets:
            names = '|'.join(sorted(map(re.escape, self.dbsets), key=len, reverse=True))
            for m in re.finditer(rf'\.\s*({names})\b(?!\s*[(<])', src.code):
                if IMPORT_LINE.match(src.code[src.code.rfind('\n', 0, m.start()) + 1:m.start()]):
                    continue
                entity, ctx = self.dbsets[m.group(1)]
                out += [(src.line(m.start()), t) for t in self.model_targets(fam, entity, ctx)]
        return out

    def model_visible(self, src, name, nid):
        rel = self.g.nodes[nid]['file']
        if rel == src.rel:
            return True
        if src.lang == 'js':
            trel = self.js_import_target(src, name)
            return trel == rel or bool(trel) and self.reexports(trel, name, rel)
        if src.lang == 'py':
            key = self.py_target(src, name)
            return key is None or key[0] == rel or key[0].endswith('__init__.py')
        return True

    def ecto_uses(self, src, fam):
        out, seen = [], set()
        for m in re.finditer(r'\bRepo\.[a-z_]\w*', src.code):
            sym = self.owner(src.rel, src.line(m.start()))
            if not sym or sym in seen:
                continue
            seen.add(sym)
            meta = self.g.nodes[sym]
            lines = src.code.split('\n')[(meta.get('line') or 1) - 1:meta.get('end') or meta.get('line') or 1]
            names = set()
            if lines and re.match(r'\s*defp?\s', lines[0]) and 'do:' not in lines[0]:
                lines = lines[1:]
            body = '\n'.join(lines)
            for r in ECTO_REF.finditer(body):
                name = next(x for x in r.groups() if x)
                if name != 'Repo' and not re.match(r'\s*=', body[r.end():].split('}', 1)[-1] if r.group(4) else ' '):
                    names.add(name)
            targets = [t for n in sorted(names) for t in self.model_targets(fam, n, src.rel)]
            if not targets:
                fn = snake(meta['name'].rsplit('.', 1)[-1])
                hits = sorted(((len(short), short) for (f, short) in self.models if f == fam and snake(short) in fn), reverse=True)
                targets = self.model_targets(fam, hits[0][1], src.rel) if hits else []
            out += [(meta.get('line') or 1, t) for t in targets]
        return out

    def scan_data(self, src):
        if not self.tables and not self.models:
            return
        if re.search(r'<auto-generated', src.text[:600]) and re.search(r'\b(?:BuildTargetModel|BuildModel)\b', src.code):
            return  # instantánea generada del modelo completo: repite todas las entidades, no es un flujo
        hits = set(self.model_uses(src)) | set(self.qualified_model_uses(src)) | set(self.query_builder_uses(src))
        for s, e in src.strings:
            if e - s > 20000:
                continue
            content = src.text[s:e]
            head = SQL_HEAD.match(SQL_COMMENT.sub('', STR_OPEN.sub('', content)))
            if not head:
                continue
            for m in SQL_TABLE[head.group(1).isupper()].finditer(content):
                found = [t for t in self.tables.get(m.group(1).lower(), []) if self.is_test(src.rel) or not self.is_test(self.g.nodes[t]['file'])]
                top = max((shared(src.rel, self.g.nodes[t]['file']) for t in found), default=0)
                for t in found:
                    if top == 0 or shared(src.rel, self.g.nodes[t]['file']) > 0 or not self.project_root(self.g.nodes[t]['file']) \
                            or not self.project_root(src.rel):
                        hits.add((src.line(s), t))
        for s, e in src.strings if self.models else ():
            hql = HQL_FROM.match(src.text[s:e]) if e - s < 4000 else None
            if hql:
                for target in self.model_targets(LANG_FAMILY.get(src.lang, src.lang), hql.group(1), src.rel):
                    hits.add((src.line(s), target))
        for rx in ORM.get(src.lang, []):
            for m in rx.finditer(src.code):
                for t in self.table_targets(m.group(1), src.rel):
                    hits.add((src.line(m.start()), t))
        if self.sqlc and src.lang in ('go', 'kt', 'java', 'py', 'js') and not self.generated(src.rel):
            if self.sqlc_rx is None:
                self.sqlc_rx = re.compile(r'\.\s*(%s)\s*\(' % '|'.join(sorted(map(re.escape, self.sqlc), key=len, reverse=True)))
            imports = [p.strip('/').split('/') for p in re.findall(r'"([\w.\-/]+/[\w.\-]+)"', src.code)] if src.lang == 'go' else None
            for m in self.sqlc_rx.finditer(src.code):
                entries = self.sqlc[m.group(1)]
                if imports is not None:
                    entries = [e for e in entries if any('/'.join(p[-3:]) + '/' in e[1] for p in imports)
                               or e[1].startswith(src.rel.rsplit('/', 1)[0] + '/')]
                ranked = sorted(((shared(src.rel, rel), names) for _, rel, names in entries), key=lambda x: -x[0])
                if not ranked or len(ranked) > 1 and ranked[0][0] == ranked[1][0]:
                    continue
                for name in ranked[0][1]:
                    for t in self.sql_targets(name, src.rel):
                        hits.add((src.line(m.start()), t))
        if src.lang in ('kt', 'java') and fam_models(self.models, src.lang) and '@' in src.code:
            for m in DAO_WRITE.finditer(src.code):
                for t in sorted(set(re.findall(r'[A-Z]\w*', m.group(1)))):
                    for target in self.model_targets(LANG_FAMILY.get(src.lang, src.lang), t, src.rel):
                        hits.add((src.line(m.end()), target))
        if self.drizzle and src.lang == 'js':
            for m in DRIZZLE_USE.finditer(src.code):
                nid = self.drizzle.get(m.group(1) or m.group(2))
                if nid and self.model_visible(src, m.group(1) or m.group(2), nid):
                    hits.add((src.line(m.start()), nid))
        if src.lang == 'rs':
            names = set(re.findall(r'\bschema::(\w+)(?:::dsl)?\b', src.code))
            for m in re.finditer(r'\b(\w+)::(?:table|dsl)\b|\b(?:insert_into|update|delete)\(\s*(\w+)(?:::table)?\s*\)', src.code):
                names.add(m.group(1) or m.group(2))
            for name in sorted(n for n in names if n in self.tables):
                for m in re.finditer(rf'(?<![\w:]){re.escape(name)}\s*(?:::table\b|\s*\.\s*(?:filter|select|find|order|limit|load|first|get_result|'
                                     rf'inner_join|left_join|count|execute)\b)|\b(?:insert_into|update|delete)\(\s*{re.escape(name)}\b', src.code):
                    for t in self.sql_targets(name, src.rel):
                        hits.add((src.line(m.start()), t))
            for m in re.finditer(r'\b(\w+)::(?:Entity|ActiveModel|Column)\b', src.code) if self.seaorm else ():
                table = self.seaorm.get(m.group(1))
                for t in self.tables.get(table, []) if table else ():
                    hits.add((src.line(m.start()), t))
        for m in TABLE_ACCESSOR.finditer(src.code) if self.tables else ():
            for t in self.table_targets(m.group(1), src.rel):
                hits.add((src.line(m.start()), t))
        for line, t in sorted(hits):
            sym = self.owner(src.rel, line)
            if sym and sym != t and not self.g.nodes[sym].get('table'):
                self.g.edge(sym, t, 'data')

    def src(self, rel, lang, text):
        s = Src(rel, lang, text)
        s.consts = self.consts
        s.url_builders = self.url_builders
        return s

    def collect_consts(self, rel, lang, text):
        if self.is_test(rel):
            return
        if lang in ('java', 'kt', 'cs', 'php', 'js', 'c'):
            self.collect_class_routes(rel, text)
            self.collect_class_bases(text)
        rx = CONST_DECL.get(lang)
        if rx and ('const' in text or 'final' in text or 'static' in text or lang in ('py', 'rb', 'go')):
            for m in rx.finditer(text):
                name, value = m.group(1), m.group(3)
                if len(value) <= 200 and len(name) > 1:
                    self.consts[name].add(value)
        if lang in ('js', 'java', 'kt', 'cs', 'py') and '@' in text:
            for m in CONSUMER_DECOR.finditer(text):
                args = text[m.end():m.end() + 400].split(')\n', 1)[0]
                self.topic_refs.update(re.findall(r'\b(?:[A-Z][A-Z0-9_]{3,}|[A-Z]\w*\.\w+\(\s*\))', args))

    def collect_sql(self, rel, text):
        if self.is_test(rel):
            return
        mid = self.module(rel)
        if not mid:
            return
        code = SQL_COMMENT_ANY.sub(lambda m: blanked(m.group()), text)
        for m in SQL_CREATE_TABLE.finditer(code):
            name = m.group(2)
            line = text.count('\n', 0, m.start()) + 1
            nid = f'c:{rel}:{name}'
            if nid not in self.g.nodes:
                semi = code.find(';', m.end())
                end = text.count('\n', 0, semi if semi > 0 else len(text)) + 1
                self.declare(nid, 'class', name, rel, line)
                self.g.nodes[nid].update(table=name, end=end, lang='sql')
                self.table_decls.add(nid)
                self.tables[name.lower()].append(nid)
                self.add_item(rel, line, end, nid)
            schema = m.group(1).rsplit('.', 1)[0].strip(' `"[]') if '.' in m.group(1) else ''
            self.sql_tables.append((nid, schema.lower(), name.lower()))
        queries = list(SQLC_NAME.finditer(text))
        for i, m in enumerate(queries):
            start = text.count('\n', 0, m.start()) + 1
            stop = queries[i + 1].start() if i + 1 < len(queries) else len(text)
            end = text.count('\n', 0, max(m.start(), stop - 1)) + 1
            nid = self.add_function(rel, m.group(1), start, max(start, end))
            body = code[m.end():stop]
            names = {t.group(1).lower() for upper in (True, False) for t in SQL_TABLE[upper].finditer(body)}
            self.sqlc[m.group(1)].append((nid, rel, sorted(names)))

    def scan_sql(self, rel, text):
        if self.is_test(rel) or not self.module(rel):
            return
        code = SQL_COMMENT_ANY.sub(lambda m: blanked(m.group()), text)
        pos = 0
        for stmt in code.split(';'):
            head = SQL_HEAD.match(stmt)
            if head and head.group(1).lower() in ('select', 'insert', 'update', 'delete', 'with', 'merge', 'replace', 'upsert'):
                for upper in (True, False):
                    for t in SQL_TABLE[upper].finditer(stmt):
                        line = text.count('\n', 0, pos + t.start()) + 1
                        sym = self.owner(rel, line)
                        for target in self.sql_targets(t.group(1), rel):
                            if sym and target != sym and self.g.nodes[target]['file'] != rel:
                                self.g.edge(sym, target, 'data')
            pos += len(stmt) + 1

    def sql_targets(self, name, rel):
        found = [n for n in self.tables.get(name.lower(), []) if self.same_project(rel, self.g.nodes[n]['file'])
                 and (self.is_test(rel) or not self.is_test(self.g.nodes[n]['file']))]  # esquemas de fixtures de test sólo para tests
        decls = [n for n in found if n in self.table_decls or self.g.nodes[n].get('file', '').endswith('.sql')] or found
        if len(decls) <= 1:
            return decls
        best = self.pick(rel, decls)
        return [best] if best else decls[:2]

    def add_item(self, rel, line, end, nid):
        items = self.by_file[rel]
        items.append((line, end, nid))
        items.sort()
        self.starts[rel] = [x[0] for x in items]

    def table_targets(self, name, rel):
        found = list(self.table_classes.get(name.lower(), []))
        if not found:
            for form in sorted(plural_forms(snake(name)) | plural_forms(name.lower())):
                found += self.tables.get(form, [])
        found = sorted(n for n in set(found) if self.same_project(rel, self.g.nodes[n]['file']))
        if len(found) <= 1:
            return found
        best = self.pick(rel, found)
        return [best] if best else found[:2]

    def project_root(self, rel):
        if self.roots is None:
            self.roots = {f.rsplit('/', 1)[0] if '/' in f else '' for f in self.files
                          if f.rsplit('/', 1)[-1] in PROJECT_MARKERS or f.endswith(('.csproj', '.fsproj'))}
            self.groups = {}
        parts = rel.split('/')[:-1]
        for i in range(len(parts), -1, -1):
            d = '/'.join(parts[:i])
            if d in self.roots:
                return d
        return None

    def same_project(self, a, b):
        ra, rb = self.project_root(a), self.project_root(b)
        if not ra or not rb or ra == rb or ra.startswith(rb + '/') or rb.startswith(ra + '/'):
            return True
        common = '/'.join(ra.split('/')[:shared(ra + '/x', rb + '/x')])
        if not common or common in self.roots:
            return True
        if common not in self.groups:
            try:
                names = os.listdir(self.root / common)
            except OSError:
                names = []
            self.groups[common] = any(n.endswith(('.sln', '.slnx')) or n.startswith(('docker-compose', 'compose.')) for n in names)
        return self.groups[common]

    def py_router_rx(self):
        """`PY_ROUTER` más las clases del repo que heredan de un router reconocido (`class UserAPIRouter(APIRouter)`)."""
        rx = getattr(self, '_py_router_rx', None)
        if rx is None:
            known = {'APIRouter', 'Blueprint', 'FastAPI', 'Flask', 'Quart', 'Sanic', 'APIBlueprint'}
            extra = sorted(n for n in self.alias_bases if n not in known and self.framework_alias(n, known))
            rx = self._py_router_rx = re.compile(PY_ROUTER.pattern[:-3] + ''.join('|' + re.escape(n) for n in extra) + r')\(') \
                if extra else PY_ROUTER
        return rx

    def scan_py(self, src):
        code, rel = src.code, src.rel
        for m in self.py_router_rx().finditer(code):
            end = src.close(paren(m))
            pre = PY_PREFIX.search(code, paren(m), end) if end > 0 else None
            if pre:
                self.local[rel][m.group(1)] = (None, pre.group(1))
        for m in PY_DECOR.finditer(code):
            recv, verb = m.group(1) or '', m.group(2)
            if not recv and not re.search(rf'^[ \t]*from\s+[\w.]+\s+import\s+[^\n]*\b{verb}\b', code, re.M):
                continue
            args, end = src.args(paren(m))
            if not args:
                continue
            path = None
            for a, b in args:
                kw = re.match(r'\s*(\w+)\s*=(?!=)', src.struct[a:b])
                if kw and kw.group(1) not in ('path', 'rule'):
                    continue
                path = src.expr(a + (kw.end() if kw else 0))
                break
            if path is None:
                continue
            d = PY_DEF.match(code, end + 1)
            argtext = code[m.end():end]
            if verb in ('route', 'api_route'):
                mm = PY_METHODS.search(argtext)
                verbs = main_verbs(quoted_all(mm.group(1))) if mm else ['ANY' if d and d.group(1) == 'class' else 'GET']
            else:
                verbs = ['GET' if verb == 'websocket' else verb.upper()]
            fn = (self.decl_after(src, d.start(2), d.group(2)) or self.owner(rel, src.line(d.start(2)))) if d else None
            self.route(src, m.start(), recv.rsplit('.', 1)[-1], verbs, path, fn)
        if 'web.' in code or 'router.add_' in code:
            self.scan_aiohttp(src)
        if 'Route(' in code:
            for m in PY_STARLETTE.finditer(code):
                args, end = src.args(paren(m))
                if len(args) < 2:
                    continue
                mm = PY_METHODS.search(code, m.end(), end)
                verbs = main_verbs(quoted_all(mm.group(1))) if mm else ['ANY']
                a, b = args[1]
                kw = re.match(r'\s*endpoint\s*=\s*', code[a:b])
                self.route(src, m.start(), '', verbs, src.expr(args[0][0]),
                           self.handler(src, a + (kw.end() if kw else 0), b, src.line(m.start())))
        if 'add_url_rule' in code:
            for m in PY_URL_RULE.finditer(code):
                args, end = src.args(paren(m))
                if not args:
                    continue
                argtext = code[m.end():end]
                mm = PY_METHODS.search(argtext)
                verbs = main_verbs(quoted_all(mm.group(1))) if mm else ['GET']
                vf = re.search(r'\bview_func\s*=\s*', argtext)
                if vf:
                    a = m.end() + vf.end()
                    b = next((y for x, y in args if x <= a <= y), end)
                    fn = self.handler(src, a, b, src.line(m.start()))
                else:
                    fn = self.handler(src, *args[2], src.line(m.start())) if len(args) > 2 else None
                self.route(src, m.start(), '', verbs, src.expr(args[0][0]), fn)
        for m in PY_MOUNT.finditer(code):
            args, end = src.args(paren(m))
            if not args:
                continue
            if m.group(2) == 'mount':
                if len(args) < 2:
                    continue
                pre, target = first_string(code[args[0][0]:args[0][1]]), code[args[1][0]:args[1][1]].strip()
            else:
                kw = PY_PREFIX.search(code, m.end(), end)
                pre, target = (kw.group(1) if kw else ''), code[args[0][0]:args[0][1]].strip()
            if pre is None or not re.fullmatch(r'[\w.]+', target):
                continue
            key = self.py_target(src, target)
            if key:
                self.mounts[key].append((rel, m.group(1), pre, ''))
                self.mount_links.append((rel, src.line(m.start()), key))
        if 'urlpatterns' in code or 'Router(' in code:
            self.scan_django(src)
        if ('tornado' in code or 'falcon' in code) and not self.is_test(rel):
            for m in re.finditer(r'''\(\s*[rbu]?['"]([^'"]+)['"]\s*,\s*([A-Z]\w*)\s*[,)]|\.add_route\(\s*['"]([^'"]+)['"]\s*,\s*([A-Z]\w*)\s*\(''', code):
                cls = self.resolve(m.group(2) or m.group(4), rel, src.line(m.start()))
                if cls and self.g.nodes[cls]['kind'] == 'class':
                    path = django_regex(m.group(1)) if m.group(1) else m.group(3)
                    self.route(src, m.start(), '', ['ANY'], path, cls)
        if ('strawberry' in code or 'graphene' in code or 'ariadne' in code) and not self.is_test(rel):
            self.scan_py_graphql(src)
        self.scan_py_clients(src)
        if re.search(r'\bgql\s*\(', code):
            self.scan_gql_ops(src)

    def scan_py_graphql(self, src):
        code, rel = src.code, src.rel
        lines = code.split('\n')
        for m in re.finditer(r'^([ \t]*)class\s+(\w*?(Query|Mutation|Subscription))\b[^\n]*:', code, re.M):
            ind, op = len(m.group(1)), m.group(3)
            start = src.line(m.start())
            for i in range(start, len(lines)):
                line = lines[i]
                if line.strip() and indent_of(line) <= ind:
                    break
                d = re.match(r'\s*(?:async\s+)?def\s+(\w+)', line)
                if not d or d.group(1).startswith('__'):
                    continue
                field = d.group(1)[8:] if d.group(1).startswith('resolve_') else d.group(1)
                decorated = any(re.match(r'\s*@\w*\.?(?:field|mutation|subscription)\b', x) for x in lines[max(0, i - 3):i])
                if decorated or d.group(1).startswith('resolve_'):
                    self.gql_endpoint(rel, i + 1, op, field, self.owner(rel, i + 1))
        for m in re.finditer(r'''\b(query|mutation|subscription)\.field\(\s*['"](\w+)['"]\s*\)\s*\n\s*(?:async\s+)?def\s+(\w+)''', code):
            self.gql_endpoint(rel, src.line(m.start()), m.group(1), m.group(2), self.in_file(rel, m.group(3)))

    def scan_aiohttp(self, src):
        code = src.code
        for m in PY_AIOHTTP.finditer(code):
            args, end = src.args(paren(m))
            verb = m.group(1)
            if verb == 'route':
                if len(args) < 3:
                    continue
                verbs, args = [(first_string(code[args[0][0]:args[0][1]]) or 'ANY').upper()], args[1:]
            elif len(args) < 2:
                continue
            else:
                verbs = ['ANY' if verb == 'view' else verb.upper()]
            self.route(src, m.start(), '', verbs, src.expr(args[0][0]), self.handler(src, *args[1], src.line(m.start())))

    def py_target(self, src, target):
        parts = target.split('.')
        var = parts[-1]
        modname = parts[-2] if len(parts) > 1 else None
        for m in PY_IMPORT.finditer(src.code):
            base = m.group(1)
            for n in m.group(2).split(','):
                bits = [b.strip() for b in n.split(' as ')]
                if not bits[0]:
                    continue
                alias = bits[-1]
                full = (base + bits[0]) if base.endswith('.') else f'{base}.{bits[0]}'
                if modname is None and alias == var:
                    sub = self.py_module(src.rel, full)
                    if sub and not sub.endswith('__init__.py'):
                        return (sub, None)
                    rel = self.py_module(src.rel, base)
                    if rel:
                        return (rel, bits[0])
                    return (sub, None) if sub else None
                if modname is not None and alias == modname:
                    rel = self.py_module(src.rel, full)
                    if rel:
                        return (rel, var)
        if modname is not None:
            for m in PY_IMPORT_AS.finditer(src.code):
                if (m.group(2) or m.group(1).rsplit('.', 1)[-1]) == modname:
                    rel = self.py_module(src.rel, m.group(1))
                    if rel:
                        return (rel, var)
            return None
        if var in self.local[src.rel] or re.search(rf'^\s*{re.escape(var)}\s*=', src.code, re.M):
            return (src.rel, var)
        return None

    def py_module(self, rel, spec):
        dots = len(spec) - len(spec.lstrip('.'))
        path = spec.lstrip('.').replace('.', '/')
        if dots:
            base = rel.split('/')[:-1]
            base = base[:len(base) - (dots - 1)] if dots > 1 else base
            path = '/'.join(base + ([path] if path else []))
        if not path:
            return None
        for cand in (f'{path}.py', f'{path}/__init__.py'):
            if cand in self.fileset:
                return cand
        if dots:
            return None
        tails = sorted(f for f in self.fileset if f.endswith(('/' + path + '.py', '/' + path + '/__init__.py')))
        if len(tails) == 1:
            return tails[0]
        if tails:
            ranked = sorted(tails, key=lambda f: (-shared(rel, f), f))
            return ranked[0] if shared(rel, ranked[0]) > shared(rel, ranked[1]) else None
        return None

    def django_routers(self, src):
        return set(re.findall(r'\b(\w+)\s*=\s*(?:\w+\.)?(?:Default|Simple|Nested\w*|Extended\w*)Router\(', src.code))

    def scan_django(self, src):
        code, rel = src.code, src.rel
        units = self.django
        routers = self.django_routers(src)
        entries = units.setdefault((rel, None), [])
        if 'urlpatterns' in code:
            nested = []  # `path("api/", include([...]))`: las rutas de la lista heredan el prefijo
            for m in PY_URLPATH.finditer(code):
                args, end = src.args(paren(m))
                if len(args) < 2:
                    continue
                lit = src.literal(src.skip(args[0][0]))
                if not lit:
                    continue
                path = lit[0] if m.group(1) == 'path' else django_regex(lit[0])
                target = code[args[1][0]:args[1][1]].strip()
                line = src.line(m.start())
                outer = [p for a, b, p in nested if a < m.start() < b]
                if re.match(r'include\(\s*\[', target):
                    nested.append((args[1][0], args[1][1], path))
                    continue
                path = ''.join(outer) + path
                inc = re.match(r'''include\(\s*(?:\(\s*)?(?:['"]([\w.]+)['"]|([\w.]+))''', target)
                if inc:
                    spec = inc.group(1) or inc.group(2)
                    if inc.group(2) and spec.split('.')[0] in routers:
                        key = (rel, spec.split('.')[0])
                    elif inc.group(1):
                        trel = self.py_module(rel, spec)
                        key = (trel, None) if trel else None
                    else:
                        found = self.py_target(src, spec)
                        key = (found[0], None) if found and found[0] != rel else None
                    if key:
                        entries.append(('include', path, key, line))
                        if key[1] is None and not self.is_test(rel):
                            self.mount_links.append((rel, line, key))
                    continue
                entries.append(('route', path, self.handler(src, args[1][0], args[1][1], line), line))
        for var in sorted(routers):
            if re.search(rf'urlpatterns\s*\+?=\s*(?:\[[^\]]*)?\b{var}\.urls', code):
                entries.append(('include', '', (rel, var), 0))
        for m in PY_ROUTER_REG.finditer(code):
            if m.group(1) not in routers:
                continue
            args, end = src.args(paren(m))
            if len(args) < 2:
                continue
            lit = src.literal(src.skip(args[0][0]))
            if not lit:
                continue
            line = src.line(m.start())
            target = self.handler(src, args[1][0], args[1][1], line)
            base = django_regex(lit[0])
            bucket = units.setdefault((rel, m.group(1)), [])
            expanded = self.viewset_routes(base, target)
            if expanded:
                bucket += [('route', path, handler, line, verbs) for verbs, path, handler in expanded]
                continue
            bucket.append(('route', base, target, line))
            bucket.append(('route', base + '/<pk>', target, line))

    def finish_django(self):
        units = self.django
        included = {e[2] for entries in units.values() for e in entries if e[0] == 'include'}
        seen = set()

        def walk(key, prefix, depth):
            if depth > 6 or (key, prefix) in seen:
                return
            seen.add((key, prefix))
            for kind, path, target, line, *verbs in units.get(key, []):
                if kind == 'include':
                    walk(target, prefix + '/' + path, depth + 1)
                elif not self.is_test(key[0]):
                    self.pending.append((key[0], line, '', tuple(verbs[0]) if verbs else ('ANY',), prefix + '/' + path, target or '', '', ''))

        for key in sorted((k for k in units if k not in included and units[k]), key=lambda k: (k[0], k[1] or '')):
            walk(key, '', 0)

    def scan_py_clients(self, src):
        code = src.code
        for m in PY_CLIENT.finditer(code):
            recv, verb = m.group(1), m.group(2)
            last = recv.rsplit('.', 1)[-1]
            if last not in PY_CLIENT_NAMES and not last.endswith(('client', 'session')):
                continue
            args, end = src.args(paren(m))
            if not args:
                continue
            if verb == 'request':
                if len(args) < 2:
                    continue
                method = first_string(code[args[0][0]:args[0][1]]) or 'ANY'
                tpl = src.expr(args[1][0])
            else:
                kw = re.match(r'\s*(\w+)\s*=(?!=)', src.struct[args[0][0]:args[0][1]])
                if kw and kw.group(1) != 'url':
                    continue
                method = 'GET' if verb == 'urlopen' else verb
                tpl = src.expr(args[0][0] + (kw.end() if kw else 0))
            self.client(src, m.start(), method, tpl)

    def js_server_vars(self, src):
        names = set(JS_SERVER_VAR.findall(src.code))
        if JS_SERVER_IMPORT.search(src.code):
            names |= JS_SERVER_NAMES
        return names

    def js_import_map(self, src):
        imports = self.js_imports.get(src.rel)
        if imports is None:
            imports = {}
            for m in JS_IMPORT.finditer(src.code):
                spec = m.group(5) or m.group(7)
                for name in (m.group(1), m.group(2), m.group(6)):
                    if name:
                        imports[name] = (spec, None)
                for group in (m.group(3), m.group(4)):
                    for part in (group or '').split(','):
                        bits = [b.strip() for b in part.strip().split(' as ')]
                        if bits[0]:
                            imports[bits[-1]] = (spec, bits[0])
            self.js_imports[src.rel] = imports
        return imports

    def js_resolve_spec(self, rel, spec):
        if not spec:
            return None
        if not spec.startswith('.'):
            return self.imported_file(rel, spec) or self.workspace_file(spec)
        base = os.path.normpath(os.path.join(os.path.dirname(rel), spec)).replace(os.sep, '/')
        for suffix in ('', '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '/index.ts', '/index.js', '/index.tsx', '/index.mjs'):
            if base + suffix in self.fileset:
                return base + suffix
        stem = os.path.splitext(base)[0]
        for suffix in ('.ts', '.tsx'):
            if stem + suffix in self.fileset:
                return stem + suffix
        return None

    def imported_file(self, rel, spec):
        if self.import_targets is None:
            self.import_targets = defaultdict(list)
            for a, b, kind in self.g.edges:
                if kind == 'import' and a.startswith('m:') and b.startswith('m:'):
                    self.import_targets[a[2:]].append(b[2:])
        tail = spec.lstrip('@~#/').split('/', 1)[-1] if spec.startswith(('@/', '~/', '#/', '/')) else spec
        found = sorted({t for t in self.import_targets.get(rel, ()) if os.path.splitext(t)[0].endswith('/' + tail)
                        or os.path.splitext(t)[0] == tail or os.path.dirname(t).endswith('/' + tail)
                        and os.path.basename(t).startswith('index.')})
        if not found and spec.startswith(('@', '~', '#')) and '/' in spec:
            tail = spec.lstrip('@~#').strip('/')
            found = sorted({t for t in self.import_targets.get(rel, ()) if ('/' + os.path.splitext(t)[0]).endswith('/' + tail)
                            or ('/' + os.path.dirname(t)).endswith('/' + tail) and os.path.basename(t).startswith('index.')})
        return found[0] if len(found) == 1 else None

    def js_import_target(self, src, ident):
        found = self.js_import_map(src).get(ident)
        return self.js_resolve_spec(src.rel, found[0]) if found else None

    def js_imported_name(self, src, ident):
        found = self.js_import_map(src).get(ident)
        return found[1] if found and found[1] else None

    def scan_js_tasks(self, src):
        code, rel = src.code, src.rel
        for m in TASK_DEF.finditer(code):
            args, end = src.args(paren(m))
            if args and end > 0:
                keys = self.arg_keys(src, args[:1], ('id', 'name'))
                if m.group(2) == 'createFunction' and len(args) > 1:
                    keys = self.arg_keys(src, args[1:2], ('event',)) or keys
            else:
                found = re.match(r'\s*\{\s*(?:id|name)\s*:\s*' + TOPIC_NAME, code[m.end():m.end() + 200])
                keys, end = ([found.group(1)] if found else []), m.end()
            if not keys or not keys[0]:
                continue
            line = src.line(m.start())
            fn = self.owner(rel, line)
            if not fn or self.g.nodes[fn]['kind'] not in ('function', 'method') or self.g.nodes[fn].get('line') != line:
                fn = self.add_function(rel, m.group(1), line, src.line(end))
            self.task_defs[m.group(1)].append((keys[0], rel))
            self.topic_uses.append((keys[0], rel, line, 'sub', fn, 'mq'))
        for m in TASK_TRIGGER.finditer(code):
            args, _ = src.args(paren(m))
            lit = src.literal(src.skip(args[0][0])) if args else None
            if m.group(1) in ('tasks', 'jobs', 'client') and lit:
                self.topic_uses.append((lit[0], rel, src.line(m.start()), 'pub', '', 'mq'))
            else:
                self.task_calls_js.append((rel, src.line(m.start()), m.group(1)))
        for m in re.finditer(r'\.\s*send\(\s*\{\s*name\s*:\s*' + TOPIC_NAME, code) if 'inngest' in code.lower() else ():
            self.topic_uses.append((m.group(1), rel, src.line(m.start()), 'pub', '', 'mq'))

    def gql_endpoint(self, rel, line, op, field, handler):
        if field and handler:
            self.endpoint(rel, line, op.upper(), f'/graphql/{field.lower()}', handler)

    def scan_resolver_maps(self, src):
        code, rel = src.code, src.rel
        for m in re.finditer(r'\b(Query|Mutation|Subscription)\s*:\s*\{', code):
            args, _ = src.args(m.end() - 1)
            for a, b in args:
                k = re.match(r'\s*(?:async\s+)?(\w+)\s*(?::\s*(.*)|\()', code[a:b], re.S)
                if not k:
                    continue
                line = src.line(a + k.start(1))
                value = (k.group(2) or '').strip()
                handler = self.resolve(value, rel, line) if re.fullmatch(r'[\w.]+', value) else None
                self.gql_endpoint(rel, line, m.group(1), k.group(1), handler or self.owner(rel, line))

    def scan_gql_ops(self, src):
        code, rel = src.code, src.rel
        if self.is_test(rel):
            return
        for s, e in src.strings:
            body = src.text[s:e]
            if not re.search(r'\b(?:query|mutation|subscription)\b|^[`"\']{1,3}\s*\{', body):
                continue
            ops = gql_fields(body)
            if not ops:
                continue
            line = src.line(s)
            sym = self.owner(rel, line)
            users = []
            const = re.search(r'\b(?:const|let|var|val)?\s*([A-Za-z_$][\w$]*)\s*(?::\s*[\w<>]+\s*)?=\s*(?:gql|graphql)?\s*\(?\s*$',
                              code[max(0, s - 120):s].split('\n')[-1])
            if const and (not sym or self.g.nodes[sym]['kind'] == 'module'):
                for u in re.finditer(rf'(?<![\w$.]){re.escape(const.group(1))}\b', code):
                    owner = self.function_at(src, u.start())
                    if owner and abs(src.line(u.start()) - line) > 0:
                        users.append(owner)
            for op, field in ops:
                for target in sorted(set(users)) or [sym]:
                    if target:
                        self.client(src, s, op.upper(), f'/graphql/{field}', target)

    def scan_trpc_server(self, src):
        code, rel = src.code, src.rel
        for m in re.finditer(r'(?:\b(?:const|let|var)\s+(\w+)\s*=\s*)?\b(?:\w+\.)?(?:router|createTRPCRouter|createRouter)\s*\(\s*\{', code):
            args, _ = src.args(m.end() - 1)
            entries = []
            for a, b in args:
                k = re.match(r'\s*(\w+)\s*:\s*', code[a:b])
                if not k:
                    continue
                value = src.struct[a + k.end():b]
                proc = re.search(r'\.\s*(query|mutation|subscription)\s*\(', value)
                line = src.line(a + k.start(1))
                if proc and 'rocedure' in value:
                    entries.append((k.group(1), 'proc', 'QUERY' if proc.group(1) == 'query' else proc.group(1).upper(), line))
                elif re.fullmatch(r'\s*\w+\s*', value):
                    entries.append((k.group(1), 'ref', value.strip(), line))
            self.trpc_routers.append((m.group(1) or '', rel, entries))

    def scan_trpc_clients(self, src):
        code = src.code
        roots = {alias for alias, (spec, name) in self.js_import_map(src).items() if 'trpc' in (spec or '').lower()}
        for m in re.finditer(r'(?<![\w$.])(\w+)((?:\.\w+)+)\.(useQuery|useSuspenseQuery|useInfiniteQuery|useMutation|query|mutate|fetch|'
                             r'prefetch|useSubscription)\s*\(', code):
            if m.group(1) not in roots and m.group(1) not in ('trpc', 'api'):
                continue
            verb = 'MUTATION' if m.group(3) in ('useMutation', 'mutate') else 'QUERY'
            self.client(src, m.start(), verb, '/trpc/' + m.group(2).strip('.').replace('.', '/'))

    def finish_trpc(self):
        named = {name: (rel, entries) for name, rel, entries in self.trpc_routers if name}
        refs = {v for _, _, entries in self.trpc_routers for _, kind, v, _ in entries if kind == 'ref'}

        def walk(rel, entries, prefix, depth):
            for key, kind, value, line in entries:
                if kind == 'proc':
                    self.endpoint(rel, line, value, '/trpc/' + '/'.join(prefix + [key]), self.owner(rel, line))
                elif value in named and depth < 6:
                    walk(*named[value], prefix + [key], depth + 1)

        for name, rel, entries in self.trpc_routers:
            if name not in refs:
                walk(rel, entries, [], 0)

    def scan_js(self, src):
        code = src.code
        self.scan_js_files(src)
        if not self.is_test(src.rel) and ('trigger' in code or 'Function(' in code or 'task(' in code.lower() or 'inngest' in code):
            self.scan_js_tasks(src)
        servers = self.js_server_vars(src)
        if servers:
            self.scan_js_server(src, servers)
        if '@nestjs' in code or 'setGlobalPrefix' in code:
            self.nest_prefix += NEST_PREFIX.findall(code)
            for m in NEST_VERSIONING.finditer(code):
                opts = m.group(1)
                if re.search(r'\btype\s*:', opts) and not re.search(r'\btype\s*:\s*VersioningType\.URI\b', opts):
                    continue
                pre = re.search(r'''\bprefix\s*:\s*['"`]([^'"`]*)''', opts)
                dv = re.search(r'\bdefaultVersion\s*:\s*([^,\n}]+)', opts)
                self.nest_versioning.append((pre.group(1) if pre else 'v', nest_version(dv.group(1)) if dv else None))
            if '@nestjs' in code:
                self.scan_annotations(src)
        elif 'type-graphql' in code:
            self.scan_annotations(src)
        self.scan_js_clients(src, servers)
        if not self.is_test(src.rel):
            if re.search(r'\b(?:Query|Mutation|Subscription)\s*:\s*\{', code):
                self.scan_resolver_maps(src)
            if 'rocedure' in code or re.search(r'\b(?:router|createTRPCRouter|createRouter)\s*\(\s*\{', code):
                self.scan_trpc_server(src)
            if re.search(r'\.\s*(?:useQuery|useSuspenseQuery|useInfiniteQuery|useMutation|query|mutate|fetch|prefetch)\s*\(', code):
                self.scan_trpc_clients(src)
        if re.search(r'\b(?:gql|graphql)\s*(?:`|\(\s*`)|/\*\s*GraphQL\s*\*/', code):
            self.scan_gql_ops(src)
        self.wrapper_calls(src)
        if re.search(r'\bcreateBuilder\s*\(', code) and re.search(r'''from\s+['"][^'"]*aspire''', code):
            self.scan_apphost(src, 'add')

    def scan_js_server(self, src, servers):
        code, rel = src.code, src.rel
        for m in JS_ROUTE.finditer(code):
            recv, verb = m.group(1), m.group(2)
            if recv not in servers:
                continue
            args, end = src.args(paren(m))
            if len(args) < 2:
                continue
            verb = {'del': 'DELETE', 'all': 'ANY'}.get(verb, verb.upper())
            self.route(src, m.start(), recv, [verb], src.expr(args[0][0]),
                       self.handler(src, *args[-1], src.line(m.start())), strict=True)
        for m in JS_CHAIN_ROUTE.finditer(code):
            if m.group(1) not in servers:
                continue
            args, end = src.args(paren(m))
            if not args:
                continue
            first = code[args[0][0]:args[0][1]]
            if first.strip().startswith('{'):
                mm, uu = METHOD_KW.search(first), URL_KW.search(first)
                hh = re.search(r'\bhandler\s*:\s*([\w.]+)', first)
                if uu:
                    fn = self.resolve(hh.group(1), rel) if hh else self.owner(rel, src.line(m.start()))
                    self.route(src, m.start(), m.group(1), [(mm.group(1) if mm else 'ANY').upper()],
                               src.expr(args[0][0] + uu.end()), fn, strict=True)
                continue
            if len(args) == 2:
                self.js_mount(src, m.group(1), src.expr(args[0][0]), code[args[1][0]:args[1][1]].strip(), m.start())
                continue
            tpl, p = src.expr(args[0][0]), end + 1
            while True:
                c = JS_CHAIN_VERB.match(code, p)
                if not c:
                    break
                cargs, cend = src.args(c.end() - 1)
                if cend < 0:
                    break
                fn = self.handler(src, *cargs[-1], src.line(m.start())) if cargs else None
                self.route(src, c.start(), m.group(1), ['ANY' if c.group(1) == 'all' else c.group(1).upper()], tpl, fn,
                           strict=True)
                p = cend + 1
        for m in JS_MOUNT.finditer(code):
            if m.group(1) not in servers:
                continue
            args, end = src.args(paren(m))
            if m.group(2) == 'register':
                if len(args) >= 2:
                    pre = re.search(r'''\bprefix\s*:\s*['"`]([^'"`]*)''', code[args[1][0]:args[1][1]])
                    if pre:
                        self.js_mount(src, m.group(1), pre.group(1), code[args[0][0]:args[0][1]].strip(), m.start())
                continue
            if len(args) < 2 or not src.literal(src.skip(args[0][0])):
                continue
            self.js_mount(src, m.group(1), src.expr(args[0][0]), code[args[-1][0]:args[-1][1]].strip(), m.start())

    def js_mount(self, src, recv, prefix, target, pos=0):
        if prefix is None:
            return
        prefix = drop_base(prefix)
        target = re.sub(r'\.routes\(\)$|\.router$|\(\)$', '', target)
        req = re.match(r'''require\(\s*['"]([^'"]+)['"]\s*\)''', target)
        if req:
            trel = self.js_resolve_spec(src.rel, req.group(1))
        elif re.fullmatch(r'[\w$]+', target):
            trel = self.js_import_target(src, target)
        else:
            return
        if trel:
            self.mounts[(trel, None)].append((src.rel, recv, prefix, ''))
            self.mount_links.append((src.rel, src.line(pos), (trel, None)))
        elif not req and re.search(rf'\b{re.escape(target)}\s*=', src.code):
            self.local[src.rel][target] = (recv, prefix)

    def scan_js_files(self, src):
        rel = src.rel
        parts = rel.split('/')
        dirs, stem = parts[:-1], os.path.splitext(parts[-1])[0]
        if self.is_test(rel):
            return
        if stem == 'route' and 'app' in dirs:
            i = len(dirs) - 1 - dirs[::-1].index('app')
            self.export_routes(src, '/'.join(next_seg(p) for p in dirs[i + 1:]))
        elif stem == '+server' and 'routes' in dirs:
            i = len(dirs) - 1 - dirs[::-1].index('routes')
            self.export_routes(src, '/'.join(next_seg(p) for p in dirs[i + 1:]))
        elif 'pages' in dirs and JS_NEXT_EXPORT.search(src.code) and not JS_DEFAULT_FN.search(src.code):
            i = len(dirs) - 1 - dirs[::-1].index('pages')
            self.export_routes(src, '/'.join([next_seg(p) for p in dirs[i + 1:]] + ([] if stem == 'index' else [next_seg(stem)])))
        elif 'routes' in dirs and dirs[-1] == 'routes' and 'app' in dirs and re.search(REMIX_EXPORT, src.code) \
                or 'routes' in dirs[:-1] and stem == 'route' and re.search(REMIX_EXPORT, src.code):
            name = dirs[-1] if stem == 'route' else stem
            segs = []
            for part in re.split(r'(?<!\[)\.(?![^\[]*\])', name):
                part = part.strip('[]').rstrip('_')
                if not part or part.startswith('_') or part.startswith('(') or part == 'index':
                    continue
                segs.append(':' + part[1:] if part.startswith('$') and len(part) > 1 else '*' if part == '$' else part)
            for m in re.finditer(REMIX_EXPORT, src.code):
                fn = self.in_file(rel, m.group(1)) or self.module(rel)
                self.route(src, m.start(), '', ['GET' if m.group(1) == 'loader' else 'POST'], '/'.join(segs), fn)
        elif 'pages' in dirs and dirs[dirs.index('pages') + 1:dirs.index('pages') + 2] == ['api']:
            i = dirs.index('pages')
            segs = [next_seg(p) for p in dirs[i + 1:]] + ([] if stem == 'index' else [next_seg(stem)])
            m = JS_DEFAULT_FN.search(src.code)
            if m or 'export default' in src.code:
                fn = self.in_file(rel, m.group(1)) if m else None
                self.route(src, 0, '', ['ANY'], '/'.join(segs), fn or self.module(rel))
        elif self.nuxt and 'server' in dirs and dirs[dirs.index('server') + 1:dirs.index('server') + 2] in (['api'], ['routes']):
            i = dirs.index('server')
            bits = stem.split('.')
            verb = bits[-1].upper() if len(bits) > 1 and bits[-1].upper() in VERBS else 'ANY'
            base = bits[0] if verb != 'ANY' else stem
            prefix = ['api'] if dirs[i + 1] == 'api' else []
            segs = prefix + [next_seg(p) for p in dirs[i + 2:]] + ([] if base == 'index' else [next_seg(base)])
            self.route(src, 0, '', [verb], '/'.join(segs), self.module(rel))

    def export_routes(self, src, path):
        for m in JS_NEXT_EXPORT.finditer(src.code):
            if m.group(1):
                found = [(m.group(1), m.group(1), m.start())]
            else:
                found, at = [], m.start(2)
                for part in m.group(2).split(','):
                    bits = [b.strip() for b in part.split(' as ')]
                    if bits[-1] in VERBS:
                        found.append((bits[-1], bits[0], at + len(part) - len(part.lstrip())))
                    at += len(part) + 1
            for verb, local, pos in found:
                fn = self.in_file(src.rel, local) or self.module(src.rel)
                self.route(src, pos, '', [verb], path, fn)

    def scan_js_clients(self, src, servers):
        code = src.code
        for m in JS_CLIENT.finditer(code):
            args, end = src.args(paren(m))
            if not args:
                continue
            a, b = args[0]
            guard = js_split(code[a:b], '&&')
            if len(guard) > 1:  # `cond && \`api/x/${id}\``: la clave es la URL de la derecha
                a = b - len(guard[-1])
            first = code[a:b]
            opts = code[args[1][0]:args[1][1]] if len(args) > 1 else ''
            if first.strip().startswith('{'):
                uu = URL_KW.search(first)
                if not uu:
                    continue
                tpl, opts = src.expr(a + uu.end()), first
            else:
                tpl = src.expr(a)
            mm = METHOD_KW.search(opts)
            verbs = [mm.group(1)] if mm else list(dict.fromkeys(re.findall(r'''['"`](GET|POST|PUT|PATCH|DELETE)['"`]''', opts))) or ['GET']
            for verb in verbs:
                if tpl is None:
                    self.param_wrapper(src, m.start(), first.strip(), verb)
                self.client(src, m.start(), verb, tpl)
        for m in JS_CLIENT_METHOD.finditer(code):
            recv, verb = m.group(1), m.group(2)
            chain = js_chain(code, m.start(1)) + [recv]
            if chain[0] in servers or recv in servers or not any(JS_CLIENT_NAMES.match(x) for x in chain):
                continue
            args, end = src.args(paren(m))
            if not args:
                continue
            base = self.js_base(src, chain[0] if chain[0] not in ('this', 'self') or len(chain) < 2 else chain[1])
            if verb == 'request':
                a, b = args[0]
                obj = code[a:b]
                uu, mm = URL_KW.search(obj), METHOD_KW.search(obj)
                if uu:
                    self.client(src, m.start(), mm.group(1) if mm else 'ANY', with_base(base, src.expr(a + uu.end())))
                continue
            tpl = self.js_url_arg(src, args[0])
            if tpl is None:
                self.param_wrapper(src, m.start(), code[args[0][0]:args[0][1]].strip(), verb, base)
            self.client(src, m.start(), verb, with_base(base, tpl))
            if not code[args[0][0]:args[0][1]].strip().startswith(('{', '"', "'")):
                for alt in self.url_alternatives(src, *args[0]):
                    self.client(src, m.start(), verb, with_base(base, alt))
        for m in re.finditer(r'\.\s*open\s*\(\s*[\'"`](GET|POST|PUT|PATCH|DELETE|HEAD)[\'"`]\s*,', code) if 'open' in code else ():
            self.client(src, m.start(), m.group(1), src.expr(m.end()))
        for m in re.finditer(r'\bnew\s+(?:EventSource|WebSocket|ReconnectingWebSocket)\s*\(', code):
            self.client(src, m.start(), 'GET', src.expr(m.end()))
        if 'callApi' in code:
            for m in re.finditer(r'\.\s*callApi\s*\(', code):
                args, end = src.args(paren(m))
                if len(args) >= 2:
                    self.client(src, m.start(), first_string(code[args[1][0]:args[1][1]]) or 'ANY', src.expr(args[0][0]))
        for m in JS_PAREN_CLIENT.finditer(code):
            open_pos = js_open(src.struct, m.start())
            if open_pos < 0 or not any(JS_CLIENT_NAMES.match(x) for x in re.findall(r'[\w$]+', code[open_pos:m.start()])):
                continue
            args, end = src.args(paren(m))
            if args and code[args[0][0]:args[0][1]].strip().startswith('{'):
                self.client(src, m.start(), m.group(1), self.js_url_arg(src, args[0]))

    def js_url_arg(self, src, arg):
        a, b = arg
        first = src.code[a:b]
        if first.strip().startswith('{'):
            uu = URL_KW.search(first)
            return src.expr(a + uu.end()) if uu else None
        return src.expr(a)

    def js_base(self, src, ident):
        trel = self.js_import_target(src, ident) or src.rel
        name = self.js_imported_name(src, ident) or ident
        key = (trel, name)
        if key not in self.js_bases:
            text = src.text if trel == src.rel else self.text(trel)
            base, m = None, None
            if text and (JS_BASE_HINT.search(text) or re.search(rf'(?<![\w$.]){re.escape(name)}\s*(?::[^=;]+)?=', text)):
                other = src if trel == src.rel else Src(trel, 'js', text)
                decl = re.search(rf'(?<![\w$.]){re.escape(name)}\s*(?::[^=;]+)?=(?!=)', other.code)
                if decl:
                    m = JS_BASE.search(other.code, decl.end(), decl.end() + 600)
                m = m or (JS_BASE.search(other.code) if JS_BASE_HINT.search(text) else None)
                tpl = other.expr(m.end()) if m else None
                if m and (tpl is None or '\0' in tpl):
                    stop = re.search(r'[,}\n]', other.struct[m.end():m.end() + 300])
                    alts = self.url_alternatives(other, m.end(), m.end() + (stop.start() if stop else 0)) if stop else []
                    tpl = next((a for a in alts if a and '\0' not in a and PATHLIKE.fullmatch(a)), tpl)
                if tpl is not None:
                    tpl = SCHEME.sub('', tpl.strip()).lstrip('\0')
                    base = tpl if '\0' not in tpl and PATHLIKE.fullmatch(tpl or '/') else None
            self.js_bases[key] = base
        return self.js_bases[key]

    def scan_annotations(self, src):
        code, s, rel = src.code, src.struct, src.rel
        if not re.search(r'^[ \t]*(?:@\w|\[\w|#\[)', s, re.M):
            return
        classes = []
        for m in CLASS_ANY.finditer(s):
            brace = s.find('{', m.end())
            semi = s.find(';', m.end())
            if brace < 0 or (0 <= semi < brace and src.lang != 'kt'):
                continue
            end = src.close(brace)
            classes.append([m.start(), end if end > 0 else len(s), m.group(1), {}])
        blocks, done = [], -1
        for m in ANN_START.finditer(s):
            if m.start() < done:
                continue
            p, anns = m.start(), []
            while True:
                p = src.skip(p)
                if s.startswith('@', p) and p + 1 < len(s) and s[p + 1].isalpha():
                    nm = ANN_NAME.match(s, p + 1)
                    q = q2 = nm.end()
                    while q2 < len(s) and s[q2] in ' \t':
                        q2 += 1
                    args = ''
                    if s.startswith('(', q2):
                        e = src.close(q2)
                        if e < 0:
                            break
                        args, q = code[q2 + 1:e], e + 1
                    anns.append((nm.group().rsplit('.', 1)[-1], args, p))
                    p = q
                elif src.lang in ('cs', 'php') and (s.startswith('[', p) or s.startswith('#[', p)):
                    o = p + (1 if s[p] == '[' else 2)
                    if o >= len(s) or not s[o].isalpha():
                        break
                    inner, e = src.args(o - 1)
                    if e < 0:
                        break
                    for a, b in inner:
                        nm = re.match(r'\s*(?:\w+:\s*)?([\w.\\]+)\s*(?:\((.*)\))?\s*$', code[a:b], re.S)
                        if nm:
                            anns.append((re.split(r'[.\\]', nm.group(1))[-1], nm.group(2) or '', a))
                    p = e + 1
                else:
                    break
            done = p
            if not anns:
                continue
            if src.lang in ('cs', 'java', 'kt', 'js', 'php'):
                anns = [self.ann_alias(a, args, at) for a, args, at in anns]
            window = s[p:p + 600]
            cm = CLASS_DECL.match(window)
            if cm:
                blocks.append(('class', cm.group(1), anns, p))
                continue
            fm = FUN_DECL.match(window) if src.lang == 'kt' else None
            stop = min([i for i in (window.find('{'), window.find(';'), window.find('=>')) if i >= 0] or [len(window)])
            name = fm.group(1) if fm else next((c.group(1) for c in CALL_NAME.finditer(window[:stop + 1])
                                                if c.group(1) not in KEYWORDS), None)
            if name:
                blocks.append(('method', name, anns, p))
        for kind, name, anns, p in blocks:
            if kind == 'class':
                for c in classes:
                    if c[2] == name and p - 5 <= c[0] <= p + 300:
                        c[3] = self.class_meta(anns, name)
                        break
                for ann, args, at in anns:
                    if (ann in SOCKET_ANNS or 'Socket' in ann and ann != 'SocketIO') and src.lang in ('java', 'kt', 'cs'):
                        path = re.search(r'''\bpath\s*=\s*"([^"]*)"''', args)
                        path = path.group(1) if path else ann_path(args)
                        if path and path.startswith('/'):
                            cls = [n for _, _, n in self.by_file.get(rel, []) if self.g.nodes[n]['kind'] == 'class'
                                   and self.g.nodes[n]['name'].rsplit('.', 1)[-1] == name]
                            self.route(src, at, '', ['GET'], path, cls[0] if cls else self.decl_after(src, p, name))
        for c in classes:
            if not c[3].get('prefix'):
                inherited = self.inherited_prefix(s[c[0]:c[0] + 2000], c[2])
                if inherited:
                    c[3] = {**c[3], 'prefix': inherited, 'client': c[3].get('client', False), 'version': c[3].get('version')}
        for kind, name, anns, p in blocks:
            if kind != 'method':
                continue
            owner = None
            for c in classes:
                if c[0] <= p <= c[1] and (owner is None or c[0] >= owner[0]):
                    owner = c
            cname = owner[2] if owner else None
            fid = f'f:{rel}:{cname}.{name}'
            fn = fid if fid in self.g.nodes else self.decl_after(src, p, name)
            meta = dict(owner[3]) if owner else {}
            if owner and src.lang == 'cs' and re.match(r'interface\b', s[owner[0]:owner[0] + 10]):
                meta['client'] = True
            self.method_annotations(src, p, anns, meta, cname, name, fn)

    def ann_alias(self, ann, args, at):
        """Atributo/anotación del repo que hereda de uno reconocido (`RestPostById` -> `HttpPost`); un atributo de ruta propio con
        plantilla construida en el constructor se convierte en `Route` con la plantilla evaluada."""
        if ann in KNOWN_ANNS or not self.alias_bases:
            return ann, args, at
        alias = self.framework_alias(ann, KNOWN_ANNS)
        if alias:
            if not args.strip() and ann + 'Attribute' in self.alias_texts:
                # plantilla fija del atributo propio: `public RestDeleteByIdAttribute() : base("{id:int}")`
                text = self.text(self.alias_texts[ann + 'Attribute']) or ''
                fixed = re.search(rf'\b{re.escape(ann)}Attribute\s*\(\s*\)\s*:\s*base\s*\(\s*("[^"]*")\s*\)', text)
                if fixed:
                    args = fixed.group(1)
            return alias, args, at
        tpl = self.attribute_template(ann, args) if ann + 'Attribute' in self.alias_texts else None
        if tpl:
            return 'Route', f'"{tpl}"', at
        return ann, args, at

    def class_meta(self, anns, name):
        meta = {'prefix': '', 'client': False, 'version': None}
        for ann, args, at in anns:
            if ann == 'Version':
                meta['version'] = nest_version(args)
            if ann == 'Path':
                meta['path_at'] = at
            if ann in ('RequestMapping', 'Path', 'Controller', 'RestController', 'Route', 'HttpExchange', 'RoutePrefix'):
                path = ann_path(args)
                if ann == 'Controller' and not path:
                    m = re.search(r'''\bpath\s*:\s*['"`]([^'"`]*)''', args)
                    path = m.group(1) if m else ''
                    if re.search(r'\bversion\s*:', args):
                        meta['version'] = nest_version(args.split('version', 1)[1])
                if path:
                    meta['prefix'] = path.replace('[controller]', re.sub(r'Controller$', '', name))
                meta['client'] = meta['client'] or ann == 'HttpExchange'
            elif ann in PRODUCER_CLASS_ANNS:
                meta['producer'] = True
            elif ann in ('RegisterRestClient', 'Client'):
                meta['client'] = True
                m = re.search(r'''\bpath\s*=\s*"([^"]*)"''', args)
                if m:
                    meta['prefix'] = m.group(1)
            elif ann == 'FeignClient':
                meta['client'] = True
                m = re.search(r'''\bpath\s*=\s*"([^"]*)"''', args)
                if m:
                    meta['prefix'] = m.group(1)
        return meta

    def method_annotations(self, src, p, anns, meta, cname, name, fn):
        verbs, path, kind, jax, at_verb, version = [], None, None, None, None, meta.get('version')
        for ann, args, at in anns:
            if ann in SPRING_VERB and src.lang in ('java', 'kt'):
                verbs.append(SPRING_VERB[ann])
                path, kind = ann_path(args), 'exchange' if ann.endswith('Exchange') else 'spring'
                found = re.findall(r'RequestMethod\.(\w+)', args)
                if ann == 'RequestMapping' and found:
                    verbs = found
            elif ann in CAP_VERB and src.lang in ('js', 'java', 'kt'):
                verbs.append(CAP_VERB[ann])
                path, kind = ann_path(args), 'nest'
            elif ann in CAP_VERB and src.lang == 'cs' and meta.get('client') and args.strip():
                verbs.append(CAP_VERB[ann])
                path, kind = ann_path(args), 'retrofit'
            elif ann in VERBS and src.lang in ('java', 'kt'):
                verbs.append(ann)
                if args.strip():
                    path, kind = ann_path(args), 'retrofit'
                else:
                    kind = kind or 'jaxrs'
            elif ann == 'Path' and src.lang in ('java', 'kt'):
                jax = ann_path(args)
            elif ann in NET_VERB and src.lang == 'cs':
                verbs.append(NET_VERB[ann])
                path, kind = (ann_path(args) if args.strip() else (path or '')), 'net'
            elif ann == 'Route' and src.lang in ('cs', 'php'):
                path, kind = ann_path(args), kind or ('net' if src.lang == 'cs' else 'symfony')
                mm = re.search(r'methods\s*:\s*\[([^\]]*)\]', args) if src.lang == 'php' else None
                if mm:
                    verbs += quoted_all(mm.group(1))
            elif ann in GQL_ANNS and src.lang in ('js', 'java', 'kt') and fn and not args.strip().startswith(('"', "'", '`')):
                field = re.search(r'''\b(?:name|field)\s*[:=]\s*['"](\w+)''', args)
                self.gql_endpoint(src.rel, src.line(at), GQL_ANNS[ann], field.group(1) if field else name, fn)
            elif ann == 'Version' and src.lang == 'js':
                version = nest_version(args)
            elif ann in CONSUMER_ANNS:
                self.consumer_annotation(src, ann, args, at, fn)
            elif ann in TYPED_LISTENER_ANNS and src.lang in ('java', 'kt') and fn and not self.is_test(src.rel):
                sig = re.search(rf'\b{re.escape(name)}\s*\(\s*(?:@\w+(?:\([^)]*\))?\s+)*(?:final\s+)?(?:\w+\s*:\s*)?([A-Z]\w*)',
                                src.code[p:p + 400])
                if sig:
                    self.typed_msgs.append((sig.group(1), src.rel, src.line(at), 'sub', fn))
            elif ann in CHANNEL_ANNS and src.lang in ('java', 'kt') and fn and not self.is_test(src.rel):
                role = CHANNEL_ANNS[ann] or ('pub' if meta.get('producer') else 'sub')
                open_pos = src.struct.find('(', at)
                spans, _ = src.args(open_pos) if open_pos > 0 else ([], -1)
                for key in self.arg_keys(src, spans, ('value', 'topics', 'name')):
                    self.channel_uses.append((key, src.rel, src.line(at), role, fn))
            if at_verb is None and kind is not None and ann not in ('Path', 'Route', 'Version'):
                at_verb = at
            if ann in LISTENERS and src.lang in ('java', 'kt'):
                for key in LISTENERS[ann]:
                    mm = re.search(rf'\b{key}\s*=\s*\{{?([^}})]*)', args)
                    names = quoted_all(mm.group(1)) if mm else ([] if '=' in args.split('"')[0] else quoted_all(args))
                    if names:
                        for t in names:
                            if not t.startswith('$') and '#{' not in t:
                                self.topic_uses.append((t, src.rel, src.line(at), 'sub', fn or '', 'mq'))
                        break
        if kind == 'jaxrs':
            path = jax or ''
            if jax is None and meta.get('path_at') is not None and not meta.get('client'):
                at_verb = meta['path_at']
        if kind is None or path is None:
            return
        full = path.lstrip('~') if kind == 'net' and path.startswith(('/', '~/')) else '/' + '/'.join(x.strip('/') for x in (meta.get('prefix') or '', path) if x.strip('/'))
        full = full.replace('[controller]', re.sub(r'Controller$', '', cname or '')).replace('[action]', name)
        verbs = main_verbs(verbs)
        at_verb = p if at_verb is None else at_verb
        if kind in ('retrofit', 'exchange') or meta.get('client'):
            sym = fn or self.owner(src.rel, src.line(p))
            for v in verbs:
                self.client(src, p, v, full, sym)
            if sym:
                self.declared_clients.add(sym)
        elif kind == 'nest':
            if not self.is_test(src.rel):
                self.nest.append((src.rel, src.line(at_verb), tuple(verbs), full, fn or '', version))
        else:
            self.route(src, at_verb, '', verbs, full, fn)

    def consumer_annotation(self, src, ann, args, at, fn):
        if not fn or self.is_test(src.rel):
            return
        open_pos = src.struct.find('(', at)
        spans, _ = src.args(open_pos) if open_pos > 0 else ([], -1)
        for key in self.arg_keys(src, spans, CONSUMER_KEYS):
            self.topic_uses.append((key, src.rel, src.line(at), 'sub', fn, 'mq'))

    def arg_keys(self, src, spans, names, positional=0):
        if len(spans) == 1 and src.struct[src.skip(spans[0][0]):].startswith('{'):
            inner, _ = src.args(src.skip(spans[0][0]))
            spans = inner
        named = {}
        plain = []
        for a, b in spans:
            kw = re.match(r'\s*([A-Za-z_]\w*)\s*(?::(?!:)|=(?![=>]))\s*', src.struct[a:b])
            if kw:
                named[kw.group(1)] = a + kw.end()
            else:
                plain.append(a)
        for name in names:
            if name in named:
                key = self.topic_key(src, named[name])
                return [key] if key else []
        if len(plain) > positional:
            key = self.topic_key(src, plain[positional])
            return [key] if key else []
        return []

    def topic_key(self, src, pos):
        pos = src.skip(pos)
        val = src.expr(pos)
        if val is not None and '\0' not in val and re.fullmatch(r'[\w.\-:/*#>]+', val):
            return val
        if val and re.fullmatch(r'[A-Za-z][\w.\-]{2,}[:./\-][\w.\-:/\x00]*', val) and re.fullmatch(r'[\w.\-:/*\x00]+', val):
            return re.sub('\0+', '*', val)
        m = re.match(r'(?:this\.|self\.)?([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*(?:\(\s*\))?)\s*(?=[,)}\]]|$)', src.code[pos:pos + 200])
        if m and not src.literal(pos) and (re.fullmatch(r'[A-Z][A-Z0-9_]+', m.group(1)) or re.match(r'[A-Z]\w*\.', m.group(1))):
            return re.sub(r'\s+', '', m.group(1))
        return None

    def scan_path_builders(self, src):
        code, s = src.code, src.struct
        assigns = defaultdict(list)
        for m in re.finditer(r'(\bthis\.)?\b(\w+)\s*=(?!=)\s*', s):
            end = self.statement_end(src, m.end())
            if PATH_CALL.search(s, m.end(), end):
                assigns[m.group(2)].append((m.start(), m.end(), end, bool(m.group(1))))

        def resolve(start, end, depth=0):
            root = re.match(r'\s*(?:this\.)?(\w+)\s*(?:\.|$)', s[start:end])
            base = ''
            if root and root.group(1) in assigns and depth < 4:
                scope = self.function_at(src, start)
                prior = [a for a in assigns[root.group(1)] if a[1] <= start and (a[3] or self.function_at(src, a[0]) in (scope, None))]
                if prior:
                    base = resolve(prior[-1][1], prior[-1][2], depth + 1) or ''
            for p in PATH_CALL.finditer(s, start, end):
                arg = src.expr(p.end())
                part = arg if arg is not None else '\0'
                base = part if p.group(1) == 'target' else base.rstrip('/') + '/' + part.lstrip('/')
            return base

        for m in re.finditer(r'\.\s*request\s*\(', s):
            stmt = max(s.rfind(';', 0, m.start()), s.rfind('{', 0, m.start()), s.rfind('}', 0, m.start())) + 1
            lead = list(re.finditer(r'(?<![=!<>])=(?![=>])|\breturn\b', s[stmt:m.start()]))
            start = stmt + lead[-1].end() if lead else stmt
            end = self.statement_end(src, m.start())
            verb = re.search(r'\.\s*(get|post|put|delete|patch|head|method)\s*\(', s[m.end():end])
            path = resolve(start, m.start())
            if not verb or not re.search('[A-Za-z]', path.replace('\0', '')):
                continue
            method = verb.group(1).upper()
            if method == 'METHOD':
                method = (first_string(code[m.end() + verb.end():end]) or 'ANY').upper()
            self.client(src, src.skip(start), method, path if path.startswith(('\0', '/')) or SCHEME.match(path) else '\0/' + path)

    def scan_channels(self, src):
        code, rel = src.code, src.rel
        for m in CHANNEL_FIELD.finditer(code):
            name, var, typ = m.group(1), m.group(2) or m.group(5), (m.group(3) or m.group(4)).rsplit('.', 1)[-1]
            name = name.strip('"') if name.startswith('"') else src.const_value(name)
            if not name:
                continue
            if 'Emitter' not in typ:
                self.channel_uses.append((name, rel, src.line(m.start()), 'sub', ''))
                continue
            names = {var} | set(re.findall(rf'\bthis\.(\w+)\s*=\s*{re.escape(var)}\s*;', code))
            alts = '|'.join(sorted(map(re.escape, names)))
            for u in re.finditer(rf'(?<![\w.])(?:this\.)?(?:{alts})\s*(?:\.|::)\s*send\w*\b', code):
                self.channel_uses.append((name, rel, src.line(u.start()), 'pub', ''))

    def scan_java_clients(self, src):
        code = src.code
        for m in re.finditer(r'\bRequest\.Builder\(\)', code) if 'Builder' in code else ():
            end = self.statement_end(src, m.start())
            url = re.search(r'\.\s*url\s*\(', src.struct[m.end():end])
            if url:
                verb = re.search(r'\.\s*(post|put|patch|delete|head)\s*\(', src.struct[m.end():end])
                self.client(src, m.start(), verb.group(1) if verb else 'GET', src.expr(m.end() + url.end()))
        if '@Channel' in code and not self.is_test(src.rel):
            self.scan_channels(src)
        for m in re.finditer(r'\b\w*[Bb]ridge\s*\.\s*send\(\s*"([\w.\-]+)"', code) if 'ridge' in code and not self.is_test(src.rel) else ():
            self.channel_uses.append((m.group(1), src.rel, src.line(m.start()), 'pub', ''))
        if '.request(' in code and ('.path(' in code or '.target(' in code):
            self.scan_path_builders(src)
        for m in JAVA_CLIENT.finditer(code):
            verb = m.group(1)
            if verb in ('put', 'delete', 'exchange') and not re.search(r'(?i)(rest|template|client)\w*\s*$', code[max(0, m.start() - 40):m.start()]):
                continue
            args, end = src.args(paren(m))
            if not args:
                continue
            if verb == 'exchange':
                hm = re.search(r'HttpMethod\.(\w+)', code[m.end():end])
                method = hm.group(1) if hm else 'ANY'
            else:
                method = re.match(r'[a-z]+', verb).group()
            self.client(src, m.start(), method, src.expr(args[0][0]))
        for m in JAVA_WEBCLIENT.finditer(code):
            self.client(src, m.start(), m.group(1), src.expr(m.end()))
        if '@Value' in code:
            fields = {f.group(2): f.group(1) for f in JAVA_VALUE_FIELD.finditer(code)}
            if fields:
                names = '|'.join(map(re.escape, sorted(fields, key=len, reverse=True)))
                for m in re.finditer(rf'\b(?:http|uri|baseUrl|create|url|rootUri)\s*\(\s*(?:this\.)?({names})\s*[,)]', code):
                    self.config_url_refs.append((src.rel, src.line(m.start()), fields[m.group(1)]))
        if self.is_test(src.rel):
            return
        for m in JAVA_FN_ROUTE.finditer(code):
            args, end = src.args(paren(m))
            if len(args) >= 2:
                self.route(src, m.start(), '', [m.group(1)], src.expr(args[0][0]), self.handler(src, *args[1], src.line(m.start())))
        for m in JAVA_LITE_ROUTE.finditer(code):
            if m.group(1) in GENERIC_NOT_CLIENT - {'app', 'router', 'route', 'routes', 'server'} or re.search(r'(?i)client|http$', m.group(1)):
                continue
            args, end = src.args(paren(m))
            line = src.line(m.start())
            if len(args) >= 2:
                fn = self.handler(src, *args[-1], line)
            else:
                chained = re.match(r'\s*\.\s*(?:handler|blockingHandler|respond|handle)\s*\(', code[end + 1:end + 80]) if end > 0 else None
                if not chained and src.struct[src.skip(end + 1):src.skip(end + 1) + 1] == '{' and end > 0:
                    self.route(src, m.start(), m.group(1), [m.group(2).upper()], src.expr(args[0][0]), self.owner(src.rel, line), strict=True)
                if not chained:
                    continue
                cargs, _ = src.args(end + 1 + chained.end() - 1)
                fn = self.handler(src, *cargs[0], line) if cargs else None
            self.route(src, m.start(), m.group(1), [m.group(2).upper()], src.expr(args[0][0]), fn, strict=True)
        for m in JAVA_PROXY_ROUTE.finditer(code):
            end = src.close(paren(m))
            if end < 0 or not re.match(r'\s*,\s*(?:\w+\.)*(?:http|https|forward|lb)\s*\(', code[end + 1:end + 120]):
                continue
            path = src.expr(m.end())
            if path:
                self.proxies.append((src.rel, src.line(m.start()), drop_base(path).rstrip('*').rstrip('/') or '/'))

    def scan_ktor(self, src):
        code, rel = src.code, src.rel
        if 'io.ktor.server' in code and not self.is_test(rel):
            for m in KT_ROUTE_FN.finditer(code):
                brace = code.find('{', m.end())
                end = src.close(brace) if brace > 0 else -1
                if end > 0 and not self.decl_after(src, m.start(), m.group(1)):
                    self.add_function(rel, m.group(1), src.line(m.start()), src.line(end))
            scopes = [(m.end() - 1, src.close(m.end() - 1), m.group(1)) for m in KT_ROUTE_SCOPE.finditer(code)]
            for m in KT_VERB.finditer(code):
                line = src.line(m.start())
                self.route(src, m.start(), '', [m.group(1).upper()], m.group(2) or '', self.owner(rel, line),
                           self.scopes_at(scopes, m.start()))
            for m in KT_ROUTE_FN.finditer(code):
                fn = self.decl_after(src, m.start(), m.group(1))
                if fn:
                    self.kt_route_fns[m.group(1)].append(fn)
            for m in KT_CALL.finditer(code):
                line = src.line(m.start())
                self.kt_calls.append((rel, line, m.group(1), self.scopes_at(scopes, m.start()), self.owner(rel, line) or ''))
        if 'lient' not in code:
            return
        for m in KT_CLIENT.finditer(code):
            verb, p, raw, tpl, body = m.group(2), m.end(), None, None, None
            if code.startswith('(', p):
                args, end = src.args(p)
                if args:
                    a, b = args[0]
                    raw = code[a:b].strip()
                    kw = re.match(r'\s*urlString\s*=\s*', code[a:b])
                    tpl = src.expr(a + (kw.end() if kw else 0)) if not raw.startswith('{') else None
                nxt = src.skip(end + 1) if end > 0 else -1
                if nxt > 0 and code.startswith('{', nxt):
                    body = (nxt, src.close(nxt))
            else:
                body = (p, src.close(p))
            if tpl is None and body and body[1] > 0:
                tpl = self.kt_builder_url(src, *body)
            method = re.sub(r'^prepare', '', verb).upper()
            if method in ('REQUEST', 'SUBMITFORM'):
                hm = re.search(r'HttpMethod\.(\w+)', code[p:body[1]] if body and body[1] > 0 else '')
                method = hm.group(1) if hm else ('POST' if method == 'SUBMITFORM' else 'ANY')
            if tpl is None and raw:
                self.param_wrapper(src, m.start(), raw, method)
            self.client(src, m.start(), method, tpl)
        self.wrapper_calls(src)

    def add_function(self, rel, name, line, end):
        nid = f'f:{rel}:{name}'
        if nid in self.g.nodes:
            return nid
        self.declare(nid, 'function', name, rel, line)
        self.g.nodes[nid].update(end=end, lang=self.g.nodes.get(f'm:{rel}', {}).get('lang'))
        items = self.by_file[rel]
        items.append((line, end, nid))
        items.sort()
        self.starts[rel] = [x[0] for x in items]
        self.short[name].append(nid)
        self.full[name].append(nid)
        return nid

    def kt_builder_url(self, src, a, b, depth=0):
        code = src.code
        for m in KT_URL.finditer(code, a, b):
            tpl = src.expr(m.end())
            if tpl is not None:
                return '/' + tpl.lstrip('/') if 'encodedPath' in m.group() and not SCHEME.match(tpl) else tpl
        if depth > 1:
            return None
        for m in re.finditer(r'(?<![\w.])(\w+)\s*\(\s*(?=["])', code[a:b]):
            lit = src.literal(src.skip(a + m.end()))
            helper = re.search(rf'\bfun\s+(?:[\w.<>]+\.)?{re.escape(m.group(1))}\s*\(\s*(\w+)\s*:', code)
            if not lit or not helper:
                continue
            brace = code.find('{', helper.end())
            end = src.close(brace) if brace > 0 else -1
            if end < 0:
                continue
            param = re.escape(helper.group(1))
            body = re.sub(rf'\$\{{?{param}\b\}}?', lambda _: lit[0], src.text[brace:end])
            body = re.sub(rf'([=(,]\s*){param}\b(?!\s*[:=(.])', lambda x: x.group(1) + '"' + lit[0] + '"', body)
            inner = Src(src.rel, src.lang, src.text[:brace] + body + src.text[end:])
            found = self.kt_builder_url(inner, brace, inner.close(brace), depth + 1)
            if found is not None:
                return found
        return None

    def param_wrapper(self, src, pos, raw, method, base=None):
        if not re.fullmatch(r'[A-Za-z_$][\w$]*', raw):
            return
        sym = self.owner(src.rel, src.line(pos))
        meta = self.g.nodes.get(sym) or {}
        if meta.get('kind') not in ('function', 'method') or not meta.get('line'):
            return
        lines = src.code.split('\n')[meta['line'] - 1:meta['line'] + 3]
        head = ' '.join(lines)
        name = meta['name'].rsplit('.', 1)[-1]
        sig = re.search(rf'\b{re.escape(name)}\s*(?:<[^()]*>)?\s*\(([^)]*)\)', head)
        if not sig:
            return
        params = [param_name(p, src.lang) for p in sig.group(1).split(',')]
        if raw in params:
            self.wrappers[src.rel].append((name, params.index(raw), method, sym, base))

    def wrapper_calls(self, src):
        for name, index, method, sym, base in self.wrappers.pop(src.rel, []):
            for m in re.finditer(rf'(?<![\w$.])(?:this\.|self\.)?{re.escape(name)}\s*(?:<[^<>()]*>)?\s*\(', src.code):
                head = src.code[max(0, m.start() - 40):m.start()]
                if re.search(r'\b(?:fun|function|def|func|fn)\s+(?:[\w.<>]+\.)?$|\b(?:fun|function|def|func|fn)\s+<[^>]*>\s*$', head):
                    continue
                args, end = src.args(paren(m))
                if len(args) > index:
                    caller = self.owner(src.rel, src.line(m.start()))
                    if caller != sym:
                        self.client(src, m.start(), method, with_base(base, src.expr(args[index][0])), caller)

    def scan_dart(self, src):
        code, rel = src.code, src.rel
        dirs = rel.split('/')[:-1]
        stem = os.path.splitext(rel.rsplit('/', 1)[-1])[0]
        if 'routes' not in dirs or stem.startswith('_') or not re.search(r'\bonRequest\s*\(', code) or self.is_test(rel):
            return
        i = len(dirs) - 1 - dirs[::-1].index('routes')
        path = '/'.join([next_seg(p) for p in dirs[i + 1:]] + ([] if stem == 'index' else [next_seg(stem)]))
        entry = re.search(r'\bonRequest\s*\(', code)
        fn = self.owner(rel, src.line(entry.start()))
        cases = list(re.finditer(r'\bcase\s+HttpMethod\.(\w+)\s*:', code))
        if not cases:
            self.route(src, entry.start(), '', ['ANY'], path, fn)
            return
        for k, m in enumerate(cases):
            j = k
            while j + 1 < len(cases) and not code[cases[j].end():cases[j + 1].start()].strip():
                j += 1
            stop = cases[j + 1].start() if j + 1 < len(cases) else min(len(code), cases[j].end() + 2000)
            body = code[cases[j].end():stop]
            if re.search(r'\bmethodNotAllowed\b|\bstatusCode\s*:\s*405\b', body.split(';', 1)[0]):
                continue
            target = None
            for c in re.finditer(r'(?<![\w.$])(\w+)\s*(?:<[^<>()]*>)?\s*\(', body):
                target = self.in_file(rel, c.group(1)) if c.group(1) not in KEYWORDS else None
                if target and target != fn:
                    break
                target = None
            self.route(src, m.start(), '', [m.group(1).upper()], path, target or fn)

    def scan_generic_clients(self, src):
        code, rel = src.code, src.rel
        if self.is_test(rel) or not GENERIC_CLIENT_HINT.search(code):
            return
        servers = self.js_server_vars(src) if src.lang == 'js' else set()
        for m in GENERIC_CLIENT.finditer(code):
            chain = re.split(r'\s*\??\.\s*', m.group(1))
            if chain[0] in servers or chain[-1] in servers or chain[-1] in GENERIC_NOT_CLIENT:
                continue
            line = src.line(m.start())
            if (rel, line) in self.route_lines:
                continue
            args, end = src.args(paren(m))
            if not args:
                continue
            last = src.struct[args[-1][0]:args[-1][1]].strip()
            if len(args) > 1 and (INLINE.match(last) and not last.startswith(('{', '(')) or '=>' in last or last.startswith('func')):
                continue
            verb = m.group(2).upper()
            if verb in ('REQUEST', 'FETCH', 'SEND', 'EXCHANGE'):
                tpl = self.js_url_arg(src, args[0]) if src.lang == 'js' else src.expr(args[0][0])
                mm = METHOD_KW.search(code[m.end():end]) or re.search(r'\b(?:HttpMethod|Method)\.(\w+)', code[m.end():end])
                verb = mm.group(1).upper() if mm else 'ANY'
            else:
                tpl = self.js_url_arg(src, args[0]) if src.lang == 'js' else src.expr(args[0][0])
            self.weak_client(src, line, verb, tpl)

    def weak_client(self, src, line, verb, tpl):
        path = client_path(tpl)
        if path is None or not any(s != ':' for s in segments(path)):
            return
        sym = self.owner(src.rel, line)
        if sym:
            item = (src.rel, line, verb if verb in VERBS else 'ANY', path, sym)
            self.weak_clients.append(item)
            if re.match(r'\s*(?:[a-zA-Z][\w+.-]*:)?(?://)?\x00', tpl):
                self.based.add(item)

    def scan_typed_messages(self, src):
        code, rel, lang = src.code, src.rel, src.lang
        add = lambda t, pos, role, sym='': self.typed_msgs.append((t, rel, src.line(pos), role, sym))
        if lang in ('java', 'kt'):
            for m in re.finditer(r'\b(?:publishEvent|post|publish|send|dispatch)\s*\(\s*(?:new\s+)?([A-Z]\w*)\s*\(', code):
                add(m.group(1), m.start(), 'pub')
            for m in re.finditer(r'\bclass\s+(\w+)[^{]*?\bApplicationListener\s*<\s*(\w+)\s*>', code):
                fn = self.in_file(rel, 'onApplicationEvent')
                if fn:
                    add(m.group(2), m.start(), 'sub', fn)
        elif lang == 'php':
            for m in re.finditer(r'\b([A-Z]\w*)::dispatch(?:Sync|Now|AfterResponse|If|Unless)?\s*\(|'
                                 r'(?:\b(?:dispatch|dispatch_sync|event|broadcast)|->\s*dispatch|::push|::dispatch)\s*\(\s*new\s+\\?(?:\w+\\)*([A-Z]\w*)', code):
                add(m.group(1) or m.group(2), m.start(), 'pub')
            cls = re.search(r'\bclass\s+(\w+)', code)
            if cls and re.search(r'\bimplements\s+[^{]*\bShouldQueue\b', code):
                fn = self.in_file(rel, 'handle')
                if fn:
                    add(cls.group(1), cls.start(), 'sub', fn)
            if cls and (re.search(r'AsMessageHandler|MessageHandlerInterface', code) or '/Listeners/' in '/' + rel):
                for m in re.finditer(r'\bfunction\s+(handle|__invoke)\s*\(\s*\\?(?:\w+\\)*([A-Z]\w*)\s+\$', code):
                    fn = self.in_file(rel, m.group(1))
                    if fn:
                        add(m.group(2), m.start(), 'sub', fn)
        elif lang == 'cs':
            for m in re.finditer(r'\b(BackgroundJob|RecurringJob)\.(?:Enqueue|Schedule|AddOrUpdate|ContinueJobWith)\s*<\s*(\w+)\s*>\s*\('
                                 r'[^;]*?\b(\w+)\s*=>\s*\3\s*\.\s*(\w+)\s*\(', code):
                key = f'{m.group(2)}.{m.group(4)}'
                add(key, m.start(), 'sub' if m.group(1) == 'RecurringJob' else 'pub')
                for fn in self.full.get(key, []):
                    self.typed_msgs.append((key, self.g.nodes[fn]['file'], self.g.nodes[fn]['line'], 'sub', fn))
        elif lang == 'ex':
            for m in re.finditer(r'^\s*use\s+Oban\.(?:Worker|Pro\.Worker)\b', code, re.M):
                mod = next((n for p, n in reversed([(x.start(), x.group(1)) for x in EX_DEFMODULE.finditer(code)]) if p < m.start()), None)
                fn = next(iter(self.full.get(f'{mod}.perform', [])), None) if mod else None
                if fn:
                    add(mod, m.start(), 'sub', fn)
            for m in re.finditer(r'\b([A-Z][\w.]*)\.new\(', code):
                add(m.group(1), m.start(), 'pub')

    def finish_typed_messages(self):
        subs = {t for t, rel, line, role, sym in self.typed_msgs if role == 'sub'}
        short = defaultdict(set)
        for t in subs:
            short[t.rsplit('.', 1)[-1]].add(t)
        for t, rel, line, role, sym in self.typed_msgs:
            cands = {t} if t in subs else short.get(t) or short.get(t.rsplit('.', 1)[-1]) or set()
            if len(cands) == 1:
                self.topic_uses.append((next(iter(cands)), rel, line, role, sym, 'mq'))

    def scan_messaging(self, src):
        code, rel = src.code, src.rel
        if self.is_test(rel):
            return
        if src.lang in ('java', 'kt', 'php', 'cs', 'ex'):
            self.scan_typed_messages(src)
        for m in re.finditer(r'''\bnew\s+Worker\s*\(\s*(['"`])([\w:.\-]+)\1\s*,\s*([\w.$]+)''', code) if src.lang == 'js' else ():
            fn = self.resolve(m.group(3), rel, src.line(m.start()))
            self.topic_uses.append((m.group(2), rel, src.line(m.start()), 'sub', fn or '', 'weak'))
        if 'switch' in code or 'ublish' in code or 'roduc' in code:
            self.scan_dispatch(src)
        if not MSG_HINT.search(code):
            return
        for m in MSG_CALL.finditer(code):
            name = m.group(1)
            role = 'pub' if name in MSG_PUB else 'sub'
            recv = code[max(0, m.start() - 60):m.start() + 1]
            if name in ('add', 'process') and not re.search(r'[Qq]ueue\w*\s*\.?\s*$', recv):
                continue
            args, end = src.args(paren(m))
            if not args:
                continue
            keys = self.arg_keys(src, args, MSG_KEYS)
            if keys == [''] and len(args) > 1:
                keys = self.arg_keys(src, args, (), positional=1)
            if not keys or not keys[0] or role == 'sub' and src.literal(src.skip(args[0][0])) is None and len(args) == 1 \
                    and src.expr(args[0][0]) is None and not re.match(r'\s*\w+\s*=(?!=)', src.struct[args[0][0]:args[0][1]]):
                declared = self.declared_queue(src, m.start())
                keys = [declared] if declared else []
            if name.lower() in ('xread', 'xreadgroup'):
                found = re.search(r'''['"]STREAMS['"]\s*,\s*['"]([\w:.\-]+)|\{\s*['"]([\w:.\-]+)['"]\s*:|Streams:\s*\[\]string\{\s*"([\w:.\-]+)"''',
                                  code[m.end():end])
                keys = [next(x for x in found.groups() if x)] if found else []
            elif src.lang == 'py' and name.startswith('enqueue') and args:
                a = args[0][0] if name != 'enqueue_in' and name != 'enqueue_at' else (args[1][0] if len(args) > 1 else None)
                fn = re.match(r'\s*(?:func\s*=\s*)?([\w.]+)\s*$', code[a:args[0 if a == args[0][0] else 1][1]]) if a is not None else None
                target = self.resolve(fn.group(1), rel) if fn else None
                if target and self.g.nodes[target]['kind'] in ('function', 'method'):
                    key = 'job:' + self.g.nodes[target]['name']
                    self.topic_uses.append((key, rel, src.line(m.start()), 'pub', '', 'mq'))
                    self.topic_uses.append((key, self.g.nodes[target]['file'], self.g.nodes[target]['line'], 'sub', target, 'mq'))
                    continue
            if not keys or not keys[0]:
                continue
            key = re.split(r'[/:]', keys[0].rstrip('/'))[-1] if re.match(r'(?:https?://|arn:)', keys[0]) else keys[0]
            sym = self.callback_target(src, args, m.start()) if role == 'sub' else ''
            self.topic_uses.append((key, rel, src.line(m.start()), role, sym or '', 'weak'))
            declared = self.declared_queue(src, m.start()) if name == 'add' else None
            if declared and declared != key:
                self.topic_uses.append((declared, rel, src.line(m.start()), role, '', 'weak'))
        for m in re.finditer(r'\bnew\s+(SendMessageCommand|SendMessageBatchCommand|ReceiveMessageCommand|PublishCommand)\s*\(\s*\{', code):
            args, _ = src.args(m.end() - 1)
            keys = self.arg_keys(src, args, ('QueueUrl', 'TopicArn'))
            if keys and keys[0]:
                key = re.split(r'[/:]', keys[0].rstrip('/'))[-1] if re.match(r'(?:https?://|arn:)', keys[0]) else keys[0]
                role = 'sub' if m.group(1).startswith('Receive') else 'pub'
                self.topic_uses.append((key, rel, src.line(m.start()), role, '', 'weak'))

    def scan_dispatch(self, src):
        code, rel = src.code, src.rel
        for m in MSG_CONFIG.finditer(code):
            role = 'pub' if re.search(r'[Pp]ublish|[Pp]roduc|[Ss]ender|[Ee]mitter', m.group(1)) else 'sub'
            lit = src.literal(src.skip(m.end()))
            if lit and re.fullmatch(r'[\w.\-:/]+', lit[0]):
                self.topic_uses.append((lit[0], rel, src.line(m.start()), role, '', 'weak'))
        for m in MSG_SWITCH.finditer(code):
            brace = m.end() - 1
            end = src.close(brace)
            if end < 0:
                continue
            cases = [c for c in re.finditer(r'\bcase\s+(?=["\'])', code[brace:end])]
            for i, c in enumerate(cases):
                pos = brace + c.end()
                lit = src.literal(pos)
                if not lit or not re.fullmatch(r'[\w.\-:/]+', lit[0]):
                    continue
                stop = brace + cases[i + 1].start() if i + 1 < len(cases) else end
                body = code[lit[1]:stop]
                handler = self.typed_dispatch(body, rel)
                self.topic_uses.append((lit[0], rel, src.line(pos), 'sub', handler or '', 'weak'))

    def typed_dispatch(self, body, rel):
        types = {t.rsplit('.', 1)[-1] for t in re.findall(r'\bvar\s+\w+\s+\*?([\w.]+)|\b\w+\s*:=\s*&?([\w.]+)\s*\{', body) for t in t if t}
        types |= {t.rsplit('.', 1)[-1] for t in re.findall(r'\b[\w.]+\s*<\s*([\w.]+)\s*>\s*\(|\bas\s+([\w.]+)', body) for t in t if t}
        for c in re.finditer(r'\.\s*(\w+)\s*\(', body):
            cands = [n for n in self.short.get(c.group(1), []) if self.g.nodes[n]['kind'] in ('function', 'method')]
            typed = [n for n in cands if types & {t.rsplit('.', 1)[-1] for t in self.param_types(n)}]
            if len(typed) == 1:
                return typed[0]
        return None

    def declared_queue(self, src, pos):
        recv = re.search(r'([A-Za-z_$][\w$]*)\s*\.\s*$', src.code[max(0, pos - 80):pos + 1])
        if not recv:
            return None
        m = None
        for m in re.finditer(rf'\b{re.escape(recv.group(1))}\s*(?::\s*[\w<>.]+\s*)?=\s*(?:await\s+)?(?:new\s+[\w$.]*Queue\s*(?:<[^<>()]*>)?\s*\(|'
                             rf'[\w$.]+\s*\.\s*(?:declare_queue|queue_declare|assertQueue|QueueDeclare\w*|queue|Queue|subscription|topic)\s*\()',
                             src.code[:pos]):
            pass
        if not m:
            return None
        args, _ = src.args(m.end() - 1)
        keys = self.arg_keys(src, args, MSG_KEYS) if args else []
        return keys[0] if keys else None

    def callback_target(self, src, args, pos):
        rel = src.rel
        for a, b in reversed(args):
            text = src.code[a:b].strip()
            kw = re.match(r'(\w+)\s*[:=](?![=>])\s*', text)
            if kw:
                if kw.group(1) not in ('callback', 'on_message_callback', 'consumer', 'handler', 'onMessage', 'eachMessage'):
                    continue
                text = text[kw.end():]
            lam = re.match(r'(?:async\s+)?lambda\b[^:]*:\s*(?:await\s+)?([\w.]+)\s*\(', text) or \
                re.match(r'(?:async\s*)?\(?[\w\s,]*\)?\s*=>\s*(?:await\s+)?([\w.]+)\s*\([^{}]*$', text)
            if lam:
                found = self.resolve(lam.group(1), rel, src.line(pos))
                if found:
                    return found
            if re.fullmatch(r'[A-Za-z_$][\w$.]*', text) and text not in ('true', 'false', 'True', 'False', 'null', 'None'):
                found = self.resolve(text, rel, src.line(pos))
                if found and self.g.nodes[found]['kind'] in ('function', 'method'):
                    return found
        return None

    def scan_topic_refs(self, src):
        if not self.topic_refs or self.is_test(src.rel):
            return
        if getattr(self, 'topic_refs_rx', None) is None:
            alts = sorted((re.escape(r).replace(r'\(', r'\(\s*').replace(r'\ ', '') for r in self.topic_refs), key=len, reverse=True)
            self.topic_refs_rx = re.compile(r'(?<![\w$.])(%s)(?![\w$])' % '|'.join(alts))
        code = src.code
        for m in self.topic_refs_rx.finditer(code):
            start = code.rfind('\n', 0, m.start()) + 1
            head = code[start:m.start()]
            if re.search(r'\b(?:import|export)\s*(?:type\s*)?\{[^}]*$|\bfrom\s+\S+\s+import\s*\([^)]*$', code[max(0, m.start() - 2000):m.start()]):
                continue
            if IMPORT_LINE.match(head) or re.search(r'(?:==|!=|\bcase|\bexport|\bconst|\bstatic|\bfinal|\bval|\bdef)\s*$|[=!]==?\s*$', head) \
                    or re.match(rf'\s*{re.escape(m.group(1))}\s*(?::\s*\w+\s*)?=(?!=)', code[m.start():m.start() + 200]):
                continue
            if self.in_decorator(src, m.start()):
                continue
            key = self.topic_key(src, m.start())
            if key:
                self.topic_uses.append((key, src.rel, src.line(m.start()), 'pub', '', 'weak'))

    def in_decorator(self, src, pos):
        depth = 0
        for i in range(pos - 1, max(-1, pos - 600), -1):
            ch = src.struct[i]
            if ch in ')]}':
                depth += 1
            elif ch in '([{':
                if depth:
                    depth -= 1
                elif ch == '(' and re.search(r'@[\w.]+\s*$', src.struct[max(0, i - 80):i]):
                    return True
        return False

    def scan_cs(self, src):
        code, rel = src.code, src.rel
        for m in CS_GROUP.finditer(code):
            lit = src.expr(m.end())
            if lit is not None:
                self.local[rel][m.group(1)] = (m.group(2), drop_base(lit))
        for m in CS_MAP.finditer(code):
            args, end = src.args(paren(m))
            if len(args) < 2:
                continue
            if m.group(2) == 'Methods':
                if len(args) < 3:
                    continue
                spec = code[args[1][0]:args[1][1]]
                verbs = main_verbs(quoted_all(spec) + re.findall(r'\bHttpMethods?\.(\w+)', spec))
            else:
                verbs = [m.group(2).upper()]
            self.route(src, m.start(), m.group(1), verbs, src.expr(args[0][0]), self.handler(src, *args[-1], src.line(m.start())))
        for m in CS_CLIENT.finditer(code):
            verb = re.match(r'[A-Z][a-z]+', m.group(1)).group()
            self.client(src, m.start(), verb, src.expr(m.end()))
        for m in CS_REQUEST.finditer(code):
            self.client(src, m.start(), m.group(1), src.expr(m.end()))
        for m in CS_FORWARDER.finditer(code):
            args, end = src.args(paren(m))
            if len(args) >= 2:
                self.route(src, m.start(), m.group(1), ['ANY'], src.expr(args[0][0]), self.owner(rel, src.line(m.start())))
            if len(args) >= 3:
                self.client(src, m.start(), 'ANY', src.expr(args[2][0]))
        for m in re.finditer(r'\bMapHub\s*<\s*(\w+)\s*>\s*\(\s*"([^"]+)"', code):
            cls = self.pick(rel, [n for n in self.short.get(m.group(1), []) if self.g.nodes[n]['kind'] == 'class'])
            self.route(src, m.start(), '', ['ANY'], m.group(2), cls)
        for m in CS_MAP_EXT.finditer(code):
            if m.group(1) not in CS_MAP_BUILTIN and not self.is_test(rel):
                self.ext_mounts.append((rel, src.line(m.start()), m.group(1)))
        for m in CS_CONN_READ.finditer(code):
            self.env_uses.append((rel, src.line(m.start()), f'ConnectionStrings__{m.group(1) or m.group(2)}'))
        for m in CS_CONFIG_READ.finditer(code):
            self.soft_env_uses.append((rel, src.line(m.start()), m.group(1) or m.group(2)))
        if ('HotChocolate' in code or 'QueryType' in code or 'ExtendObjectType' in code or re.search(r'\bclass\s+(?:Query|Mutation)\b', code)) \
                and not self.is_test(rel):
            for m in re.finditer(r'(\[(?:QueryType|MutationType|SubscriptionType|ExtendObjectType[^\]]*)\]\s*)?(?:(?:public|internal|static|'
                                 r'partial|sealed)\s+)*class\s+(\w+)[^{]*\{', code):
                tag = (m.group(1) or '') + m.group(2)
                op = next((o for o in ('Mutation', 'Subscription', 'Query') if o in tag), None)
                if not op or not m.group(1) and m.group(2) not in ('Query', 'Mutation', 'Subscription'):
                    continue
                end = src.close(m.end() - 1)
                for f in re.finditer(r'\bpublic\s+(?:static\s+)?(?:async\s+)?(?:virtual\s+)?[\w<>\[\],.?]+\s+(\w+)\s*\(', code[m.end():end if end > 0 else len(code)]):
                    field = re.sub(r'Async$', '', re.sub(r'^Get(?=[A-Z])', '', f.group(1)))
                    line = src.line(m.end() + f.start())
                    self.gql_endpoint(rel, line, op, field, self.owner(rel, line))
        if 'DistributedApplication' in code:
            self.scan_apphost(src, 'Add')

    def scan_apphost(self, src, add):
        code, rel = src.code, src.rel
        if self.is_test(rel):
            return
        decl = re.compile(rf'(?:(?:var|const|let)\s+(\w+)\s*=\s*)?(?:await\s+)?(\w+)\s*\.\s*({add}[A-Z]\w*)\s*(?:<[^<>()]*>)?\s*\(\s*'
                          rf'''(?:name\s*:\s*)?["']([\w.-]+)["']''')
        var_of = {}
        for m in decl.finditer(code):
            stmt = self.statement_end(src, m.start())
            nid = self.add_resource(rel, m.group(4), src.line(m.start()), src.line(stmt))
            if m.group(1):
                var_of[m.group(1)] = (nid, m.group(4), m.group(3)[len(add):])
        for m in re.finditer(r'\.\s*(WithReference|WaitFor|WaitForCompletion|PublishWithContainerFiles|withReference|waitFor|'
                             r'waitForCompletion|publishWithContainerFiles)\s*\(\s*(\w+)', code):
            target = var_of.get(m.group(2))
            if not target:
                continue
            line = src.line(m.start())
            self.aspire_refs.append((rel, line, target[0]))
            if m.group(1).lower() == 'withreference':
                name = target[1]
                if target[2] in ASPIRE_APPS:
                    names = [f'services__{name}__http__0', f'services__{name}__https__0']
                else:
                    up = re.sub(r'\W', '_', name).upper()
                    names = [f'ConnectionStrings__{name}'] + [f'{up}_{x}' for x in ('URI', 'HOST', 'PORT', 'USERNAME', 'PASSWORD', 'DATABASENAME')]
                self.aspire_env += [(rel, line, n) for n in names]
        for m in re.finditer(r'''\.\s*(?:WithHttpEndpoint|WithHttpsEndpoint|WithEndpoint|withHttpEndpoint|withHttpsEndpoint|withEndpoint)'''
                             r'''\s*\([^()]*?\benv\s*:\s*["']([A-Za-z_]\w*)["']''', code):
            self.aspire_env.append((rel, src.line(m.start()), m.group(1)))
        for m in re.finditer(r'''\.\s*(?:WithEnvironment|withEnvironment)\s*\(\s*["']([A-Za-z_]\w*)["']''', code):
            self.aspire_env.append((rel, src.line(m.start()), m.group(1)))

    def statement_end(self, src, pos):
        depth = 0
        for m in re.finditer(r'[()\[\]{};]', src.struct[pos:pos + 20000]):
            ch = m.group()
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
                if depth < 0:
                    return pos + m.start()
            elif depth == 0:
                return pos + m.start()
        return min(len(src.struct) - 1, pos + 20000)

    def add_resource(self, rel, name, line, end):
        nid = f'c:{rel}:{name}'
        if nid in self.g.nodes:
            nid = f'c:{rel}:{name}@{line}'
        self.declare(nid, 'class', name, rel, line)
        self.g.nodes[nid].update(end=end, lang=self.g.nodes.get(f'm:{rel}', {}).get('lang'))
        self.add_item(rel, line, end, nid)
        self.short[name].append(nid)
        self.resources.append((name, nid))
        return nid

    def scan_go(self, src):
        code, rel = src.code, src.rel
        scopes = []
        for m in GO_ROUTE_BLOCK.finditer(code):
            brace = src.struct.find('{', m.end())
            if brace > 0:
                scopes.append((brace, src.close(brace), m.group(1)))
        for m in GO_GROUP.finditer(code):
            lit = src.expr(m.end())
            if lit is not None:
                self.local[rel][m.group(1)] = (m.group(2), drop_base(lit))
                self.local_at[rel].setdefault(m.group(1), []).append((src.line(m.start()), m.group(2), drop_base(lit)))
        for m in GO_ROUTE.finditer(code):
            recv, verb = m.group(1), m.group(2)
            if recv in ('http', 'client', 'httpClient', 'c', 'cli') and verb in ('Get', 'Post', 'Head'):
                continue
            args, end = src.args(paren(m))
            if len(args) < 2:
                continue
            first, verbs = args[0], None
            if verb in ('Handle', 'HandleFunc') and len(args) >= 3:
                lit = src.literal(src.skip(first[0]))
                if lit and lit[0].isupper() and '/' not in lit[0]:
                    verbs, first = [lit[0]], args[1]
            tpl = src.expr(first[0])
            if tpl is None:
                continue
            lead = re.match(r'^([A-Z]+)\s+(.*)$', tpl)
            if lead and lead.group(1) in VERBS:
                verbs, tpl = [lead.group(1)], lead.group(2)
            if verbs is None:
                if verb in ('Handle', 'HandleFunc'):
                    chain = GO_METHODS.match(code, end + 1)
                    verbs = main_verbs([v for pair in re.findall(r'"(\w+)"|Method(\w+)', chain.group(1)) for v in pair if v]) \
                        if chain else ['ANY']
                else:
                    verbs = ['ANY' if verb == 'Any' else verb.upper()]
            self.route(src, m.start(), recv, verbs, tpl, self.handler(src, *args[-1], src.line(m.start())),
                       self.scopes_at(scopes, m.start()), strict=recv not in self.local[rel])  # en un grupo, `"x/y"` es relativa
        for m in GO_CLIENT.finditer(code):
            self.client(src, m.start(), m.group(2).replace('PostForm', 'Post'), src.expr(m.end()))
        for m in GO_NEWREQ.finditer(code):
            self.client(src, m.start(), m.group(1) or m.group(2), src.expr(m.end()))
        for m in GO_RESTY.finditer(code):
            self.client(src, m.start(), m.group(1), src.expr(m.end()))
        for m in re.finditer(r'\bfunc\s*\(\s*\w+\s+\*?(query|mutation|subscription)Resolver\s*\)\s*(\w+)\s*\(', code) if not self.is_test(rel) else ():
            line = src.line(m.start())
            self.gql_endpoint(rel, line, m.group(1), m.group(2), self.owner(rel, line))
        if re.search(r'\bgraphql\s*\(\s*`|`\s*(?:query|mutation)\b', code):
            self.scan_gql_ops(src)

    def scan_rb(self, src):
        rel = src.rel
        if 'perform' in src.code and not self.is_test(rel):
            for m in RB_ENQUEUE.finditer(src.code):
                const = m.group(1)
                if const[0].islower():
                    inj = re.search(rf'''(?<![\w.]){re.escape(const)}\s*(?::|=(?![=~>]))\s*([A-Z][\w]*(?:::[A-Z]\w*)*)\b''', src.code)
                    const = inj.group(1) if inj else None
                if const:
                    self.job_calls.append((rel, src.line(m.start()), const))
        if rel.rsplit('/', 1)[-1] == 'routes.rb' or '/config/routes/' in f'/{rel}':
            self.scan_rails(src)
        elif re.search(r'\bSinatra\b|require\s+[\'"]sinatra', src.code):
            for m in RB_SINATRA.finditer(src.code):
                self.route(src, m.start(), '', [m.group(1).upper()], m.group(3), self.owner(rel, src.line(m.start())))
        elif 'Grape::API' in src.code and not self.is_test(rel):
            self.scan_grape(src)
        for m in RB_CLIENT.finditer(src.code):
            self.client(src, m.start(), m.group(2), src.expr(m.end()))

    def scan_grape(self, src):
        stack, prefix, version = [], '', ''
        codes = src.code.split('\n')
        for i, raw in enumerate(codes):
            body, ind = raw.strip(), indent_of(raw)
            if not body:
                continue
            stack = [x for x in stack if x[0] < ind or x[0] == ind and not re.match(r'end\b', body)]
            if re.match(r'end\b', body):
                continue
            m = re.match(r'''prefix\s*\(?\s*['":]/?([\w/-]+)''', body)
            if m:
                prefix = m.group(1)
                continue
            m = re.match(r'''version\s*\(?\s*['":]([\w.]+)['"]?(.*)''', body)
            if m and ('using: :path' in m.group(2) or 'using:' not in m.group(2)):
                version = m.group(1)
                continue
            m = re.match(r'''(resources?|namespace|group|segment|route_param)\s*\(?\s*['":]([\w/-]+)['"]?.*\bdo\b''', body)
            if m:
                seg = ':' + m.group(2) if m.group(1) == 'route_param' else m.group(2)
                stack.append((ind, seg))
                continue
            m = re.match(r'''(get|post|put|patch|delete|options|head)\b\s*\(?\s*(?:['":]([\w/:.-]*)['"]?)?[^\n]*\bdo\b''', body)
            if m:
                path = '/'.join(x for x in [prefix, version] + [s for _, s in stack] + [(m.group(2) or '').strip('/')] if x)
                self.route(src, src.nl[i - 1] + 1 if i else 0, '', [m.group(1).upper()], '/' + path, self.owner(src.rel, i + 1))

    def scan_rails(self, src):
        if self.is_test(src.rel):
            return
        stack, skip = [], 0
        codes, structs = src.code.split('\n'), src.struct.split('\n')
        for i, raw in enumerate(structs):
            if i < skip:
                continue
            line, text, j = raw.strip(), codes[i].strip(), i
            while text.endswith(',') and j + 1 < len(codes) and j - i < 8:
                j += 1
                line, text = line + ' ' + structs[j].strip(), text + ' ' + codes[j].strip()
            skip = j + 1
            if not line:
                continue
            if RB_END.match(line):
                if stack:
                    stack.pop()
                continue
            opens = bool(RB_OPENER.search(line))
            if text.startswith('devise_for'):
                j, full = i, text
                while full.rstrip().endswith(',') and j + 1 < len(codes):
                    j += 1
                    full += ' ' + codes[j].strip()
                self.rails_devise(src, i + 1, stack, full)
            m = RAILS_RES.match(text)
            if m:
                names = re.findall(r':(\w+)', m.group(2))
                opts = option_map(m.group(3))
                for res in names:
                    self.rails_resources(src, i + 1, stack, m.group(1) == 'resource', res, opts)
                if opens:
                    stack.append(('res', names[-1], m.group(1) == 'resource', opts))
                continue
            m = RAILS_VERB.match(text)
            if m and (m.group(1) != 'match' or m.group(3) or m.group(4)):
                self.rails_verb(src, i + 1, stack, m)
                if opens:
                    stack.append(('none',))
                continue
            m = RAILS_SCOPE.match(text)
            if m and opens:
                kind, arg = m.group(1), m.group(2) or m.group(4) or ''
                opts = option_map(m.group(5))
                if kind == 'namespace':
                    stack.append(('scope', arg, arg))
                elif kind == 'scope':
                    stack.append(('scope', unq(opts.get('path', arg)), unq(opts.get('module', ''))))
                elif kind in ('member', 'collection'):
                    stack.append((kind,))
                elif kind == 'controller':
                    stack.append(('ctrl', arg))
                else:
                    stack.append(('none',))
                continue
            if opens:
                stack.append(('none',))

    def rails_devise(self, src, line, stack, text):
        res = re.match(r'devise_for\s*\(?\s*:(\w+)', text)
        ctrls = re.search(r'\bcontrollers:\s*\{([^}]*)\}', text)
        if not res or not ctrls:
            return
        names = dict(re.findall(r'''(\w+):\s*[:'"]([\w/]+)''', ctrls.group(1)))
        renamed = re.search(r'\bpath_names:\s*\{([^}]*)\}', text)
        renamed = dict(re.findall(r'''(\w+):\s*[:'"]([\w/-]+)''', renamed.group(1))) if renamed else {}
        custom = re.search(r'''\bpath:\s*[:'"]([\w/-]*)''', text)
        path, modules, _ = self.rails_prefix(stack)
        base = path + [custom.group(1) if custom else res.group(1)]
        seg = lambda key: renamed.get(key, key)
        for kind, routes in DEVISE_ROUTES.items():
            if kind in names:
                for verb, sub, action in routes:
                    self.rails_route(src, line, verb, '/'.join(base + [seg(x) for x in sub]), modules, names[kind], action, True)

    def rails_prefix(self, stack, member=False, collection=False):
        path, modules, ctrl = [], [], None
        for idx, item in enumerate(stack):
            if item[0] == 'scope':
                if item[1].strip('/'):
                    path.append(item[1].strip('/'))
                if item[2]:
                    modules.append(item[2].strip('/'))
            elif item[0] == 'res':
                res, singular, opts = item[1], item[2], item[3]
                path.append(unq(opts.get('path', res)))
                inner = next((x[0] for x in stack[idx + 1:] if x[0] in ('member', 'collection', 'res')), None)
                if not singular and inner != 'collection' and not (inner is None and collection):
                    # `post :x, on: :collection` dentro de `resources :y do`: ruta de colección, sin id del recurso más interno
                    path.append(':id' if inner == 'member' or (inner is None and member) else f':{singularize(res)}_id')
                ctrl = unq(opts.get('controller', res if not singular or res.endswith('s') else res + 's'))
                if opts.get('module'):  # `resources :x, module: :y` (y::XController), también para las rutas anidadas
                    modules.append(unq(opts['module']).strip('/'))
            elif item[0] == 'ctrl':
                ctrl = item[1]
        return path, modules, ctrl

    def hanami_action(self, key):
        tail = '/actions/' + key.replace('.', '/') + '.rb'
        files = [f for f in self.by_file if ('/' + f).endswith(tail)]
        if len(files) != 1:
            return None
        cls = ''.join(w.capitalize() for w in key.rsplit('.', 1)[-1].split('_'))
        items = [n for _, _, n in self.by_file[files[0]] if self.g.nodes[n]['kind'] == 'class']
        return next((n for n in items if self.g.nodes[n]['name'].rsplit('.', 1)[-1] == cls), items[-1] if items else None)

    def rails_resources(self, src, line, stack, singular, res, opts):
        path, modules, _ = self.rails_prefix(stack)
        key = unq(opts.get('to', ''))
        if '.' in key or opts.get('to') and not modules and HANAMI_KEY.fullmatch(key):
            only = set(re.findall(r'\w+', opts['only'])) if 'only' in opts else None
            excluded = set(re.findall(r'\w+', opts.get('except', '')))
            for action, verb, suffix in RAILS_ACTIONS:
                if singular and action == 'index' or (only is not None and action not in only) or action in excluded:
                    continue
                fn = self.hanami_action(f'{key}.{action}')
                if fn:
                    suffix = suffix.replace('/:id', '') if singular else suffix
                    self.pending.append((src.rel, line, '', (verb,), '/' + '/'.join(path + [res]) + suffix, fn, '', ''))
            return
        only = set(re.findall(r'\w+', opts['only'])) if 'only' in opts else None
        excluded = set(re.findall(r'\w+', opts.get('except', '')))
        seg = unq(opts.get('path', res))
        ctrl = unq(opts.get('controller', res if not singular or res.endswith('s') else res + 's'))
        if opts.get('module'):
            modules = modules + [unq(opts['module']).strip('/')]
        for action, verb, suffix in RAILS_ACTIONS:
            if singular and action == 'index' or (only is not None and action not in only) or action in excluded:
                continue
            suffix = suffix.replace('/:id', '') if singular else suffix
            self.rails_route(src, line, verb, '/'.join(path + [seg]) + suffix, modules, ctrl, action, True)

    def rails_verb(self, src, line, stack, m):
        verb, lit, sym, rest = m.group(1), m.group(3), m.group(4), m.group(5) or ''
        opts = option_map(rest)
        to = RAILS_TO.search(rest)
        key = HANAMI_TO.search(rest)
        if key and not to and verb != 'root':
            path, _, _ = self.rails_prefix(stack)
            seg = (lit or sym or '').strip('/')
            for v in ([verb.upper()] if verb != 'match' else main_verbs(re.findall(r'\w+', opts.get('via', 'any')))):
                self.pending.append((src.rel, line, '', (v,), '/' + '/'.join(path + [seg]), self.hanami_action(key.group(1)) or '', '', ''))
            return
        in_res = any(x[0] == 'res' for x in stack)
        member = opts.get('on') == ':member' or (in_res and opts.get('on') != ':collection')
        path, modules, ctrl = self.rails_prefix(stack, member=member, collection=opts.get('on') == ':collection')
        if verb == 'root':
            target = to or (re.match(r'([\w/]+)#(\w+)', lit) if lit else None)
            if target:
                self.rails_route(src, line, 'GET', '/'.join(path), modules, target.group(1), target.group(2))
            return
        seg = '' if lit and '#' in lit else (lit if lit is not None else (sym or ''))
        if to:
            ctrl, action = to.group(1), to.group(2)
        elif lit and '#' in lit:
            ctrl, action = lit.split('#', 1)
        else:
            action = unq(opts.get('action', '')) or sym or (seg.strip('/').split('/')[-1] if seg else '')
            ctrl = unq(opts.get('controller', '')) or ctrl or (seg.strip('/').split('/')[0] if seg else None)
        verbs = [verb.upper()] if verb != 'match' else main_verbs(re.findall(r'\w+', opts.get('via', 'any')))
        for v in verbs:
            self.rails_route(src, line, v, '/'.join(path + [seg.strip('/')]), modules, ctrl, action)

    def rails_route(self, src, line, verb, path, modules, ctrl, action, expanded=False):
        fn = None
        if ctrl and action:
            sub = '/'.join(p for p in modules + [ctrl] if p)
            files = [f for f in self.by_file if f.endswith(f'controllers/{sub}_controller.rb')]
            if not files and modules:
                files = [f for f in self.by_file if f.endswith(f'controllers/{ctrl}_controller.rb')]
            if len(files) == 1:
                cls = ''.join(w.capitalize() for w in ctrl.split('/')[-1].split('_')) + 'Controller'
                items = [n for _, _, n in self.by_file[files[0]]]
                fn = next((n for n in items if self.g.nodes[n]['name'] == f'{cls}.{action}'), None)
                if fn is None and expanded:
                    return
                fn = fn or next((n for n in items if self.g.nodes[n]['name'] == cls), None)
        self.pending.append((src.rel, line, '', (verb,), '/' + path, fn or '', '', ''))

    def scan_php(self, src):
        code, rel = src.code, src.rel
        scopes, defaults = [], []
        if 'group' in code:
            for m in PHP_GROUP.finditer(code):
                open_pos = paren(m)
                args, end = src.args(open_pos)
                if end < 0:
                    continue
                start = max(code.rfind(';', 0, m.start()), code.rfind('{', 0, m.start()), code.rfind('}', 0, m.start())) + 1
                chain = code[start:m.start()]
                pre = re.search(r'''\bprefix\(\s*['"]([^'"]*)['"]''', chain)
                first = code[args[0][0]:args[0][1]] if args else ''
                arr = re.search(r'''['"]prefix['"]\s*=>\s*['"]([^'"]*)['"]''', first) if first.lstrip().startswith('[') else None
                lit = src.literal(src.skip(args[0][0])) if args else None
                prefix = pre.group(1) if pre else arr.group(1) if arr else lit[0] if lit else ''
                scopes.append((open_pos, end, prefix))
                ctl = re.search(r'\bcontroller\(\s*\\?([\w\\]+)::class', chain)
                if ctl:
                    defaults.append((open_pos, end, ctl.group(1).rsplit('\\', 1)[-1]))
        base = 'api' if rel.endswith('routes/api.php') else ''
        uses = {(m.group(2) or m.group(1).rsplit('\\', 1)[-1]): m.group(1) for m in PHP_USE.finditer(code)}

        def php_target(a, b, line, owner=None):
            text = code[a:b].strip()
            m = PHP_CLASS_REF.match(text)
            if owner and re.fullmatch(r'''['"]\w+['"]''', text):
                return self.resolve(text[1:-1], rel, owner=owner, hint=self.php_hint(uses, owner))
            if not m:
                return self.handler(src, a, b, line)
            alias = m.group(1).rsplit('\\', 1)[-1]
            fqn = uses.get(alias, m.group(1))
            cls, hint = fqn.rsplit('\\', 1)[-1], self.php_hint(uses, alias)
            head = m.group(1).lstrip('\\').split('\\', 1)
            if len(head) == 2 and head[0] in uses:
                # `Client\Servers\X::class` con `use App\Http\Controllers\Api\Client;`: el espacio de nombres completo da la carpeta
                full = uses[head[0]] + '\\' + head[1]
                parts = full.split('\\')
                hint = '/'.join(parts[1:] if len(parts) > 2 else parts) + '.php'
            if m.group(2):
                return self.resolve(m.group(2), rel, owner=cls, hint=hint)
            return self.resolve(f'{cls}::class', rel, hint=hint)

        def scope_of(pos):
            return '/'.join(x for x in (base, self.scopes_at(scopes, pos)) if x)

        for m in PHP_ROUTE.finditer(code):
            args, end = src.args(paren(m))
            verb = m.group(1)
            if verb == 'match':
                if len(args) < 3:
                    continue
                verbs, args = main_verbs(quoted_all(code[args[0][0]:args[0][1]])), args[1:]
            else:
                verbs = ['ANY' if verb == 'any' else verb.upper()]
            if len(args) < 2:
                continue
            ctl = next((c for s, e, c in reversed(defaults) if s <= m.start() <= e), None)
            fn = php_target(args[1][0], args[1][1], src.line(m.start()), ctl)
            self.route(src, m.start(), '', verbs, src.expr(args[0][0]), fn, scope_of(m.start()))
        for m in PHP_RESOURCE.finditer(code):
            args, end = src.args(paren(m))
            if len(args) < 2:
                continue
            lit = src.literal(src.skip(args[0][0]))
            cls = re.match(r'\s*\\?([\w\\]+)::class', code[args[1][0]:args[1][1]])
            if not lit or not cls:
                continue
            alias = cls.group(1).rsplit('\\', 1)[-1]
            cls, hint = uses.get(alias, alias).rsplit('\\', 1)[-1], self.php_hint(uses, alias)
            stop = code.find(';', end)
            tail = code[end:stop if stop > 0 else end + 200]
            only = re.search(r'->only\(\s*\[?([^\])]*)', tail)
            exc = re.search(r'->except\(\s*\[?([^\])]*)', tail)
            only = set(quoted_all(only.group(1))) if only else None
            exc = set(quoted_all(exc.group(1))) if exc else set()
            segs = lit[0].strip('/').split('.')
            path = '/'.join([f'{s}/{{{singularize(s)}}}' for s in segs[:-1]] + [segs[-1]])
            param = '{' + singularize(segs[-1].split('/')[-1]).replace('-', '_') + '}'
            for action, verb, suffix in LARAVEL_ACTIONS:
                if m.group(1) == 'apiResource' and action in ('create', 'edit'):
                    continue
                if (only is not None and action not in only) or action in exc:
                    continue
                self.route(src, m.start(), '', [verb], path + suffix.replace(':p', param),
                           self.resolve(action, rel, owner=cls, hint=hint), scope_of(m.start()))
        for m in PHP_VAR_ROUTE.finditer(code):
            if m.group(1) not in PHP_SERVER_VARS:
                continue
            args, end = src.args(paren(m))
            verb = m.group(2)
            if verb == 'map':
                if len(args) < 3:
                    continue
                verbs, args = main_verbs(quoted_all(code[args[0][0]:args[0][1]])), args[1:]
            else:
                verbs = ['ANY' if verb == 'any' else verb.upper()]
            if len(args) < 2 or not src.literal(src.skip(args[0][0])):
                continue
            self.route(src, m.start(), m.group(1), verbs, src.expr(args[0][0]),
                       php_target(args[1][0], args[1][1], src.line(m.start())), scope_of(m.start()), strict=True)
        for m in PHP_CLIENT.finditer(code):
            if m.group(1) == 'request':
                args, end = src.args(paren(m))
                if len(args) >= 2:
                    self.client(src, m.start(), first_string(code[args[0][0]:args[0][1]]) or 'ANY', src.expr(args[1][0]))
            else:
                self.client(src, m.start(), m.group(1), src.expr(m.end()))

    def php_hint(self, uses, alias):
        fqn = uses.get(alias)
        if not fqn or '\\' not in fqn:
            return None
        parts = fqn.split('\\')
        return '/'.join(parts[1:] if len(parts) > 2 else parts) + '.php'

    def scan_rs(self, src):
        code, rel = src.code, src.rel
        scopes = []
        for m in RS_SCOPE.finditer(code):
            end = -1
            depth = 0
            for i in range(m.start() - 1, max(-1, m.start() - 4000), -1):
                ch = src.struct[i]
                if ch in ')]}':
                    depth += 1
                elif ch in '([{':
                    if depth == 0:
                        end = src.close(i)
                        break
                    depth -= 1
            if end < 0:
                stop = code.find(';', m.end())
                end = stop if stop > 0 else len(code)
            scopes.append((m.end(), end, m.group(1)))
        for m in RS_ATTR.finditer(code):
            d = RS_FN.match(code, code.find(']', m.end()) + 1)
            fn = self.decl_after(src, d.start(1), d.group(1)) if d else None
            self.route(src, m.start(), '', [m.group(1).upper()], m.group(2), fn, self.scopes_at(scopes, m.start()), owner=fn)
        for m in re.finditer(r'\.mount\(\s*"([^"]*)"\s*,\s*routes!\[([^\]]*)\]', code):
            for name in re.findall(r'[\w:]+', m.group(2)):
                fn = self.rs_target(rel, name) or self.resolve(name.replace('::', '.'), rel)
                if fn:
                    self.mounts[('sym', fn)].append((rel, '', m.group(1), self.owner(rel, src.line(m.start())) or ''))
        if 'warp::' in code:
            self.scan_warp(src)
        for m in RS_ROUTE.finditer(code):
            args, end = src.args(paren(m))
            if len(args) < 2:
                continue
            body = code[args[1][0]:args[1][1]]
            for verb, target in RS_ACTIX_VERB.findall(body) or RS_AXUM_VERB.findall(body):
                self.route(src, m.start(), '', ['ANY' if verb == 'any' else verb.upper()], m.group(1),
                           self.resolve(target.replace('::', '.'), rel, src.line(m.start())), self.scopes_at(scopes, m.start()))
        for m in RS_RESOURCE.finditer(code):
            stop = code.find(';', m.end())
            chain = code[m.end():stop if stop > 0 else m.end() + 400]
            cut = chain.find('web::resource')
            chain = chain[:cut] if cut > 0 else chain
            found = RS_ACTIX_VERB.findall(chain) or [('any', t) for t in re.findall(r'^\s*\.\s*to\(\s*([\w:]+)', chain)]
            for verb, target in found:
                self.route(src, m.start(), '', ['ANY' if verb == 'any' else verb.upper()], m.group(1),
                           self.resolve(target.replace('::', '.'), rel, src.line(m.start())), self.scopes_at(scopes, m.start()))
        for m in list(RS_NEST.finditer(code)) + list(RS_MERGE.finditer(code)):
            path, target = (m.group(1), m.group(2)) if m.re is RS_NEST else ('', m.group(1))
            fn = self.rs_target(rel, target) or self.resolve(target.replace('::', '.'), rel)
            if fn and self.g.nodes[fn]['kind'] in ('function', 'method'):
                self.mounts[('sym', fn)].append((rel, '', path, self.owner(rel, src.line(m.start())) or ''))
                self.mount_links.append((rel, src.line(m.start()), ('sym', fn)))
        for m in RS_CLIENT.finditer(code):
            self.client(src, m.start(), m.group(1), src.expr(m.end()))
        if not self.is_test(rel) and '::' in code:
            self.scan_variant_queues(src)
        for m in RS_PATH_CLIENT.finditer(code) if not self.is_test(rel) else ():
            p = src.skip(m.end())
            p = src.skip(p + 1) if code.startswith('&', p) else p
            tpl = src.expr(p)
            if tpl is not None:
                self.weak_client(src, src.line(m.start()), m.group(2).upper(), tpl)

    def scan_variant_queues(self, src):
        code, rel = src.code, src.rel
        for m in VARIANT_ARM.finditer(code):
            enum, variant, body = m.group(1), m.group(2), m.group(3).strip()
            if not QUEUE_ENUM.fullmatch(enum):
                continue
            target = re.fullmatch(r'([A-Z]\w*)::([A-Z]\w*)\s*,?', body)
            if target and QUEUE_ENUM.fullmatch(target.group(1)):
                self.variant_alias[(enum, variant)] = target.group(2)
                continue
            handler = None
            for c in re.finditer(r'(?<![\w:])([a-z_]\w*)\s*\(', body):
                if c.group(1) not in ('pin', 'new', 'from', 'into', 'some', 'ok', 'err', 'spawn', 'clone', 'to_string'):
                    found = self.resolve(c.group(1), rel, src.line(m.start()))
                    if found and self.g.nodes[found]['kind'] in ('function', 'method'):
                        handler = found
                        break
            if handler:
                line = src.line(m.start())
                self.variant_uses.append((enum, variant, rel, line, 'sub', handler))
                self.variant_uses.append((enum, variant, rel, line, 'sub', ''))
        for m in VARIANT_SEND.finditer(code):
            if not QUEUE_ENUM.fullmatch(m.group(1)):
                continue
            p = src.skip(m.end())
            if code.startswith('(', p) or code.startswith('{', p):
                end = src.close(p)
                p = src.skip(end + 1) if end > 0 else p
            ufcs = re.search(rf'\b{m.group(1)}::(?:{QUEUE_VERBS})\s*\(\s*$', code[max(0, m.start() - 80):m.start()])
            if ufcs or re.match(rf'\.\s*(?:{QUEUE_VERBS})\s*\(', code[p:p + 40]):
                self.variant_uses.append((m.group(1), m.group(2), rel, src.line(m.start()), 'pub', ''))

    def finish_variants(self):
        subs = {v for e, v, rel, line, role, sym in self.variant_uses if role == 'sub'}
        for enum, variant, rel, line, role, sym in self.variant_uses:
            name = self.variant_alias.get((enum, variant), variant)
            if name in subs:
                self.topic_uses.append((name, rel, line, role, sym, 'weak'))
        for rel, line, value in self.queue_refs:
            if value in subs:
                self.topic_uses.append((value, rel, line, 'sub', '', 'weak'))

    def scan_vapor(self, src):
        code, rel = src.code, src.rel
        if not re.search(r'^\s*import\s+Vapor\b', code, re.M) or self.is_test(rel):
            return
        for m in re.finditer(r'\blet\s+(\w+)\s*=\s*(\w+)\.grouped\(([^)]*)\)', code):
            self.local[rel][m.group(1)] = (m.group(2), '/'.join(quoted_all(m.group(3))))
        for m in re.finditer(r'\b(\w+)\s*\.\s*(get|post|put|patch|delete)\s*\(', code):
            args, end = src.args(paren(m))
            parts, fn = [], None
            for a, b in args:
                text = code[a:b].strip()
                use = re.match(r'use\s*:\s*([\w.]+)', text)
                if use:
                    fn = self.resolve(use.group(1).split('.')[-1], rel, src.line(m.start()))
                elif re.fullmatch(r'"[^"]*"', text):
                    parts.append(text[1:-1])
                elif text:
                    parts = None
                    break
            if parts is None or end < 0:
                continue
            if fn is None and code[src.skip(end + 1):src.skip(end + 1) + 1] == '{':
                fn = self.owner(rel, src.line(m.start()))
            if fn and (parts or m.group(1) in self.local[rel]):
                self.route(src, m.start(), m.group(1), [m.group(2).upper()], '/' + '/'.join(parts), fn)

    def scan_swift_clients(self, src):
        code = src.code
        if self.is_test(src.rel) or 'URL' not in code:
            return
        for m in re.finditer(r'\b(?:URLRequest\(\s*url\s*:\s*|(?:data|dataTask|upload|download)\(\s*(?:from|with)\s*:\s*)URL\(\s*string\s*:\s*', code):
            fn = self.function_at(src, m.start())
            meta = self.g.nodes.get(fn) or {}
            body = code[m.start():src.nl[meta['end'] - 1] if meta.get('end') and meta['end'] <= len(src.nl) else m.start() + 800]
            verb = re.search(r'\.httpMethod\s*=\s*"(\w+)"', body)
            self.client(src, m.start(), verb.group(1) if verb else 'GET', src.expr(m.end()))
        for m in re.finditer(r'\b(?:AF|Alamofire|session|Session)\s*\.\s*request\s*\(', code):
            args, end = src.args(paren(m))
            if args:
                verb = re.search(r'\bmethod\s*:\s*\.(get|post|put|patch|delete)\b', code[m.end():end])
                self.client(src, m.start(), verb.group(1) if verb else 'GET', src.expr(args[0][0]))

    def scan_play_routes(self, rel):
        text = self.text(rel) or ''
        mid = None
        for i, line in enumerate(text.split('\n')):
            m = re.match(r'^\s*(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS|\*)\s+(/\S*)\s+([\w.]+)\.(\w+)', line)
            if not m:
                continue
            cls = m.group(3).rsplit('.', 1)[-1]
            fn = self.pick(rel, self.full.get(f'{cls}.{m.group(4)}', []))
            mid = mid or self.config_module(rel, text, 'routes')
            verb = 'ANY' if m.group(1) == '*' else m.group(1)
            self.endpoint(rel, i + 1, verb, norm_path(m.group(2).replace('$', ':')), fn)

    def rs_target(self, rel, path):
        parts = path.split('::')
        if len(parts) < 2:
            return None
        stem = rel[:-3]
        base = stem.rsplit('/', 1)[0] if stem.endswith(('/mod', '/lib', '/main')) or '/' not in stem else stem
        mods = parts[:-1]
        if mods[0] == 'crate':
            base, mods = rel.split('/src/')[0] + '/src' if '/src/' in rel else 'src', mods[1:]
        while mods and mods[0] in ('super', 'self'):
            if mods[0] == 'super':
                base = base.rsplit('/', 1)[0] if '/' in base else ''
            mods = mods[1:]
        sub = '/'.join([base] + mods if base else mods)
        for cand in (f'{sub}.rs', f'{sub}/mod.rs'):
            if cand in self.fileset:
                return self.in_file(cand, parts[-1])
        return None

    def scan_warp(self, src):
        code = src.code
        for m in re.finditer(r'\bwarp::path!\(|\bwarp::path\(\s*"', code):
            start = max(code.rfind(';', 0, m.start()), code.rfind('{', 0, m.start())) + 1
            if any(p.start() < m.start() for p in re.finditer(r'\bwarp::path(?:!\(|\()', code[start:m.start()])):
                continue
            end = self.statement_end(src, m.start())
            stmt = code[start:end]
            segs = []
            for p in re.finditer(r'\bwarp::path!\(([^)]*)\)|\bwarp::path\(\s*"([^"]*)"\s*\)|\bwarp::path::param(?:::<[^>]*>)?\(\)', stmt):
                if p.group(1) is not None:
                    segs += [x.strip().strip('"') if x.strip().startswith('"') else ':param' for x in p.group(1).split('/') if x.strip()]
                else:
                    segs.append(p.group(2) if p.group(2) is not None else ':param')
            verb = re.search(r'\bwarp::(get|post|put|delete|patch|head)\(\)', stmt)
            handler = re.search(r'\.(?:and_then|map|then)\(\s*([\w:]+)\s*\)', stmt)
            fn = self.resolve(handler.group(1).replace('::', '.'), src.rel, src.line(m.start())) if handler else None
            if segs and fn:
                self.route(src, m.start(), '', [verb.group(1).upper() if verb else 'ANY'], '/' + '/'.join(segs), fn)

    def scan_ex(self, src):
        if 'Phoenix.Router' in src.code or re.search(r'^\s*use\s+[\w.]+\s*,\s*:router\b', src.code, re.M):
            self.scan_phoenix(src)
        elif re.search(r'^\s*use\s+Plug\.Router\b', src.code, re.M) and not self.is_test(src.rel):
            mods = [(m.start(), m.group(1)) for m in EX_DEFMODULE.finditer(src.code)]
            for m in re.finditer(r'^[ \t]*(get|post|put|patch|delete|options|match|forward)\s+"([^"]*)"', src.code, re.M):
                mod = next((n for p, n in reversed(mods) if p < m.start()), None)
                cls = self.pick(src.rel, [n for n in self.full.get(mod, []) + self.short.get((mod or '').rsplit('.', 1)[-1], [])
                                          if self.g.nodes[n]['kind'] == 'class' and self.g.nodes[n]['file'] == src.rel])
                verb = {'match': 'ANY', 'forward': 'ANY'}.get(m.group(1), m.group(1).upper())
                self.route(src, m.start(), '', [verb], m.group(2), cls or self.module(src.rel))
        for m in EX_CLIENT.finditer(src.code):
            self.client(src, m.start(), m.group(1), src.expr(m.end()))

    def scan_phoenix(self, src):
        if self.is_test(src.rel):
            return
        stack = []
        rows = src.code.split('\n')
        skip = -1
        for i, raw in enumerate(rows):
            if i <= skip:
                continue
            line = raw.strip()
            if not line:
                continue
            j = i
            while line.endswith(',') and j + 1 < len(rows) and j - i < 6:
                j += 1
                line = line + ' ' + rows[j].strip()
            skip = j
            if RB_END.match(line):
                if stack:
                    stack.pop()
                continue
            opens = bool(re.search(r'\bdo\s*$', line)) or line.startswith('fn') and line.endswith('->')
            prefix = '/'.join(x[1].strip('/') for x in stack if x[1].strip('/'))
            alias = '.'.join(x[2] for x in stack if len(x) > 2 and x[2])
            m = EX_SCOPE.match(line)
            if m:
                if opens:
                    stack.append(('scope', m.group(1), m.group(2) or ''))
                continue
            m = EX_RES.match(line)
            if m:
                ctrl, rest, seg = m.group(2), m.group(3), m.group(1).strip('/')
                only = re.search(r'only:\s*\[([^\]]*)\]', rest)
                exc = re.search(r'except:\s*\[([^\]]*)\]', rest)
                only = set(re.findall(r':(\w+)', only.group(1))) if only else None
                exc = set(re.findall(r':(\w+)', exc.group(1))) if exc else set()
                for action, verb, suffix in RAILS_ACTIONS:
                    name = 'delete' if action == 'destroy' else action
                    if (only is not None and name not in only) or name in exc:
                        continue
                    self.phoenix_route(src, i + 1, verb, f'{prefix}/{seg}{suffix}', ctrl, name, True)
                if opens:
                    stack.append(('res', f'{seg}/:{singularize(seg.split("/")[-1])}_id'))
                continue
            m = EX_VERB.match(line)
            if m:
                verb = {'live': 'GET', 'forward': 'ANY'}.get(m.group(1), m.group(1).upper())
                self.phoenix_route(src, i + 1, verb, f'{prefix}/{m.group(2)}', m.group(3), m.group(4), alias=alias)
                if opens:
                    stack.append(('none', ''))
                continue
            if opens:
                stack.append(('none', ''))

    def phoenix_route(self, src, line, verb, path, ctrl, action, expanded=False, alias=''):
        short = ctrl.rsplit('.', 1)[-1]
        scoped = [n for n in self.full.get(f'{alias}.{ctrl}.{action}', [])] if alias and action else []
        fn = scoped[0] if len(scoped) == 1 else self.pick(src.rel, [n for n in self.short.get(action, [])
                                                                    if self.g.nodes[n]['name'].endswith(f'{short}.{action}')]) \
            if action else None
        if fn is None and expanded and self.pick(src.rel, [n for n in self.short.get(short, []) if self.g.nodes[n]['kind'] == 'class']):
            return
        fn = fn or self.pick(src.rel, [n for n in self.full.get(ctrl, []) + self.short.get(short, [])
                                       if self.g.nodes[n]['kind'] == 'class'])
        self.pending.append((src.rel, line, '', (verb,), path, fn or '', '', ''))

    def load_protos(self):
        groups, pkgs = defaultdict(list), {}
        for nid, m in sorted(self.g.nodes.items()):
            rel = m.get('file') or ''
            if m.get('kind') != 'method' or not rel.endswith('.proto') or '.' not in m['name'] or self.is_test(rel):
                continue
            if rel not in pkgs:
                found = PROTO_PACKAGE.search(self.text(rel) or '')
                pkgs[rel] = found.group(1) if found else ''
            svc, rpc = m['name'].rsplit('.', 1)
            groups[(pkgs[rel], svc, rpc)].append((rel.count('/'), len(rel), rel, m.get('line') or 1, nid))
        for (pkg, svc, rpc), items in sorted(groups.items()):
            _, _, rel, line, first = min(items)
            name = f'RPC {pkg + "." if pkg else ""}{svc}/{rpc}'
            eid = self.g.node(f'e:{rel}:{name}', kind='endpoint', name=name, file=rel, line=line, lang='proto',
                              route=name, hash=digest(name))
            mid = self.module(rel)
            if mid:
                self.g.edge(mid, eid, 'contains')
            self.services.setdefault(svc, {}).setdefault(rpc_key(rpc), eid)
            for *_, copy in items:
                if copy != first:
                    self.g.edge(copy, eid, 'rpc')
            for hline, verb, path in self.proto_http(rel, line):
                hid = self.endpoint(rel, hline, verb, norm_path(path), None)
                self.proto_routes.append((hid, eid))

    def proto_http(self, rel, line):
        text = self.text(rel) or ''
        if 'google.api.http' not in text:
            return []
        lines = text.split('\n')
        start = sum(len(x) + 1 for x in lines[:line - 1])
        head = re.match(r'\s*rpc\s+\w+\s*\([^)]*\)\s*returns\s*\([^)]*\)\s*', text[start:start + 600])
        if not head or not text.startswith('{', start + head.end()):
            return []
        body_start = start + head.end()
        depth, end = 0, body_start
        for i in range(body_start, min(len(text), body_start + 4000)):
            depth += {'{': 1, '}': -1}.get(text[i], 0)
            if depth == 0:
                end = i
                break
        out = []
        for m in re.finditer(r'\b(get|post|put|patch|delete)\s*:\s*"([^"]+)"', text[body_start:end]):
            out.append((text.count('\n', 0, body_start + m.start()) + 1, m.group(1).upper(), m.group(2)))
        return out

    def scan_grpc(self, src):
        if not self.services:
            return
        code, rel, lang = src.code, src.rel, src.lang
        servers = []
        if lang == 'go':
            servers += [(m.group(1), m.group(2), 'dir') for m in GRPC_GO_EMBED.finditer(code)]
            for m in GRPC_GO_GW.finditer(code):
                self.grpc_wiring.append((rel, src.line(m.start()), m.group(1)))
            for m in GRPC_GO_REG.finditer(code):
                impl = m.group(2).strip()
                if m.group(1) in self.services:
                    self.grpc_wiring.append((rel, src.line(m.start()), m.group(1)))
                t = re.match(r'&?\s*(\w+)\s*\{|new\((\w+)\)', impl) or re.match(r'(?:\w+\.)?()()()(New\w*)\s*\(', impl)
                if not t and re.fullmatch(r'&?\s*\w+', impl):
                    impl = impl.lstrip('&').strip()
                    t = re.search(rf'\b{impl}\s*:?=\s*(?:&\s*(\w+)\s*\{{|new\((\w+)\)|(\w+)\s*\{{|(?:\w+\.)?(New\w*)\()', code)
                if not t:
                    continue
                cls = next(x for x in t.groups() if x)
                folder = None
                if t.lastindex == 4:
                    cls, folder = self.go_constructed(rel, cls)
                if cls:
                    servers.append((cls, m.group(1), f'dir:{folder}' if folder is not None else 'dir'))
                    self.grpc_regs.append((rel, src.line(m.start()), cls, folder))
        elif lang == 'py':
            impls = {m.group(1): m.group(2) for m in GRPC_PY_SERVER.finditer(code)}
            for m in GRPC_PY_SUB.finditer(code):
                base = m.group(2).rsplit('.', 1)[-1]
                if base in impls and m.group(1) not in impls:
                    impls[m.group(1)] = impls[base]
            servers += [(c, s, 'file') for c, s in sorted(impls.items())]
        elif lang in ('java', 'kt'):
            servers += [(m.group(1), m.group(2), 'file') for m in GRPC_JAVA_SERVER.finditer(code)]
            servers += [(m.group(1), m.group(2), 'file') for m in GRPC_IMPL_BASE.finditer(code) if m.group(2) in self.services]
            if '@GrpcService' in code:
                for m in GRPC_IMPLEMENTS.finditer(code):
                    names = {t.rsplit('.', 1)[-1] for t in re.findall(r'[\w.]+', m.group(2))}
                    servers += [(m.group(1), svc, 'file') for svc in sorted(names) if svc in self.services]
            for m in GRPC_INJECT.finditer(code):
                svc = grpc_service(m.group(2) or m.group(3), self.services)
                if svc:
                    self.grpc_clients.append((rel, src.line(m.start()), svc))
        elif lang == 'cs':
            servers += [(m.group(1), m.group(2), 'file') for m in GRPC_CS_SERVER.finditer(code)]
            for m in GRPC_CS_MAP.finditer(code):
                self.grpc_regs.append((rel, src.line(m.start()), m.group(1), None))
        elif lang == 'rs' and 'tonic' in code:
            servers += [(m.group(2), m.group(1), 'file') for m in GRPC_RS_SERVER.finditer(code)]
        elif lang == 'js' and not self.is_test(rel):
            for m in GRPC_JS_SERVER.finditer(code):
                svc = m.group(1).rsplit('.', 1)[-1]
                p = src.skip(m.end())
                if svc not in self.services or not code.startswith('{', p):
                    continue
                args, _ = src.args(p)
                for a, b in args:
                    kv = re.match(r'''\s*['"]?(\w+)['"]?\s*(?::\s*(.+))?$''', code[a:b], re.S)
                    if not kv:
                        continue
                    eid = self.services[svc].get(rpc_key(kv.group(1)))
                    fn = self.resolve((kv.group(2) or kv.group(1)).strip(), rel)
                    if eid and fn:
                        self.g.edge(eid, fn, 'handles')
        if not self.is_test(rel):
            for cls, svc, scope in servers:
                self.grpc_impls.setdefault((cls, rel), svc)
                for key, eid in sorted(self.services.get(svc, {}).items()):
                    for n in self.class_methods(cls, scope, rel):
                        if rpc_key(self.g.nodes[n]['name'].rsplit('.', 1)[-1]) == key:
                            self.g.edge(eid, n, 'handles')
        binds, chains = defaultdict(set), []
        if lang == 'go':
            chains = [(m, m.group(1)) for m in GRPC_GO_CHAIN.finditer(code)]
            binds_rx = [(GRPC_GO_BIND, 1, 2), (GRPC_GO_DECL, 1, 2)]
        elif lang == 'py':
            chains = [(m, m.group(1)) for m in GRPC_PY_CHAIN.finditer(code)]
            binds_rx = [(GRPC_PY_BIND, 1, 2)]
        elif lang in ('java', 'kt'):
            binds_rx = [(GRPC_JAVA_BIND, 1, 2), (GRPC_JAVA_DECL, 2, 1)]
            for m in GRPC_INJECT.finditer(code):
                svc = grpc_service(m.group(2) or m.group(3), self.services)
                var = m.group(4) or m.group(1)
                if svc and var:
                    binds[var].add(svc)
                    for f in re.finditer(rf'\bthis\.(\w+)\s*=\s*{re.escape(var)}\s*;', code):
                        binds[f.group(1)].add(svc)
        elif lang == 'cs':
            binds_rx = [(GRPC_CS_BIND, 1, 2), (GRPC_CS_DECL, 2, 1)]
            for m in GRPC_CS_ALIAS.finditer(code):
                if m.group(2) in self.services:
                    binds_rx.append((re.compile(rf'\b{m.group(1)}\s+(\w+)\s*[,;)=]'), 1, None, m.group(2)))
        elif lang == 'js':
            binds_rx = [(GRPC_JS_BIND, 1, 2)]
        elif lang == 'rs':
            binds_rx = [(GRPC_RS_BIND, 1, 2)]
        else:
            binds_rx = []
        for rx, var, svc, *fixed in binds_rx:
            for m in rx.finditer(code):
                name = fixed[0] if fixed else m.group(svc)
                if name not in self.services and lang == 'go' and rx is GRPC_GO_BIND:
                    name = self.go_client_service(rel, f'New{name}Client') or name
                if name in self.services:
                    binds[m.group(var)].add(name)
        for m, svc in chains:
            if svc not in self.services:
                continue
            end = src.close(paren(m))
            call = GRPC_CALL.match(code, end + 1) if end > 0 else None
            if call:
                self.rpc_call(src, m.start(), {svc}, call.group(1))
        for var, svcs in sorted(binds.items()):
            for m in re.finditer(rf'\b{re.escape(var)}\s*(?:\(\s*\))?\s*\.\s*(\w+)\s*\(', code):
                self.rpc_call(src, m.start(), svcs, m.group(1))

    def go_constructed(self, rel, ctor):
        fn = self.pick(rel, [n for n in self.short.get(ctor, []) if self.g.nodes[n]['kind'] == 'function'])
        if not fn:
            return None, None
        frel = self.g.nodes[fn]['file']
        text = self.text(frel) or ''
        m = re.search(rf'\bfunc\s+{re.escape(ctor)}\s*\([^)]*\)\s*\(?\s*\*?(?:(\w+)\.)?(\w+)', text)
        if m and m.group(1):  # devuelve una interfaz de otro paquete: el tipo concreto es el `return &T{...}` del cuerpo
            body = re.search(r'\breturn\s+&?(\w+)\s*\{', text[m.end():m.end() + 20000])
            return (body.group(1), frel.rsplit('/', 1)[0] if '/' in frel else '') if body else (None, None)
        return (m.group(2), frel.rsplit('/', 1)[0] if '/' in frel else '') if m else (None, None)

    def go_client_service(self, rel, ctor):
        fn = self.pick(rel, [n for n in self.short.get(ctor, []) if self.g.nodes[n]['kind'] == 'function'])
        if not fn:
            return None
        m = re.search(rf'\bfunc\s+{re.escape(ctor)}\s*\([^)]*\)\s*([^{{]*)', self.text(self.g.nodes[fn]['file']) or '')
        found = [x for x in re.findall(r'(\w+)Client\b', m.group(1) if m else '') if x in self.services]
        return found[0] if len(set(found)) == 1 else None

    def class_methods(self, cls, scope, rel):
        if scope.startswith('dir'):
            folder = scope[4:] if scope.startswith('dir:') else rel.rsplit('/', 1)[0] if '/' in rel else ''
            return sorted(n for n in self.owners.get(cls, [])
                          if (self.g.nodes[n]['file'].rsplit('/', 1)[0] if '/' in self.g.nodes[n]['file'] else '') == folder)
        return sorted(n for _, _, n in self.by_file.get(rel, []) if self.g.nodes[n]['name'].rsplit('.', 1)[0] == cls
                      and self.g.nodes[n]['kind'] == 'method')

    def rpc_call(self, src, pos, svcs, method):
        key = rpc_key(method)
        alt = key[:-5] if key.endswith('async') and len(key) > 5 else None
        found = sorted({self.services[s].get(key) or (self.services[s].get(alt) if alt else None) for s in svcs} - {None})
        if len(found) == 1:
            self.rpc_pending.append((src.rel, src.line(pos), found[0]))

    def load_env_files(self):
        dirs = {''}
        for rel in self.files:
            parts = rel.split('/')[:-1]
            dirs.update('/'.join(parts[:i]) for i in range(1, len(parts) + 1))
        names, cands, templates = set(ENV_FILES), set(), set()
        for d in dirs:
            try:
                found = os.listdir(self.root / d) if d else os.listdir(self.root)
            except OSError:
                continue
            cands |= {f'{d}/{n}' if d else n for n in found if n in names or ENV_LIKE.match(n)}
            templates |= {f'{d}/{n}' if d else n for n in found if TEMPLATE_FILE.match(n)}
        cands |= templates
        if (self.root / '.git').exists():
            self.is_tracked('')
            cands |= {rel for rel in self.tracked or () if ENV_LIKE.match(rel.rsplit('/', 1)[-1])}
            templates = {rel for rel in self.tracked or () if TEMPLATE_FILE.match(rel.rsplit('/', 1)[-1])}
            cands |= templates
        public = set(ENV_FILES) - set(PRIVATE_ENV)
        for rel in sorted(c for c in cands if not self.is_test(c)):
            path = self.root / rel
            try:
                if rel.rsplit('/', 1)[-1] not in public and (not self.tracked or rel not in self.tracked) and rel not in templates:
                    continue
                if not path.is_file() or path.stat().st_size > 256 * 1024:
                    continue
                text = path.read_text(encoding='utf-8', errors='replace')
            except OSError:
                continue
            self.env_file(rel, text)

    def is_tracked(self, rel):
        if self.tracked is False:
            from .analyze import git_visible
            self.tracked = git_visible(self.root)
        return self.tracked is None or rel in self.tracked

    def compose_ref(self, rel, line, kind, value):
        if kind != 'env_file':
            self.svc_refs.append((rel, line, value.split(':')[0], 'depends'))
            return
        target = os.path.normpath(os.path.join(os.path.dirname(rel), value)).replace(os.sep, '/')
        if target.startswith('..') or not (self.root / target).is_file():
            return
        if target not in self.fileset and not self.is_tracked(target):
            return
        try:
            text = (self.root / target).read_text(encoding='utf-8', errors='replace')[:256 * 1024]
        except OSError:
            return
        if self.env_file(target, text) or self.module(target):
            self.env_file_refs.append((rel, line, target))

    def env_file(self, rel, text):
        if rel in self.env_loaded:
            return self.module(rel)
        self.env_loaded.add(rel)
        documented = bool(TEMPLATE_NAME.search(rel.rsplit('/', 1)[-1]))  # plantillas: las líneas comentadas documentan variables
        found = [(i + 1, m.group(1)) for i, line in enumerate(text.split('\n'))
                 for m in [re.match(r'^\s*(?:export\s+)?([A-Za-z_]\w*)\s*=', line) or documented and COMMENTED_DEF.match(line)] if m]
        if TEMPLATE_FILE.match(rel.rsplit('/', 1)[-1]) and len(found) < 3:
            return None
        if not found:
            return None
        mid = self.module(rel) or self.g.node(f'm:{rel}', kind='module', name=rel.rsplit('/', 1)[-1], file=rel, line=1, lang='env',
                                              end=text.count('\n') + 1, hash=digest(rel + ' '.join(n for _, n in found)))
        self.env_defs += [(rel, line, n, mid) for line, n in found]
        self.scan_services(rel, text.split('\n'))
        return mid

    def scan_json(self, rel):
        try:
            if (self.root / rel).stat().st_size > 4 * 1024 * 1024:
                return
        except OSError:
            return
        text = self.text(rel)
        if text and '"paths"' in text[:200000] and re.search(r'"(?:openapi|swagger)"\s*:', text[:4000]):
            self.openapi += [(rel,) + op for op in openapi_json(text)]
        if text and len(text) < 512 * 1024:
            self.scan_json_env(rel, text)

    def scan_yaml(self, rel):
        mid = self.module(rel)
        text = self.text(rel) if mid else None
        if not text:
            return
        lines = text.split('\n')
        self.scan_env_blocks(rel, lines, mid)
        self.scan_compose_builds(rel, lines)
        if '<%' in text and 'ENV' in text and not self.is_test(rel):
            # plantillas ERB en YAML (`url: <%= ENV.fetch('REDIS_URL', 'redis://..') %>`): lecturas de entorno del fichero
            for m in ERB_ENV.finditer(text):
                self.env_uses.append((rel, text.count('\n', 0, m.start()) + 1, m.group(1) or m.group(2)))
        if not self.is_test(rel) and re.search(r'^(?:openapi|swagger)\s*:', text, re.M) and re.search(r'^paths\s*:', text, re.M):
            self.openapi += [(rel,) + op for op in openapi_yaml(text)]
            self.openapi_refs(rel, text)
        if not self.is_test(rel) and re.search(r'^\s*-?\s*(?:queue|topic|channel|stream|subject):', text, re.M):
            for m in re.finditer(r'''^\s*-?\s*(?:queue|topic|channel|stream|subject):\s*['"]?([A-Za-z_][\w.\-:]*)['"]?\s*$''', text, re.M):
                self.queue_refs.append((rel, text.count('\n', 0, m.start()) + 1, m.group(1)))
        if 'class' in text and not self.is_test(rel):
            for m in re.finditer(r'''^\s*(?:class|job_class|worker|class_name):\s*['"]?((?:::)?[A-Z]\w*(?:::[A-Z]\w*)*)['"]?\s*$''', text, re.M):
                self.job_refs.append((rel, text.count('\n', 0, m.start()) + 1, m.group(1)))
        base = rel.rsplit('/', 1)[-1]
        if not base.startswith(('docker-compose', 'compose.')) and (re.search(r'^services:\s*$', text, re.M) or (
                re.search(r'^\s+(?:image|build):', text, re.M) and not re.search(r'^(?:apiVersion|kind)\s*:', text, re.M))):
            for name, line, end in compose_services(text):
                self.compose_files.add(rel)
                nid = f'c:{rel}:{name}'
                if nid not in self.g.nodes:
                    self.declare(nid, 'class', name, rel, line)
                    self.g.nodes[nid].update(end=end, lang=self.g.nodes[mid].get('lang'))
                    self.add_item(rel, line, end, nid)
            if rel not in self.compose_files:
                self.scan_platform(rel, lines)
        self.scan_services(rel, lines)
        if '$' in text and not self.is_test(rel):
            keys = []
            for i, line in enumerate(lines):
                k = re.match(r'^(\s*)([\w.\-]+)\s*(?:[:=]\s*(.*)|\{\s*)$', line) if not line.lstrip().startswith('#') else None
                if k:
                    ind = len(k.group(1))
                    keys = [(n, key) for n, key in keys if n < ind] + [(ind, k.group(2))]
                for r in YAML_ENV_REF.finditer((k.group(3) or '') if k else line):
                    name = r.group(1) or r.group(2)
                    self.env_uses.append((rel, i + 1, name))
                    if k:
                        self.config_keys.setdefault('.'.join(key for _, key in keys), name)
        for i, line in enumerate(lines):
            ref = re.match(r'^\s*(?:configMapKeyRef|secretKeyRef):\s*$', line)
            if ref:
                near = '\n'.join(lines[i + 1:i + 3])
                key, cm = re.search(r'\bkey:\s*["\']?([\w.-]+)', near), re.search(r'\bname:\s*["\']?([\w.-]+)', near)
                owner = next((j for j in range(i, max(-1, i - 4), -1) if re.match(r'^\s*-\s*name:', lines[j])), i)
                if key and cm:
                    self.cm_refs.append((rel, owner + 1, cm.group(1), key.group(1)))
        if re.search(r'^kind:\s*(?:ConfigMap|Secret)\s*$', text, re.M):
            kind, block, cm = None, None, None
            for i, line in enumerate(lines):
                if line.startswith('---'):
                    kind, block, cm = None, None, None
                    continue
                km = re.match(r'^kind:\s*(\w+)', line)
                if km:
                    kind = km.group(1)
                nm = re.match(r'^\s{1,4}name:\s*["\']?([\w.-]+)', line) if cm is None and block is None else None
                if nm:
                    cm = nm.group(1)
                if re.match(r'^(?:data|stringData):\s*$', line):
                    block = -1
                    continue
                if block is not None and line.strip() and not line.startswith((' ', '\t')):
                    block = None
                if block is None or kind not in ('ConfigMap', 'Secret') or not line.strip():
                    continue
                ind = len(line) - len(line.lstrip())
                block = ind if block == -1 else block
                dm = re.match(r'^[ \t]+["\']?([A-Za-z_][\w.-]*)["\']?\s*:\s*(.*)$', line) if ind == block else None
                if dm:
                    self.env_defs.append((rel, i + 1, dm.group(1), mid))
                    if cm:
                        self.cm_values[(cm, dm.group(1))] = dm.group(2).strip().strip('"\'')
        if not re.search(r'^\s*(?:-\s+)?(?:env|environment):', text, re.M):
            return
        for i, line in enumerate(lines):
            m = re.match(r'^(\s*)(-\s+)?(env|environment):\s*(?:#.*)?$', line)
            if not m:
                continue
            ind, child = len(m.group(1)) + len(m.group(2) or ''), None
            for j in range(i + 1, len(lines)):
                raw = lines[j]
                body = raw.strip()
                if not body or body.startswith('#'):
                    continue
                cur = len(raw) - len(raw.lstrip())
                if cur < ind or (cur == ind and not body.startswith('-')):
                    break
                child = cur if child is None else child
                if cur != child:
                    continue
                k = re.match(r'''^-\s*name:\s*["']?([A-Za-z_][\w.-]*)''', body) or \
                    re.match(r'''^-\s*["']?([A-Za-z_]\w*)(?:=|["']?\s*$)''', body) or \
                    re.match(r'''^["']?([A-Z_][A-Za-z0-9_]*|[A-Za-z][A-Za-z0-9]*__[\w]+)["']?\s*:''', body)  # también `APP_db__host`
                if k:
                    self.env_defs.append((rel, j + 1, k.group(1), mid))

    def scan_platform(self, rel, lines):
        mid, items = self.module(rel), {}
        for key in PLATFORM_KEYS:
            for body, line, end in yaml_blocks(lines, key, items=True):
                ind = indent_of(lines[line - 1]) + 2
                name = None
                for i in range(line - 1, end):
                    m = re.match(r'''^(\s*)(?:-\s+)?name:\s*["']?([\w.\-]+)''', lines[i])
                    if m and (i == line - 1 or len(m.group(1)) == ind):
                        name = m.group(2)
                        break
                if name and name not in items:
                    items[name] = (self.add_resource(rel, name, line, end), line, end)
        if not items or self.is_test(rel):
            return
        for name, (nid, line, end) in sorted(items.items(), key=lambda x: x[1][1]):
            for i in range(line - 1, end):
                m = re.match(r'''^(\s*)-\s*key:\s*["']?([A-Za-z_]\w*)''', lines[i])
                if not m:
                    continue
                stop = next((j for j in range(i + 1, end) if lines[j].strip() and indent_of(lines[j]) <= len(m.group(1))), end)
                block = '\n'.join(lines[i:stop])
                if mid:
                    self.env_defs.append((rel, i + 1, m.group(2), mid))
                ref = re.search(r'''\bfrom(?:Service|Database|Group)\s*:\s*\n(?:[^\n]*\n){0,3}?\s*name:\s*["']?([\w.\-]+)|'''
                                r'''\bfromGroup\s*:\s*["']?([\w.\-]+)''', block)
                target = items.get(ref.group(1) or ref.group(2)) if ref else None
                if target:
                    var = self.add_resource(rel, f'{name}.{m.group(2)}', i + 1, stop)
                    self.g.edge(var, target[0], 'depends')

    def config_module(self, rel, text, lang):
        return self.module(rel) or self.g.node(f'm:{rel}', kind='module', name=rel.rsplit('/', 1)[-1], file=rel, line=1, lang=lang,
                                               end=text.count('\n') + 1, hash=digest(rel))

    def scan_toml(self, rel):
        text = self.text(rel)
        if not text or not re.search(r'^\[(?:[\w.]+\.)?env(?:ironment)?\]', text, re.M):
            return
        mid, section = None, None
        for i, line in enumerate(text.split('\n')):
            head = re.match(r'^\s*\[([^\]]+)\]', line)
            if head:
                section = head.group(1).strip()
                continue
            m = re.match(r'''^\s*["']?([A-Za-z_]\w*)["']?\s*=''', line)
            if m and section and re.fullmatch(r'(?:[\w.]+\.)?env(?:ironment)?', section):
                mid = mid or self.config_module(rel, text, 'toml')
                self.env_defs.append((rel, i + 1, m.group(1), mid))

    def scan_procfile(self, rel):
        text = self.text(rel)
        if not text:
            return
        mid = None
        for i, line in enumerate(text.split('\n')):
            m = re.match(r'^\s*([\w-]+)\s*:\s*(.+)$', line)
            if not m:
                continue
            for tok in re.findall(r'[\w./-]+(?::[\w]+)?', m.group(2)):
                path = tok.split(':', 1)[0]
                target = path if path in self.fileset else self.py_module(rel, path) if re.fullmatch(r'\w+(?:\.\w+)+', path) else None
                if target and self.module(target) and target != rel:
                    mid = mid or self.config_module(rel, text, 'procfile')
                    self.g.edge(mid, self.module(target), 'depends')

    def scan_dockerfile(self, rel):
        mid = self.module(rel)
        text = self.text(rel) if mid else None
        lines = (text or '').split('\n')
        cont = False
        for i, line in enumerate(lines):
            m = re.match(r'^\s*(ENV|ARG)\s+(.+)$', line, re.I)
            body = m.group(2) if m else line if cont else None
            cont = bool(body is not None and line.rstrip().endswith('\\'))
            if body is not None:
                body = body.rstrip().rstrip('\\')
                for n in re.findall(r'([A-Za-z_]\w*)=', body) or (re.findall(r'^\s*([A-Za-z_]\w*)', body) if m else []):
                    self.env_defs.append((rel, i + 1, n, mid))

    def scan_services(self, rel, lines):
        if self.is_test(rel):
            return
        base = rel.rsplit('/', 1)[-1]
        compose = base.startswith(('docker-compose', 'compose.')) or rel in self.compose_files
        spring = re.match(r'(?:application|bootstrap)(?:-[\w-]+)?\.(?:properties|ya?ml)$', base) is not None
        keys, dep, uri, dep_kind, ports, aliases = [], None, None, None, None, None
        for i, line in enumerate(lines):
            body = line.strip()
            if not body or body.startswith('#'):
                continue
            ind = len(line) - len(line.lstrip())
            if dep is not None and ind <= dep:
                dep = None
            if ports is not None and (ind < ports or ind == ports and not body.startswith('-')):
                ports = None
            if aliases is not None and (ind < aliases or ind == aliases and not body.startswith('-')):
                aliases = None
            k = re.match(r'^(?:%[\w,\-]+\.)?([\w.\-\[\]"]+)\s*[:=]\s*(.*)$', body)
            if k and not body.startswith('-'):
                keys = [(n, key) for n, key in keys if n < ind] + [(ind, k.group(1).replace('"', ''))]
                path = '.'.join(x for _, x in keys)
                value = k.group(2).strip().strip('"\'')
                if (path == 'spring.application.name' or path.endswith('.application.name') and spring) and re.fullmatch(r'[\w.-]+', value):
                    self.svc_names.append((value, rel, i + 1))
                if spring and value:
                    self.spring_props.append((rel, i + 1, path, value))
                if HOSTISH.search(k.group(1)) and re.fullmatch(r'[a-z][a-z0-9-]*[a-z0-9]', value) and value != 'localhost':
                    self.svc_refs.append((rel, i + 1, value, 'bare'))
            key = k.group(1) if k and not body.startswith('-') else None
            if compose and key in ('container_name', 'hostname') and re.fullmatch(r'[\w.-]+', k.group(2).strip().strip('"\'')):
                self.svc_aliases.append((rel, i + 1, k.group(2).strip().strip('"\'')))
            if compose and key == 'aliases' and not k.group(2).strip():
                aliases = ind
                continue
            if aliases is not None and body.startswith('-'):
                self.svc_aliases.append((rel, i + 1, body.lstrip('- ').strip('"\'')))
                continue
            if compose and key == 'ports' and not k.group(2).strip():
                ports = ind
                continue
            if ports is not None and body.startswith('-'):
                pm = re.match(r'''-\s*["']?(?:[\d.]+:)?(\d{2,5})(?:-\d+)?:\d{2,5}''', body)
                if pm:
                    self.svc_ports.append((rel, i + 1, pm.group(1)))
                continue
            if compose:
                inline = re.match(r'(depends_on|links|env_file):\s*\[([^\]]*)\]', body) or re.match(r'(env_file):\s*([^\s#\[][^#]*)$', body)
                if inline:
                    for name in re.findall(r'[\w./:-]+', inline.group(2)):
                        self.compose_ref(rel, i + 1, inline.group(1), name)
                    continue
                block = re.match(r'(depends_on|links|env_file):\s*$', body)
                if block:
                    dep, child, dep_kind = ind, None, block.group(1)
                    continue
                if dep is not None:
                    child = ind if child is None else child
                    item = re.match(r'''-\s*(?:path:\s*)?["']?([\w./:-]+)["']?\s*$''', body) or \
                        (re.match(r'([\w.-]+)\s*:', body) if ind == child and dep_kind == 'depends_on' else None)
                    if item:
                        self.compose_ref(rel, i + 1, dep_kind, item.group(1))
                    continue
            km = re.match(r'-\s*["\']?(?:[\w]+\.)*(\w+)Kt\.(\w+)["\']?\s*$', body)
            if km:
                self.kt_modules.append((rel, i + 1, km.group(1), km.group(2)))
                continue
            if key in HOST_SKIP:
                continue
            value = k.group(2) if key else body.lstrip('- ')
            gw = re.match(r'''-?\s*["']?Path\s*=\s*([^"'\s]+)''', body)
            if gw and uri:
                for path in gw.group(1).split(','):
                    self.gateway_routes.append((rel, i + 1, path, *uri))
                continue
            if body.startswith('- ') and re.match(r'-\s*id\s*:', body):
                uri = None
            for m in HOST_REF.finditer(value):
                host = m.group(2) or m.group(3)
                if host and host not in ('localhost', 'www') and not host.isdigit():
                    self.svc_refs.append((rel, i + 1, host, 'lb' if m.group(1) == 'lb:' else 'url'))
                    if key == 'uri':
                        uri = (host, 'lb' if m.group(1) == 'lb:' else 'url')
            for m in LOCAL_PORT.finditer(value):
                self.port_refs.append((rel, i + 1, m.group(1)))

    def finish_services(self):
        hosts = defaultdict(list)
        for rel, items in self.by_file.items():
            name = rel.rsplit('/', 1)[-1]
            if not name.endswith(('.yml', '.yaml')):
                continue
            compose = name.startswith(('docker-compose', 'compose.')) or rel in self.compose_files
            for _, _, nid in items:
                meta = self.g.nodes[nid]
                if meta['kind'] != 'class':
                    continue
                if compose:
                    hosts[meta['name']].append((1 if name in COMPOSE_MAIN else 0, nid))
                elif '/' in meta['name']:
                    kind, host = meta['name'].split('/', 1)
                    hosts[host].append((1 if kind == 'Service' else 0, nid))
        for host, rel, line in self.svc_names:
            mid = self.module(rel)
            if mid:
                hosts[host].append(('app', mid))
        for host, nid in self.resources:
            hosts[host].append((1, nid))
        for rel, line, alias in sorted(set(self.svc_aliases)):
            nid = self.owner(rel, line)
            if nid and self.g.nodes[nid]['kind'] == 'class' and self.g.nodes[nid]['name'] != alias:
                hosts[alias].append((1 if rel.rsplit('/', 1)[-1] in COMPOSE_MAIN else 0, nid))
        for rel, line, path, host, kind in sorted(set(self.gateway_routes)):
            target = self.service_target(hosts, rel, None, host, kind)
            if target:
                self.endpoint(rel, line, 'ANY', '/' + path.strip('/'), target, index=False)
        for rel, line, host, kind in sorted(set(self.svc_refs)):
            self.link_service(hosts, rel, self.owner(rel, line), host, kind)
        self.finish_service_ids(hosts)
        self.finish_manifest_refs()
        ports = self.service_ports()
        for rel, line, port in sorted(set(self.port_refs)):
            sym = self.owner(rel, line)
            targets = [t for t in ports.get(port, []) if t != sym and self.g.nodes[t]['file'] != rel
                       and not (self.world(rel) == 'manifest' and self.world(self.g.nodes[t]['file']) == 'compose')
                       and not (sym and self.g.nodes[sym]['name'] == self.g.nodes[t]['name'] and self.world(rel) == 'compose')]
            if sym and len(set(targets)) == 1:
                self.g.edge(sym, targets[0], 'depends')
        for rel, line, key in sorted(set(self.config_url_refs)):
            sym = self.owner(rel, line)
            for value in self.prop_values(rel, key):
                for m in HOST_REF.finditer(value):
                    self.link_service(hosts, rel, sym, m.group(2) or m.group(3))
                for m in LOCAL_PORT.finditer(value):
                    targets = [t for t in ports.get(m.group(1), []) if t != sym and self.g.nodes[t]['file'] != rel]
                    if sym and len(set(targets)) == 1:
                        self.g.edge(sym, targets[0], 'depends')
        for rel, line, target in sorted(set(self.env_file_refs)):
            sym, mid = self.owner(rel, line), self.module(target)
            if sym and mid:
                self.g.edge(sym, mid, 'depends')
        for rel, line, cm, key in sorted(set(self.cm_refs)):
            sym, value = self.owner(rel, line), self.cm_values.get((cm, key)) or ''
            for m in HOST_REF.finditer(value):
                self.link_service(hosts, rel, sym, m.group(2) or m.group(3))
        for rel, line, target in sorted(set(self.aspire_refs)):
            sym = self.owner(rel, line)
            if sym and sym != target:
                self.g.edge(sym, target, 'depends')
        for rel, line, stem, fn in sorted(set(self.kt_modules)):
            cands = [n for n in self.short.get(fn, []) if self.g.nodes[n]['file'].endswith(f'/{stem}.kt')]
            target, mid = self.pick(rel, cands), self.module(rel)
            if target and mid:
                self.g.edge(mid, target, 'depends')

    def service_ports(self):
        ports = defaultdict(list)
        for rel, line, port in sorted(set(self.svc_ports)):
            sym = self.owner(rel, line)
            if sym and self.g.nodes[sym]['kind'] == 'class':
                ports[port].append(sym)
        own = {rel: value for rel, line, key, value in self.spring_props if key == 'server.port' and value.isdigit()}
        for name, rel, line in sorted(set(self.svc_names)):
            mid = self.module(rel)
            if mid:
                ports[own.get(rel, '8080')].append(mid)
        return ports

    def prop_values(self, rel, key):
        found = [(shared(rel, r), r, v) for r, line, k, v in self.spring_props if k == key]
        if not found:
            return []
        top = max(s for s, _, _ in found)
        return sorted({v for s, r, v in found if s == top})

    def service_target(self, hosts, rel, sym, host, kind):
        pool = self.service_pool(hosts, rel, sym, host, kind)
        return pool[0] if len(pool) == 1 else self.pick(rel, pool)

    def service_pool(self, hosts, rel, sym, host, kind):
        cands = [((2 if kind == 'lb' else 0) if rank == 'app' else rank, n) for rank, n in hosts.get(host, [])]
        cands = [(rank, n) for rank, n in cands if n != sym
                 and (kind != 'depends' or self.world(self.g.nodes[n]['file']) == 'compose')]
        local = [(rank, n) for rank, n in cands if self.g.nodes[n]['file'] == rel]
        cands = local if local and rel.endswith(('.yml', '.yaml')) and '.override.' not in rel.rsplit('/', 1)[-1] else cands
        world = self.world(rel)
        if world:
            same = [(rank, n) for rank, n in cands if self.world(self.g.nodes[n]['file']) in (world, None)]
            cands = same or cands
        if not cands:
            return []
        top = max(rank for rank, _ in cands)
        return [n for rank, n in cands if rank == top]

    def link_service(self, hosts, rel, sym, host, kind='url'):
        if not sym:
            return
        pool = self.service_pool(hosts, rel, sym, host, kind)
        target = pool[0] if len(pool) == 1 else self.pick(rel, pool) or self.parallel(rel, pool)
        if not target and len(pool) > 1:
            # varias variantes del compose (`docker-compose.dev.yml`, `.prod.yml`...): el fichero principal sin sufijo
            main = [n for n in pool if re.fullmatch(r'(?:docker-)?compose\.ya?ml', self.g.nodes[n]['file'].rsplit('/', 1)[-1])]
            target = main[0] if len(main) == 1 else None
        targets = [target] if target else pool
        if not target and (len(targets) > 3 or any(self.world(self.g.nodes[n]['file']) != 'manifest' for n in targets)):
            return
        for t in targets:
            if self.g.nodes[sym]['name'].rsplit('/', 1)[-1] != host:
                self.g.edge(sym, t, 'depends')

    def parallel(self, rel, pool):
        tail = rel.split('/')[::-1]
        ranked = sorted(((shared('/'.join(tail) + '/x', '/'.join(self.g.nodes[n]['file'].split('/')[::-1]) + '/x'), n) for n in pool),
                        key=lambda x: (-x[0], x[1]))
        return ranked[0][1] if len(ranked) > 1 and ranked[0][0] > ranked[1][0] and ranked[0][0] > 1 else None

    def declare(self, nid, kind, name, rel, line):
        self.g.node(nid, kind=kind, name=name, file=rel, line=line, hash=digest(name))
        mid = self.module(rel)
        if mid:
            self.g.edge(mid, nid, 'contains')
        return nid

    def finish_env(self):
        defined = {env_key(name) for rel, line, name, mid in self.env_defs if not self.is_test(rel)}
        props = defaultdict(list)
        for rel, line, key, value in self.spring_props:
            props[key].append((rel, line))
            var = re.search(r'(?:^|\.)env\.vars\.([A-Za-z_][\w\-]*)$', key)
            if var and self.module(rel):
                self.env_defs.append((rel, line, var.group(1), self.module(rel)))
        defined = {env_key(name) for rel, line, name, mid in self.env_defs if not self.is_test(rel)}
        for folder in sorted({rel.rsplit('/', 1)[0] for rel, _, _, _ in self.spring_props if '/' in rel}):
            for name in SPRING_LOGGING:
                rel = f'{folder}/{name}'
                if rel in self.fileset or not (self.root / rel).is_file() or self.is_test(rel) or not self.is_tracked(rel):
                    continue
                try:
                    text = (self.root / rel).read_text(encoding='utf-8', errors='replace')[:256 * 1024]
                except OSError:
                    continue
                self.xml_reads += [(rel, text.count('\n', 0, m.start()) + 1, m.group(1) or m.group(2)) for m in XML_PROP.finditer(text)]
        for rel, line, key in sorted(set(self.xml_reads)):
            if props.get(key) or env_key(key) in defined:
                if not self.module(rel):
                    self.g.node(f'm:{rel}', kind='module', name=rel.rsplit('/', 1)[-1], file=rel, line=1, lang='xml', hash=digest(rel))
                self.config_reads.append((rel, line, key))
        read = set()
        for rel, line, key in sorted(set(self.config_reads)):
            name = self.config_keys.get(key)
            if name is None:
                found = {v for k, v in self.config_keys.items() if k.endswith('.' + key)}
                name = found.pop() if len(found) == 1 else None
            if name:
                self.env_uses.append((rel, line, name))
            relaxed = env_key(key)
            if props.get(key) or relaxed in defined:
                self.env_uses.append((rel, line, relaxed))
                read.add(key)
        for key, places in props.items():
            relaxed = env_key(key)
            if key in read or relaxed in defined:
                for rel, line in places:
                    mid = self.module(rel)
                    if mid:
                        self.env_defs.append((rel, line, relaxed, mid))
        for rel, line, field in self.settings_reads:
            if field in self.settings_fields:
                self.env_uses.append((rel, line, self.settings_fields[field]))
        used = {env_key(u[2]) for u in self.env_uses + self.soft_env_uses}
        for rel, line, name in sorted(set(self.aspire_env)):
            mid = self.module(rel)
            if mid and env_key(name) in used:
                self.env_defs.append((rel, line, name, mid))
        defined = {env_key(name) for rel, line, name, mid in self.env_defs if not self.is_test(rel)}
        self.env_uses += [u for u in self.soft_env_uses if env_key(u[2]) in defined]
        nodes = {}
        for rel, line, name, mid in sorted(set(self.env_defs)):
            if self.is_test(rel):
                continue
            key = env_key(name)
            if key not in nodes:
                nodes[key] = self.declare(f'v:{name}', 'variable', name, rel, line)
            self.g.edge(mid, nodes[key], 'env')
            sym = self.owner(rel, line)
            if sym and sym != mid and self.g.nodes[sym]['kind'] == 'class' and not rel.endswith(CODE_EXTS):
                self.g.edge(sym, nodes[key], 'env')
        for rel, line, name in sorted(set(self.env_uses), key=lambda x: (self.is_test(x[0]), x)):
            key = env_key(name)
            if key not in nodes:
                if self.is_test(rel):
                    continue
                nodes[key] = self.declare(f'v:{name}', 'variable', name, rel, line)
            sym = self.owner(rel, line)
            if sym and sym.startswith('m:') and rel.endswith(CODE_EXTS):
                sym = self.decl_node(rel, line)
            if sym:
                self.g.edge(sym, nodes[key], 'env')

    def finish_jobs(self):
        for rel, line, name in self.task_calls_js:
            defs = self.task_defs.get(name, [])
            trel = self.js_import_target(self.src(rel, 'js', self.text(rel) or ''), name) if len(defs) > 1 else None
            ids = sorted({i for i, r in defs if trel is None or r == trel})
            if len(ids) == 1:
                self.topic_uses.append((ids[0], rel, line, 'pub', '', 'mq'))
        quals = {q: (rel, line, sup, marker) for rel, line, q, sup, marker in self.rb_classes}
        if not quals:
            return
        tails = defaultdict(list)
        for q in quals:
            parts = q.split('::')
            for i in range(len(parts)):
                tails['::'.join(parts[i:])].append(q)

        def resolve(name, ns=''):
            name = name.lstrip(':')
            parts = ns.split('::') if ns else []
            for i in range(len(parts), 0, -1):
                cand = '::'.join(parts[:i] + [name])
                if cand in quals:
                    return cand
            found = tails.get(name, [])
            return found[0] if len(found) == 1 else None

        def is_job(q, depth=0):
            rel, line, sup, marker = quals[q]
            if marker or depth > 5:
                return marker
            base = resolve(sup, q.rsplit('::', 1)[0] if '::' in q else '') if sup else None
            return bool(base and base != q and is_job(base, depth + 1))

        jobs = {q for q in quals if is_job(q)}
        for q in sorted(jobs):
            rel, line, sup, marker = quals[q]
            short = q.rsplit('::', 1)[-1]
            fns = [n for _, _, n in self.by_file.get(rel, []) if self.g.nodes[n]['kind'] in ('method', 'function')
                   and self.g.nodes[n]['name'].endswith(f'{short}.perform')] or \
                [n for _, _, n in self.by_file.get(rel, []) if self.g.nodes[n]['kind'] in ('method', 'function')
                 and self.g.nodes[n]['name'].endswith(f'{short}.each_iteration')]  # jobs iterables: el cuerpo es cada iteración
            if fns:
                self.topic_uses.append((q, rel, line, 'sub', fns[0], 'mq'))
        for rel, line, const in self.job_calls:
            q = resolve(const)
            if q in jobs:
                self.topic_uses.append((q, rel, line, 'pub', '', 'mq'))
        for rel, line, const in self.job_refs:
            q = resolve(const)
            if q in jobs:
                self.topic_uses.append((q, rel, line, 'sub', '', 'mq'))

    def finish_channels(self):
        mapped, config = [], defaultdict(set)
        for rel, line, key, value in self.spring_props:
            m = MESSAGING_KEY.match(key)
            if not m or self.is_test(rel):
                continue
            direction, channel, attr = (m.group(1), m.group(2), m.group(3)) if m.group(2) else ('', m.group(4), m.group(5))
            if not direction:
                bind = re.match(r'(.+)-(in|out)-\d+$', channel)
                direction = {'in': 'incoming', 'out': 'outgoing'}.get(bind.group(2)) if bind else None
            config[(rel, channel)].add(attr)
            mapped.append((rel, line, direction, channel, attr, value.strip().strip('"\'')))
        topics = defaultdict(list)
        for rel, line, direction, channel, attr, value in mapped:
            if attr in ('topic', 'destination', 'address', 'queue') and re.fullmatch(r'[\w.\-:/]+', value):
                topics[channel].append((rel, value))
        for rel, line, direction, channel, attr, value in mapped:
            named = attr in ('topic', 'destination', 'address', 'queue')
            if direction and (named or attr == 'connector' and not config[(rel, channel)] & {'topic', 'destination', 'address', 'queue'}):
                topic = value if named and re.fullmatch(r'[\w.\-:/]+', value) else channel
                self.topic_uses.append((topic, rel, line, 'sub' if direction == 'incoming' else 'pub', '', 'mq'))
                bind = re.match(r'(.+)-(?:in|out)-\d+$', channel)
                if bind:
                    fns = [n for n in self.short.get(bind.group(1), []) if self.g.nodes[n]['kind'] in ('function', 'method')
                           and self.same_project(rel, self.g.nodes[n]['file'])]
                    fn = fns[0] if len(fns) == 1 else self.pick(rel, fns)
                    if fn:
                        self.topic_uses.append((topic, rel, line, 'sub' if direction == 'incoming' else 'pub', fn, 'mq'))
        for name, rel, line, role, sym in self.channel_uses:
            found = [(shared(rel, r), t) for r, t in topics.get(name, []) if self.same_project(rel, r)]
            top = max((k for k, _ in found), default=None)
            best = sorted({t for k, t in found if k == top})
            self.topic_uses.append((best[0] if len(best) == 1 else name, rel, line, role, sym, 'mq'))

    def finish_topics(self):
        for name, cls, rel in sorted(set(self.event_handlers)):
            for n in self.class_methods(cls, 'file', rel):
                if self.g.nodes[n]['name'].rsplit('.', 1)[-1] in EVENT_METHODS:
                    self.topic_uses.append((name, rel, self.g.nodes[n].get('line') or 1, 'sub', n, 'mq'))
        for name, rel, line in sorted(self.task_calls):
            if name in self.tasks:
                self.topic_uses.append((self.tasks[name], rel, line, 'pub', '', 'mq'))
        uses = sorted(set(self.topic_uses), key=lambda x: (self.is_test(x[1]), x[3] != 'sub', x))
        roles = defaultdict(lambda: defaultdict(set))
        strong = defaultdict(lambda: defaultdict(set))
        for name, rel, line, role, sym, kind in uses:
            roles[(name, kind)][role].add(rel)
            if kind != 'weak':
                strong[name][role].add(rel)
        nodes = {}
        for name, rel, line, role, sym, kind in uses:
            found = roles[(name, kind)]
            pubs, subs = found['pub'] | strong[name]['pub'], found['sub'] | strong[name]['sub']
            if kind == 'emitter' and (not pubs or not subs or len(pubs | subs) < 2):
                continue
            other = 'sub' if role == 'pub' else 'pub'
            if kind == 'weak' and (name in COMMON_EVENTS or len(name) < 3 or not (strong[name][other] or roles[(name, kind)][other])):
                continue
            if name not in nodes:
                if self.is_test(rel):
                    continue
                nodes[name] = self.declare(f't:{name}', 'topic', name, rel, line)
            sym = sym or self.owner(rel, line)
            if sym:
                self.g.edge(*((sym, nodes[name]) if role == 'pub' else (nodes[name], sym)), 'event')

    def finish_endpoints(self):
        self.finish_django()
        for rel, line, name, scope, sym in sorted(set(self.kt_calls)):
            fns = self.kt_route_fns.get(name, [])
            if len(set(fns)) == 1 and fns[0] != sym:
                self.mounts[('sym', fns[0])].append((rel, '', scope, sym))
                self.mount_links.append((rel, line, ('sym', fns[0])))
        nest = sorted(set(self.nest_prefix))
        versioning = sorted(set(self.nest_versioning))
        vprefix, vdefault = versioning[0] if len(versioning) == 1 else (None, None)
        for rel, line, verbs, path, fn, version in self.nest:
            version = vdefault if version is None else version
            vseg = f'{vprefix}{version}/' if vprefix is not None and version and version != 'NEUTRAL' else ''
            self.pending.append((rel, line, '', verbs, (nest[0] + '/' if len(nest) == 1 else '') + vseg + path, fn, '', ''))
        for rel, line, recv, verbs, tpl, handler, scope, sym in sorted(set(self.pending)):
            for pre in self.prefixes(rel, recv, sym, line=line):
                path = norm_path('/'.join(x for x in (pre, scope, tpl) if x))
                for verb, fn in self.expand_handler(verbs, handler):
                    self.endpoint(rel, line, verb, path, fn)
        self.finish_openapi()

    def finish_openapi(self):
        if not self.openapi:
            return
        existing = {(verb, tuple(segs)) for items in self.ep_index.values() for verb, segs, _ in items}
        groups, wanted = defaultdict(set), defaultdict(list)
        for rel, line, verb, path, op, tags in self.openapi:
            for tag in tags[:1] or ('',):
                groups[(rel, tag)].add(rpc_key(op))
        keys = {rpc_key(op) for *_, op, _ in self.openapi}
        for name, nids in self.short.items():
            if rpc_key(name) in keys:
                wanted[rpc_key(name)] += nids
        for rel, line, verb, path, op, tags in sorted(set(self.openapi)):
            path = norm_path(path)
            if (verb, tuple(segments(path))) in existing:
                continue
            group = groups[(rel, tags[0] if tags else '')]
            need = min(2, len(group))
            cands = []
            for n in sorted(set(wanted.get(rpc_key(op), []))):
                meta = self.g.nodes[n]
                if meta['kind'] not in ('function', 'method') or self.is_test(meta['file']) or self.generated(meta['file']) \
                        or not self.same_project(rel, meta['file']):
                    continue
                if meta['kind'] == 'method' and '.' in meta['name']:
                    peers = [m for m in self.owners.get(meta['name'].rsplit('.', 1)[0], []) if self.g.nodes[m]['file'] == meta['file']]
                else:
                    peers = [m for _, _, m in self.by_file.get(meta['file'], []) if self.g.nodes[m]['kind'] == 'function']
                hits = len({rpc_key(self.g.nodes[m]['name'].rsplit('.', 1)[-1]) for m in peers} & group)
                if hits >= need:
                    cands.append((hits, n))
            cands = [(k, n) for k, n in cands if n not in self.declared_clients] or cands
            top = max((k for k, _ in cands), default=0)
            cands = [n for k, n in cands if k == top]
            if len(cands) > 1:
                cands = self.spec_implementors(cands, tags) or cands
            handler = cands[0] if len(cands) == 1 else self.pick(rel, cands)
            if handler:
                self.endpoint(rel, line, verb, path, handler)

    def finish_mounts(self):
        for rel, line, name in sorted(set(self.ext_mounts)):
            cands = [n for n in self.short.get(name, []) if self.g.nodes[n]['kind'] in ('function', 'method')
                     and re.search(rf'\b{re.escape(name)}\s*\(\s*this\b', self.text(self.g.nodes[n]['file']) or '')]
            fn = self.pick(rel, cands)
            if fn:
                self.mount_links.append((rel, line, ('sym', fn)))
        for rel, line, key in sorted(set(self.mount_links)):
            if self.is_test(rel):
                continue
            target = key[1] if key[0] == 'sym' else (self.in_file(key[0], key[1]) if key[1] else None) or self.module(key[0])
            sym = self.owner(rel, line)
            if sym and target and sym != target:
                self.g.edge(sym, target, 'handles')

    def finish_proxies(self):
        if not self.proxies:
            return
        handled = defaultdict(set)
        for a, b, kind in self.g.edges:
            if kind == 'handles' and a.startswith('e:'):
                handled[a].add(b)
        eps = [(segs, nid) for items in self.ep_index.values() for _, segs, nid in items]
        for rel, line, prefix in sorted(set(self.proxies)):
            want = segments(norm_path(prefix))
            if not want or self.is_test(rel):
                continue
            hits = [nid for segs, nid in eps if segs[:len(want)] == want and self.g.nodes[nid]['file'] != rel]
            owners = set()
            for nid in hits:
                for h in handled.get(nid, ()):
                    meta = self.g.nodes[h]
                    short = meta['name'].rsplit('.', 1)[0].rsplit('.', 1)[-1] if '.' in meta['name'] else None
                    cls = [n for _, _, n in self.by_file.get(meta['file'], []) if self.g.nodes[n]['kind'] == 'class'
                           and self.g.nodes[n]['name'].rsplit('.', 1)[-1] == short] if short else []
                    owners.add(cls[0] if len(cls) == 1 else self.module(meta['file']) or h)
            files = {self.g.nodes[n]['file'] for n in hits}
            target = next(iter(owners)) if len(owners) == 1 else (self.module(next(iter(files))) if len(files) == 1 else None)
            if target:
                self.endpoint(rel, line, 'ANY', norm_path(prefix), target, index=False)

    def prefixes(self, rel, recv, sym, depth=0, line=None):
        if depth > 5:
            return ['']
        entry = self.local[rel].get(recv) if recv else None
        hist = self.local_at[rel].get(recv) if recv and line is not None and rel in self.local_at else None
        before = [h for h in hist or () if h[0] <= line]
        if before:
            line, entry = before[-1][0] - 1, before[-1][1:]
        if entry and entry[0] and entry[0] != recv:
            return [p + '/' + entry[1] for p in self.prefixes(rel, entry[0], sym, depth + 1, line)]
        own = entry[1] if entry else ''
        mounts = (self.mounts.get(('sym', sym)) if sym else None) or self.mounts.get((rel, recv)) or self.mounts.get((rel, None)) or []
        base = sorted({p + '/' + lit for r2, v2, lit, s2 in sorted(set(mounts))
                       for p in self.prefixes(r2, v2, s2, depth + 1)})[:3] or ['']
        return [b + '/' + own if own else b for b in base]

    def endpoint(self, rel, line, verb, path, handler, index=True):
        name = f'{verb} {path}'
        nid = f'e:{rel}:{name}'
        if nid not in self.g.nodes:
            mid = self.module(rel)
            self.g.node(nid, kind='endpoint', name=name, file=rel, line=line, lang=self.g.nodes[mid].get('lang') if mid else None,
                        route=name, hash=digest(name))
            if mid:
                self.g.edge(mid, nid, 'contains')
            segs = segments(path)
            if index:
                self.ep_index[segs[-1] if segs else ''].append((verb, segs, nid))
        if handler and handler in self.g.nodes:
            self.g.edge(nid, self.implementation(handler), 'handles')
        return nid

    def generated(self, rel):
        if rel not in self.gen_files:
            head = (self.text(rel) or '')[:1500]
            self.gen_files[rel] = bool(GENERATED.search(head) or GENERATED_NAME.search(rel.rsplit('/', 1)[-1]))
        return self.gen_files[rel]

    def implementation(self, nid):
        meta = self.g.nodes[nid]
        if meta['kind'] != 'method' or not self.generated(meta['file']):
            return nid
        folder = meta['file'].rsplit('/', 1)[0] if '/' in meta['file'] else ''
        name = meta['name'].rsplit('.', 1)[-1]
        cands = [n for n in self.short.get(name, []) if n != nid and self.g.nodes[n]['kind'] == 'method'
                 and (self.g.nodes[n]['file'].rsplit('/', 1)[0] if '/' in self.g.nodes[n]['file'] else '') == folder
                 and not self.generated(self.g.nodes[n]['file'])]
        if len(cands) > 1:
            own = self.param_types(nid)
            scored = sorted(((len(own & self.param_types(c)), c) for c in cands), reverse=True)
            cands = [c for k, c in scored if k == scored[0][0]] if scored[0][0] > scored[1][0] else cands
        return cands[0] if len(cands) == 1 else nid

    def param_types(self, nid):
        meta = self.g.nodes[nid]
        lines = (self.text(meta['file']) or '').split('\n')[(meta.get('line') or 1) - 1:(meta.get('line') or 1) + 2]
        name = re.escape(meta['name'].rsplit('.', 1)[-1])
        m = re.search(rf'\b{name}\s*\(([^)]*)\)', ' '.join(lines))
        return set(re.findall(r'[A-Za-z_][\w.]*', m.group(1))) if m else set()

    def finish_clients(self):
        targets = defaultdict(set)
        strong = set(self.clients)
        strong_lines = set()
        for item in sorted(strong):
            rel, line, method, path, sym = item
            target = self.match(method, segments(path), rel, item in self.based)
            if target:
                self.g.edge(sym, target, 'http')
                targets[sym].add(target)
                strong_lines.add((rel, line))  # un cliente débil en la misma línea sólo cuenta si el fuerte no casó
        for item in sorted(set(self.weak_clients) - strong):
            rel, line, method, path, sym = item
            if (rel, line) in strong_lines:
                continue
            target = self.match(method, segments(path), rel, item in self.based)
            if target and self.g.nodes[target]['file'] != rel:
                self.g.edge(sym, target, 'http')
                targets[sym].add(target)
        wrappers = {}
        for sym, found in targets.items():
            m = self.g.nodes[sym]
            if len(found) == 1 and m['kind'] in ('function', 'method') and (self.generated(m['file']) or sym in self.declared_clients):
                wrappers[sym] = next(iter(found))
        for a, b, kind in sorted(self.g.edges):
            if kind == 'call' and b in wrappers and a in self.g.nodes:
                rel = self.g.nodes[a].get('file') or ''
                if rel != self.g.nodes[b]['file'] and not self.is_test(rel):
                    self.g.edge(a, wrappers[b], 'http')
        self.typed_receivers(wrappers, 'http')

    def typed_receivers(self, wrappers, kind):
        owners = defaultdict(dict)
        for sym, target in wrappers.items():
            meta = self.g.nodes[sym]
            if meta['kind'] == 'method' and '.' in meta['name']:
                cls, name = meta['name'].rsplit('.', 1)
                owners[cls.rsplit('.', 1)[-1]][name] = (target, meta['file'])
        if not owners:
            return
        names = '|'.join(sorted(map(re.escape, owners), key=len, reverse=True))
        decl = re.compile(rf'\b(\w+)\s*:\s*(?:[\w.]+\.)?({names})\b(?!\s*[.(<])|\b(?:[\w.]+\.)?({names})\s+(\w+)\s*[;,)=]|'
                          rf'\b(\w+)\s*=\s*[\w.]*\bcreate\s*\(\s*({names})(?:::class(?:\.java)?|\.class)?\s*\)')
        mention = re.compile(rf'\b(?:{names})\b')
        for rel in self.files:
            lang = EXT_LANG.get(os.path.splitext(rel)[1])
            if lang not in ('java', 'kt', 'cs', 'js', 'c', 'py', 'go', 'rs', 'php') or self.is_test(rel):
                continue
            text = self.text(rel)
            if not text or len(text) > 512 * 1024 or not mention.search(text):
                continue
            src = None
            for m in decl.finditer(text):
                var, cls = (m.group(1), m.group(2)) if m.group(1) else (m.group(4), m.group(3)) if m.group(3) else (m.group(5), m.group(6))
                methods = owners[cls]
                if any(f == rel for _, f in methods.values()):
                    continue
                src = src or self.src(rel, lang, text)
                for call in re.finditer(rf'(?<![\w$])(?:this\.|self\.|self->|\$this->)?{re.escape(var)}\s*\??[.]\s*(\w+)\s*\(', src.code):
                    hit = methods.get(call.group(1))
                    sym = self.owner(rel, src.line(call.start())) if hit else None
                    if sym and sym != hit[0]:
                        self.g.edge(sym, hit[0], kind)

    def match(self, method, csegs, rel=None, based=False):
        best = self.match_all(method, csegs, prefer=based)
        if not best and (based or any(re.search(r'[._-]', s) for s in csegs[-1:])):
            best = self.match_all(method, csegs, 1, prefer=based)
            return best[0] if len(best) == 1 else None
        if len(best) > 1 and rel:
            ranked = sorted(((shared(rel, self.g.nodes[n]['file']), n) for n in best), key=lambda x: (-x[0], x[1]))
            best = [n for k, n in ranked if k == ranked[0][0]]
            if len(best) > 1 and len({self.g.nodes[n]['file'] for n in best}) == 1:
                best = [min(best, key=lambda n: (self.g.nodes[n].get('line') or 0, n))]
        return best[0] if len(best) == 1 else None

    def match_all(self, method, csegs, min_lits=2, prefer=False):
        last = csegs[-1] if csegs else ''
        pool = self.ep_index.get(last, []) + (self.ep_index.get(':', []) if last not in (':', '') else [])
        best, top = [], None
        for verb, esegs, nid in pool:
            if verb != method and 'ANY' not in (verb, method):
                continue
            n = min(len(esegs), len(csegs))
            lits, ok = 0, True
            for a, b in zip(esegs[len(esegs) - n:], csegs[len(csegs) - n:]):
                if a == ':':
                    continue
                if b == ':' or a != b:
                    ok = False
                    break
                lits += 1
            if not ok or (lits == 0 and (esegs or csegs)):
                continue
            if len(esegs) == len(csegs):
                tier = 3
            elif len(csegs) > len(esegs):
                tier = 2
            elif ':' in esegs[:len(esegs) - n] or lits < min_lits:
                continue
            else:
                tier = 1
            # con base desconocida (`${base}x`) manda el número de segmentos literales y, a igualdad, el menor prefijo extra
            score = (lits, tier, verb == method, -abs(len(esegs) - len(csegs))) if prefer else (tier, lits, verb == method)
            if top is None or score > top:
                top, best = score, [nid]
            elif score == top:
                best.append(nid)
        return sorted(set(best))

    def finish_rpc(self):
        for rel, line, cls, folder in sorted(set(self.grpc_regs)):
            cands = [n for n in self.short.get(cls, []) if self.g.nodes[n]['kind'] == 'class'
                     and (folder is None or self.g.nodes[n]['file'].startswith(folder))]
            impl = self.pick(rel, cands)
            sym = self.owner(rel, line)
            if impl and sym and not self.is_test(rel):
                self.g.edge(sym, impl, 'handles')
                svc = self.grpc_impls.get((cls, self.g.nodes[impl]['file']))
                if svc and folder is None and not rel.endswith('.go'):
                    self.grpc_wiring.append((rel, line, svc))
        for rel, line, eid in sorted(set(self.rpc_pending)):
            sym = self.owner(rel, line)
            if sym:
                self.g.edge(sym, eid, 'rpc')
        for rel, line, svc in sorted(set(self.grpc_clients)):
            sym = self.owner(rel, line)
            impls = [n for (cls, frel), s2 in sorted(self.grpc_impls.items()) if s2 == svc
                     for _, _, n in self.by_file.get(frel, []) if self.g.nodes[n]['kind'] == 'class' and self.g.nodes[n]['name'] == cls]
            impl = impls[0] if len(impls) == 1 else self.pick(rel, impls)
            if sym and impl and not self.is_test(rel):
                self.g.edge(sym, impl, 'rpc')
        for rel, line, svc in sorted(set(self.grpc_wiring)):
            sym = self.owner(rel, line)
            if sym and not self.is_test(rel):
                for eid in sorted(set(self.services.get(svc, {}).values())):
                    self.g.edge(sym, eid, 'rpc')
        if self.proto_routes:
            handled = defaultdict(set)
            for a, b, kind in self.g.edges:
                if kind == 'handles' and a.startswith('e:'):
                    handled[a].add(b)
            for hid, eid in self.proto_routes:
                for target in sorted(handled.get(eid, ())):
                    self.g.edge(hid, target, 'handles')


def link_bridges(root, files, g, issues, read_source):
    from .analyze import is_test
    Bridges(root, files, g, read_source, is_test, issues).run()
